INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 1, '宴山亭·裁剪冰绡', 'songci-sc-127', '裁剪冰绡轻叠数重淡著胭脂匀注新样靓妆艳溢香融羞杀蕊珠宫女易得凋零更多少无情风雨愁苦闲院落凄凉几回春暮凭寄离恨重重这双燕何曾会人言语天遥地远万水千山知他故宫何处怎不思量除梦里有时曾去无据和梦也新来不做', '杏花像裁剪好的洁白薄绸，轻轻叠成几层，又淡淡地抹上胭脂。它妆饰新巧，艳丽芳香，连蕊珠宫里的仙女见了也自愧不如。可这花偏偏容易凋谢，更禁不起多少无情的风雨。愁苦之中，我在这凄凉的院落里，春天已经过去几回了？
我想托燕子捎去重重离恨，可这双燕又怎么会懂得人话。天遥地远，隔着万水千山，谁知故国的宫殿如今在哪里。怎能不思念，只是除了梦里，有时还能回去一趟。如今连这点凭据也没有了——连梦，近来也不肯做了。', 'public-domain'),
  ('songci300', 2, '木兰花·城上风光莺语乱', 'songci-sc-2', '城上风光莺语乱城下烟波春拍岸绿杨芳草几时休泪眼愁肠先已断情怀渐觉成衰晚鸾镜朱颜惊暗换昔年多病厌芳尊今日芳尊惟恐浅', '城上春光烂漫，黄莺的叫声乱成一片；城下烟波浩渺，春水拍打着堤岸。绿杨芳草年年如此，什么时候才有个了结？我泪眼愁肠，早已断尽。
心情渐渐感到衰颓迟暮，对镜一照，惊见红润的容颜暗暗换了模样。从前多病，见了酒杯就厌烦；如今却只怕杯中的酒太浅。', 'public-domain'),
  ('songci300', 3, '苏幕遮·碧云天', 'songci-sc-3', '碧云天黄叶地秋色连波波上寒烟翠山映斜阳天接水芳草无情更在斜阳外黯乡魂追旅思夜夜除非好梦留人睡明月楼高休独倚酒入愁肠化作相思泪', '碧蓝的天，枯黄的地，秋色连着水波，波上笼着翠色的寒烟。远山映着斜阳，水天相接；无情的芳草，一直铺到斜阳之外。
思乡的心黯然销魂，羁旅的愁绪缠着不放，除非夜夜有好梦留人安睡。明月当空，不要独自倚在高楼上；酒入愁肠，只会化作相思的眼泪。', 'public-domain'),
  ('songci300', 4, '御街行·纷纷坠叶飘香砌', 'songci-sc-4', '纷纷坠叶飘香砌夜寂静寒声碎真珠帘卷玉楼空天淡银河垂地年年今夜月华如练长是人千里愁肠已断无由醉酒未到先成泪残灯明灭枕头欹谙尽孤眠滋味都来此事眉间心上无计相回避', '纷纷飘落的树叶堆在带香气的台阶上。夜很静，细碎的寒声不断。珍珠帘卷起，玉楼空寂，天色清淡，银河低垂到地面。年年今夜，月光像白练一样明净，而人总是远隔千里。
愁肠已经断尽，无从借酒麻醉；酒还没到嘴边，先化成了泪。残灯忽明忽暗，斜靠着枕头，孤独失眠的滋味尝了个够。算来这份愁思，无论在眉间还是心上，都没有办法回避。', 'public-domain'),
  ('songci300', 5, '渔家傲·塞下秋来风景异', 'poems-cz9-18', '塞下秋来风景异衡阳雁去无留意四面边声连角起千嶂里长烟落日孤城闭浊酒一杯家万里燕然未勒归无计羌管悠悠霜满地人不寐将军白发征夫泪', '边塞的秋天一来，风景就大不相同，大雁向衡阳飞去，毫不留恋。四面八方的边声随着号角响起，重重山峦之中，长烟升腾，落日低垂，孤城紧闭。一杯浊酒遥寄万里之外的家乡，可是边患未平、功业未成，归乡无从谈起。羌笛悠悠，寒霜满地，人们难以入睡，将军白了头发，征夫流下眼泪。', 'school'),
  ('songci300', 6, '千秋岁·数声鶗鴂', 'songci-sc-6', '数声鶗鴂又报芳菲歇惜春更选残红折雨轻风色暴梅子青时节永丰柳无人尽日花飞雪莫把幺弦拨怨极弦能说天不老情难绝心似双丝网中有千千结夜过也东窗未白凝残月', '几声杜鹃啼叫，又报告春天已经过去。因惜春，我特意挑一枝残花折下。雨点轻而风力猛，正是梅子发青的时节。永丰坊的柳树无人过问，整日飘着如雪的柳絮。
不要拨动那根细弦，怨到极处时，琴弦会把心事都说出来。天不会老，情也难断绝。心像双丝结成的网，中间有千千万万个结。夜已经过去了，东窗未白，只留着一弯残月。', 'public-domain'),
  ('songci300', 7, '菩萨蛮·哀筝一弄湘江曲', 'songci-sc-7', '哀筝一弄湘江曲声声写尽湘波绿纤指十三弦细将幽恨传当筵秋水慢玉柱斜飞雁弹到断肠时春山眉黛低', '古筝哀怨地弹起一支湘江曲，声声都化作湘江的绿水。纤细的手指按着十三根弦，细细地把深藏的幽恨传出来。
筵席上，她的目光像秋水一样缓缓流动，弦柱像斜飞的雁行。弹到最伤心的地方，双眉微低，像笼着春山的黛色。', 'public-domain'),
  ('songci300', 8, '醉垂鞭·双蝶绣罗裙', 'songci-sc-8', '双蝶绣罗裙东池宴初相见朱粉不深匀闲花淡淡春细看诸处好人人道柳腰身昨日乱山昏来时衣上云', '罗裙上绣着一对蝴蝶，那是在东池的宴席上初次相见。脸上的脂粉抹得很淡，像闲花淡淡地开着，自有一段春意。
细细看去，处处都好；人人都说，她的腰身像柳枝一样细。昨日黄昏乱山模糊，她来时衣上仿佛带着云彩。', 'public-domain'),
  ('songci300', 9, '一丛花·伤高怀远几时穷', 'songci-sc-9', '伤高怀远几时穷无物似情浓离愁正引千丝乱更东陌飞絮濛濛嘶骑渐遥征尘不断何处认郎踪双鸳池沼水溶溶南北小桡通梯横画阁黄昏后又还是斜月帘栊沉恨细思不如桃杏犹解嫁东风', '登高伤怀、思念远人，什么时候才到尽头？没有什么比情更浓的东西了。离愁正引得千丝万缕纷乱，何况东边路上，飞絮迷蒙。嘶鸣的马越走越远，扬起的尘土不断，我到哪里去认他的行踪？
池水溶溶，有双鸳鸯嬉戏，南北的小船相通。黄昏后，画阁上梯子横放着，又还是那一钩斜月照着窗帘。深恨之中细细想来，还不如桃花杏花——它们还懂得嫁给东风。', 'public-domain'),
  ('songci300', 10, '天仙子·水调数声持酒听', 'songci-sc-10', '水调数声持酒听午醉醒来愁未醒送春春去几时回临晚镜伤流景往事后期空记省沙上并禽池上暝云破月来花弄影重重帘幕密遮灯风不定人初静明日落红应满径', '端着酒听了几声《水调》，午间醉倒，醒来后愁还没醒。送走了春天，春天什么时候再回来？傍晚对镜，感伤时光流逝，往事与日后的约期都白白记在心里。
沙上成双的水鸟栖息，池边天色昏暝；云开月出，花在月下摆弄影子。层层帘幕密密遮住灯光，风还在吹，人刚刚静下来，料想明天落花该铺满小径了。', 'public-domain'),
  ('songci300', 11, '青门引·乍暖还轻冷', 'songci-sc-11', '乍暖还轻冷风雨晚来方定庭轩寂寞近清明残花中酒又是去年病楼头画角风吹醒入夜重门静那堪更被明月隔墙送过秋千影', '天气刚刚转暖，又有些微冷；风雨到傍晚才停。庭院冷清，将近清明，对着残花喝闷酒，又犯去年一样的病。
城楼上的画角声被风吹来，把人吹醒；入夜后重重门户一片寂静。更叫人受不了的是，明月还把隔墙那边的秋千影子送了过来。', 'public-domain'),
  ('songci300', 12, '生查子·含羞整翠鬟', 'songci-sc-12', '含羞整翠鬟得意频相顾雁柱十三弦一一春莺语娇云容易飞梦断知何处深院锁黄昏阵阵芭蕉雨', '她含着羞整理乌黑的鬓发，又得意地频频回头。筝上十三根弦、十三根雁柱，一声声都像春天的黄莺在啼。
娇美的云彩容易飘散，梦断之后不知人在何处。深深的院落锁住了黄昏，只听见一阵阵雨打芭蕉。', 'public-domain'),
  ('songci300', 13, '浣溪沙·一曲新词酒一杯', 'songci-sc-13', '一曲新词酒一杯去年天气旧亭台夕阳西下几时回无可奈何花落去似曾相识燕归来小园香径独徘徊', '唱一支新填的词，饮一杯酒，天气还是去年的天气，亭台还是旧日的亭台。夕阳西下，什么时候才能回来？
花儿落去，谁也无可奈何；燕子归来，好像是旧时相识。我独自在小园的花径上徘徊。', 'public-domain'),
  ('songci300', 14, '浣溪沙·一向年光有限身', 'songci-sc-14', '一向年光有限身等闲离别易销魂酒筵歌席莫辞频满目山河空念远落花风雨更伤春不如怜取眼前人', '一年的时光有限，人的身体也有限，寻常的离别最叫人伤感。酒席歌筵，不要嫌它太频繁。
满眼山河，白白地思念远方；落花风雨，更添伤春之情。不如好好珍惜眼前的人。', 'public-domain'),
  ('songci300', 15, '清平乐·红笺小字', 'songci-sc-15', '红笺小字说尽平生意鸿雁在云鱼在水惆怅此情难寄斜阳独倚西楼遥山恰对帘钩人面不知何处绿波依旧东流', '红色信笺上写满小字，把平生的心意都说了。可鸿雁在高云、游鱼在水底，这份情意无处寄送，只令人惆怅。
斜阳里独自倚着西楼，远山正对着帘钩。那张熟悉的脸不知去了哪里，只有绿波依旧向东流去。', 'public-domain'),
  ('songci300', 16, '清平乐·金风细细', 'songci-sc-16', '金风细细叶叶梧桐坠绿酒初尝人易醉一枕小窗浓睡紫薇朱槿花残斜阳却照阑干双燕欲归时节银屏昨夜微寒', '秋风细细地吹，梧桐叶一片片落下。新酿的酒初尝容易醉，在小窗下枕着睡了一场。
紫薇和朱槿都已凋残，斜阳又照在栏杆上。正是双燕将要南归的时节，昨夜银屏后已有些微寒。', 'public-domain'),
  ('songci300', 17, '木兰花·燕鸿过后莺归去', 'songci-sc-17', '燕鸿过后莺归去细算浮生千万绪长于春梦几多时散似秋云无觅处闻琴解佩神仙侣挽断罗衣留不住劝君莫作独醒人烂醉花间应有数', '燕子大雁先后北去南来，黄莺也归去了；细算这一生，千头万绪。相聚比起春梦来能长多少？一散开就像秋云，无处可寻。
不论是闻琴知音的卓文君，还是解佩相赠的神女，扯断了罗衣也留不住。劝你不要做独醒的人，在花丛中痛饮大醉，也是命中注定。', 'public-domain'),
  ('songci300', 18, '木兰花·绿杨芳草长亭路', 'songci-sc-18', '绿杨芳草长亭路年少抛人容易去楼头残梦五更钟花底离愁三月雨无情不似多情苦一寸还成千万缕天涯地角有穷时只有相思无尽处', '绿杨芳草，长亭古道，年少的人轻易离我而去。楼头的残梦被五更的钟声惊醒，花下的离愁像三月的细雨。
无情不像有情那样苦，一寸相思还会化成千万缕。天涯地角总有尽头，只有相思没有尽头。', 'public-domain'),
  ('songci300', 19, '木兰花·池塘水绿风微暖', 'songci-sc-19', '池塘水绿风微暖记得玉真初见面重头歌韵响铮琮入破舞腰红乱旋玉钩阑下香阶畔醉后不知斜日晚当时共我赏花人点检如今无一半', '池塘水绿，微风送暖，记得初见她的那一天。她重头唱来，歌声铮琮动听；入破时舞动腰肢，红裙旋转纷乱。
在玉钩栏杆下、香阶旁边，醉后不觉太阳已经西斜。当年与我一同赏花的人，如今数一数，不到一半了。', 'public-domain'),
  ('songci300', 20, '踏莎行·碧海无波', 'songci-sc-20', '碧海无波瑶台有路思量便合双飞去当时轻别意中人山长水远知何处绮席凝尘香闺掩雾红笺小字凭谁附高楼目尽欲黄昏梧桐叶上萧萧雨', '碧海没有波浪，瑶台自有道路，想来本应双双飞去。当初轻易离别了心上人，如今山长水远，不知她在何处。
华美的席上积了尘，闺房笼着雾。写了小字的红笺，还能托谁送去？在高楼上望尽天涯，天色将晚，梧桐叶上已响起萧萧的雨声。', 'public-domain'),
  ('songci300', 21, '踏莎行·小径红稀', 'songci-sc-21', '小径红稀芳郊绿遍高台树色阴阴见春风不解禁杨花濛濛乱扑行人面翠叶藏莺朱帘隔燕炉香静逐游丝转一场愁梦酒醒时斜阳却照深深院', '小路上花已稀少，郊野芳草绿遍，高台的树色在朦胧中显出。春风不懂得管束杨花，让它迷迷蒙蒙地乱扑行人的脸。
绿叶里藏着黄莺，红帘外隔着燕子，炉香静静地随着游丝旋转。一场愁梦酒醒的时候，斜阳正照着深深的庭院。', 'public-domain'),
  ('songci300', 22, '蝶恋花·六曲阑干偎碧树', 'songci-sc-332', '六曲阑干偎碧树杨柳风轻展尽黄金缕谁把钿筝移玉柱穿帘海燕双飞去满眼游丝兼落絮红杏开时一霎清明雨浓睡觉来莺乱语惊残好梦无寻处', '六曲栏杆围着碧绿的树，杨柳风轻，柳条已绽出金黄的嫩丝。是谁把钿筝的玉柱移换，弹出新调？燕子穿过帘幕双双飞去。
满眼是游丝和飞絮，红杏开时，一场清明的急雨。浓睡醒来，莺声乱啼，惊破了我的好梦，再也无处寻觅。', 'public-domain'),
  ('songci300', 23, '凤箫吟·锁离愁', 'songci-sc-23', '锁离愁连绵无际来时陌上初熏绣帏人念远暗垂珠露泣送征轮长行长在眼更重重远水孤云但望极楼高尽日目断王孙销魂池塘别后曾行处绿妒轻裙恁时携素手乱花飞絮里缓步香茵朱颜空自改向年年芳意长新遍绿野嬉游醉眼莫负青春', '芳草锁住离愁，连绵无边；来时路上，草香初起。绣帘中的人思念远行的人，暗暗垂下露珠般的泪，哭着送走远行的车轮。车马走远了，仍在眼中，更有重重远水和孤云。只能登上高楼极目远望，整日望到看不见行人。
伤心啊。池塘一别之后，她走过的地方，绿草都嫉妒她轻软的罗裙。那时牵着她的素手，在乱花飞絮中缓步走在香草地上。如今红颜白白地改变，而芳草年年依旧新绿。让它绿遍原野吧，纵情游乐、醉眼相看，不要辜负了青春。', 'public-domain'),
  ('songci300', 24, '木兰花·东城渐觉风光好', 'songci-sc-24', '东城渐觉风光好縠皱波纹迎客棹绿杨烟外晓寒轻红杏枝头春意闹浮生长恨欢娱少肯爱千金轻一笑为君持酒劝斜阳且向花间留晚照', '城东的风光渐渐好起来，像绉纱一样的水波迎着游船。绿杨笼在轻烟里，清晨的寒意很轻；红杏枝头上，春意热闹非凡。
人生浮沉，常恨欢乐太少，怎肯吝惜千金而看轻一笑？我为你端着酒去劝斜阳：暂且留在花间，多照一会儿吧。', 'public-domain'),
  ('songci300', 25, '采桑子·群芳过后西湖好', 'songci-sc-25', '群芳过后西湖好狼籍残红飞絮濛濛垂柳阑干尽日风笙歌散尽游人去始觉春空垂下帘栊双燕归来细雨中', '百花凋谢之后，西湖反而更好看：落花狼藉，柳絮迷蒙，垂柳拂着栏杆，整天吹着风。
笙歌散尽，游人离去，这才觉得春天空了。放下帘子，看一双燕子在细雨中归来。', 'public-domain'),
  ('songci300', 26, '诉衷情·清晨帘幕卷轻霜', 'songci-sc-26', '清晨帘幕卷轻霜呵手试梅妆都缘自有离恨故画作远山长思往事惜流芳易成伤拟歌先敛欲笑还颦最断人肠', '清晨卷起帘幕，外面落着轻霜；呵暖手，试着画梅花妆。都因为心中自有离恨，所以把眉画得像远山一样长。
回想往事，惋惜流逝的芳华，最容易伤心。想唱歌先收起笑意，要笑又皱起眉头，最叫人断肠。', 'public-domain'),
  ('songci300', 27, '踏莎行·候馆梅残', 'songci-sc-27', '候馆梅残溪桥柳细草薰风暖摇征辔离愁渐远渐无穷迢迢不断如春水寸寸柔肠盈盈粉泪楼高莫近危阑倚平芜尽处是春山行人更在春山外', '驿馆旁梅花凋残，溪桥边柳丝细长，草香风暖，他摇着马缰上路。离愁随着路程渐远而无穷无尽，像春水一样迢迢不断。
一寸寸柔肠，一行行粉泪；楼虽高，也别靠近栏杆去倚。平坦的原野尽头是春山，而远行的人还在春山之外。', 'public-domain'),
  ('songci300', 28, '蝶恋花·庭院深深深几许', 'songci-sc-28', '庭院深深深几许杨柳堆烟帘幕无重数玉勒雕鞍游冶处楼高不见章台路雨横风狂三月暮门掩黄昏无计留春住泪眼问花花不语乱红飞过秋千去', '庭院深深，深到什么程度？杨柳堆着烟雾，帘幕一层又一层。他骑着玉勒雕鞍的马在外游乐，我登上高楼也望不见那条章台路。
风狂雨横，正是三月将尽。黄昏掩上门，也没有办法把春天留住。含着泪问花，花不回答；纷乱的落花飘过秋千飞走了。', 'public-domain'),
  ('songci300', 29, '蝶恋花·谁道闲情抛弃久', 'songci-sc-29', '谁道闲情抛弃久每到春来惆怅还依旧日日花前常病酒不辞镜里朱颜瘦河畔青芜堤上柳为问新愁何事年年有独立小桥风满袖平林新月人归后', '谁说闲愁已经被抛下很久了？每到春天来，惆怅还是老样子。天天在花前喝醉，也不推辞镜子里红颜一天天消瘦。
河畔的青草、堤上的柳树，我问它们：新的愁为什么年年都有？我独自站在小桥上，风吹满衣袖；平展的树林上升起新月，人已归去。', 'public-domain'),
  ('songci300', 30, '蝶恋花·几日行云何处去', 'songci-sc-333', '几日行云何处去忘却归来不道春将暮百草千花寒食路香车系在谁家树泪眼倚楼频独语双燕来时陌上相逢否撩乱春愁如柳絮依依梦里无寻处', '那片游云几日之间飘到哪里去了？忘了回来，也不管春天将尽。寒食路旁百草千花，你的香车系在了谁家的树上？
含泪倚楼，一再自言自语：双燕飞来时，路上可曾遇见他？撩乱的春愁像柳絮一样纷飞，只能在依稀的梦里，却也无处可寻。', 'public-domain'),
  ('songci300', 31, '木兰花·别后不知君远近', 'songci-sc-334', '别后不知君远近触目凄凉多少闷渐行渐远渐无书水阔鱼沉何处问夜深风竹敲秋韵万叶千声皆是恨故敧单枕梦中寻梦又不成灯又烬', '分别以后不知你走得多远，满眼凄凉，说不尽的烦闷。你越走越远，越远越没有书信，水面辽阔、鱼儿深沉，到哪里去打听？
夜深了，风吹竹林敲出秋声，万叶千声都是怨恨。我斜靠着孤枕想在梦里寻你，梦没有做成，灯又烧成了灰。', 'public-domain'),
  ('songci300', 32, '浪淘沙·把酒祝东风', 'songci-sc-32', '把酒祝东风且共从容垂杨紫陌洛城东总是当时携手处游遍芳丛聚散苦匆匆此恨无穷今年花胜去年红可惜明年花更好知与谁同', '举酒向东风祝愿：暂且从容一些。洛阳城东的垂杨大道上，都是当年我们携手同游、走遍花丛的地方。
聚散总是匆匆，这恨没有尽头。今年的花比去年红；可惜明年花更好，又知道能与谁一同观赏！', 'public-domain'),
  ('songci300', 33, '青玉案·一年春事都来几', 'songci-sc-33', '一年春事都来几早过了三之二绿暗红嫣浑可事绿杨庭院暖风帘幕有个人憔悴买花载酒长安市又争似家山见桃李不枉东风吹客泪相思难表梦魂无据惟有归来是', '一年的春事算起来有多少？早已过了三分之二。绿荫浓、红花艳，都还算好景；绿杨的庭院，暖风吹动帘幕，可有一个人憔悴着。
在长安城里买花载酒，又怎比得上在家乡看桃李。东风吹落客子的泪也不算白吹——相思难以表达，梦魂没有凭据，只有回去才是正理。', 'public-domain'),
  ('songci300', 34, '曲玉管·陇首云飞', 'songci-sc-34', '陇首云飞江边日晚烟波满目凭阑久一望关河萧索千里清秋忍凝眸杳杳神京盈盈仙子别来锦字终难偶断雁无凭冉冉飞下汀洲思悠悠暗想当初有多少幽欢佳会岂知聚散难期翻成雨恨云愁阻追游每登山临水惹起平生心事一场消黯永日无言却下层楼', '山顶云飞，江边日落，满眼烟波，我倚着栏杆站了很久。望出去关山河川一片萧索，千里清秋，怎忍心一直看下去。遥远的京城，那位盈盈的佳人，别后连书信也难得相通。失群的孤雁没有凭据，缓缓飞下汀洲，我的思念悠悠无尽。
暗自回想当初，有多少幽会欢聚，哪里知道聚散难以预期，反而变成云雨般的愁恨。想追寻旧游而不可得。每次登山临水，都惹起平生心事，一场黯然消魂，整天说不出一句话，只好走下高楼。', 'public-domain'),
  ('songci300', 35, '雨霖铃·寒蝉凄切', 'songci-sc-35', '寒蝉凄切对长亭晚骤雨初歇都门帐饮无绪留恋处兰舟催发执手相看泪眼竟无语凝噎念去去千里烟波暮霭沉沉楚天阔多情自古伤离别更那堪冷落清秋节今宵酒醒何处杨柳岸晓风残月此去经年应是良辰好景虚设便纵有千种风情更与何人说', '寒蝉叫得凄切，面对长亭，已是傍晚，一阵急雨刚停。在京城门外设帐饯别，毫无心绪；正留恋时，船上催着出发。握着手互相看着泪眼，竟哽噎得说不出一句话。想到这一去，千里烟波，暮霭沉沉，楚地天空辽阔。
自古多情的人最伤离别，更哪堪在这冷落的清秋时节！今夜酒醒时人在何处？只有杨柳岸边、晓风残月。这一去经年累月，良辰美景也都形同虚设。纵然有千种风情，又向谁诉说？', 'public-domain'),
  ('songci300', 36, '蝶恋花·伫倚危楼风细细', 'songci-sc-36', '伫倚危楼风细细望极春愁黯黯生天际草色烟光残照里无言谁会凭阑意拟把疏狂图一醉对酒当歌强乐还无味衣带渐宽终不悔为伊消得人憔悴', '久立在高楼上，微风细细；望到天边，春愁黯然从那里生出。草色与烟光笼在残照里，我默默无言，谁能懂得我倚栏的心意。
本想放纵一场，图个一醉；对着酒唱歌，勉强作乐还是没滋味。衣带渐渐宽松也始终不悔，为了她，人瘦了也值得。', 'public-domain'),
  ('songci300', 37, '采莲令·月华收', 'songci-sc-37', '月华收云淡霜天曙西征客此时情苦翠娥执手送临歧轧轧开朱户千娇面盈盈伫立无言有泪断肠争忍回顾一叶兰舟便恁急桨凌波去贪行色岂知离绪万般方寸但饮恨脉脉同谁语更回首重城不见寒江天外隐隐两三烟树', '月华收尽，云淡霜天，天将破晓。西行的旅人，此时心里最苦。她握着我的手送到岔路口，朱红门户轧轧打开。千娇百媚的脸，盈盈地站着，说不出话，只有泪；我肝肠寸断，怎忍回头再看。
一叶兰舟，就这样飞快地划桨凌波而去。只顾着赶路，哪里懂得离愁别绪；千般滋味堵在心口，只能含恨，脉脉之情向谁诉说。再回头，重重城郭已看不见，寒江之外，天边隐隐只有两三株烟树。', 'public-domain'),
  ('songci300', 38, '浪淘沙慢·梦觉透窗风一线', 'songci-sc-38', '梦觉透窗风一线寒灯吹息那堪酒醒又闻空阶夜雨频滴嗟因循久作天涯客负佳人几许盟言便忍把从前欢会陡顿翻成忧戚愁极再三追思洞房深处几度饮散歌阑香暖鸳鸯被岂暂时疏散费伊心力殢云尤雨有万般千种相怜相惜恰到如今天长漏永无端自家疏隔知何时却拥秦云态愿低帏昵枕轻轻细说与江乡夜夜数寒更思忆', '梦醒时一线风透进窗来，把寒灯吹灭了。更难受的是酒醒之后，又听见空台阶上夜雨滴滴答答。可叹我因循蹉跎，长久在外做天涯客，辜负了佳人多少盟誓，竟忍心把从前的欢会，一下子翻成忧愁。
愁到极处，再三追想：在洞房深处，有好几次饮罢歌残，香暖的鸳鸯被里。哪里是暂时的分别，实在费了她的心力。那时如云似雨，千种万般，互相怜惜。
到了如今，天长夜永，无缘无故地自己疏远了。不知何时才能重新拥着那如云的情态，愿在低垂的帷幕、贴身的枕上，轻轻地细细说给她听：在江乡的每一夜，我数着寒更思念你。', 'public-domain'),
  ('songci300', 39, '定风波·自春来', 'songci-sc-39', '自春来惨绿愁红芳心是事可可日上花梢莺穿柳带犹压香衾卧暖酥消腻云亸终日厌厌倦梳裹无那恨薄情一去音书无个早知恁么悔当初不把雕鞍锁向鸡窗只与蛮笺象管拘束教吟课镇相随莫抛躲针线闲拈伴伊坐和我免使年少光阴虚过', '自从春天来了，绿叶凄惨、红花含愁，我心里对什么事都提不起劲。太阳升上花梢，黄莺在柳条间穿飞，我还赖在香被里躺着。肌肤消瘦，鬓发松垂，整天懒懒地不愿梳妆。无可奈何，只恨那薄情的人一去，连一封信也没有。
早知如此，后悔当初没有把他的马鞍锁住。让他在书房里，只用纸笔，拘着让他吟诗作文。要一直相随，不许躲开；闲时拈着针线陪他坐着。与我在一起，免得把这青春的年少光阴白白虚度。', 'public-domain'),
  ('songci300', 40, '少年游·长安古道马迟迟', 'songci-sc-40', '长安古道马迟迟高柳乱蝉嘶夕阳岛外秋风原上目断四天垂归云一去无踪迹何处是前期狎兴生疏酒徒萧索不似少年时', '长安古道上，马儿慢吞吞地走，高柳上乱蝉嘶鸣。夕阳在岛屿之外，秋风起在原野上，望到天边，四面天幕低垂。
归云一去没有踪迹，从前的约期又在哪里？冶游的兴致已生疏，酒友也已零落，再不像少年时候了。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 41, '戚氏·晚秋天', 'songci-sc-41', '晚秋天一霎微雨洒庭轩槛菊萧疏井梧零乱惹残烟凄然望江关飞云黯淡夕阳闲当时宋玉悲感向此临水与登山远道迢递行人凄楚倦听陇水潺湲正蝉吟败叶蛩响衰草相应喧喧孤馆度日如年风露渐变悄悄至更阑长天净绛河清浅皓月婵娟思绵绵夜永对景那堪屈指暗想从前未名未禄绮陌红楼往往经岁迁延帝里风光好当年少日暮宴朝欢况有狂朋怪侣遇当歌对酒竞留连别来迅景如梭旧游似梦烟水程何限念利名憔悴长萦绊追往事空惨愁颜漏箭移稍觉轻寒渐呜咽画角数声残对闲窗畔停灯向晓抱影无眠', '晚秋天气，一阵小雨洒在庭院。栏杆旁的菊花稀疏，井边的梧桐零乱，惹起残烟。心里凄然，望向江关，飞云黯淡，夕阳悠闲。当年宋玉的悲感，正是在这样的地方临水登山。远路迢迢，行人凄楚，听厌了陇头流水的潺潺声。正当蝉在败叶间鸣，蟋蟀在衰草里叫，相互应和，一片喧闹。
独宿孤馆，度日如年；风露渐渐变冷，悄悄到了更深夜尽。长空澄净，银河清浅，皓月美好。思绪绵绵，长夜对着这景致，怎堪扳着指头回想从前。没有功名，没有俸禄，只在绮陌红楼里，往往一混就是一年。
京城风光好，当年年少时，朝朝暮暮宴饮欢乐。何况有一群狂放的朋友，遇到当歌对酒的场合就争着留连。别来光阴快得像梭子，旧游如梦，烟水茫茫，路程哪里有个尽头。想那名利，把人熬得憔悴，长久地缠住不放。追想往事，只是白白地满面愁惨。漏箭移动，渐渐觉得有些轻寒。画角声渐次呜咽，几声之后断了。对着闲窗，熄了灯守到天亮，抱着影子无法入睡。', 'public-domain'),
  ('songci300', 42, '夜半乐·冻云黯淡天气', 'songci-sc-42', '冻云黯淡天气扁舟一叶乘兴离江渚渡万壑千岩越溪深处怒涛渐息樵风乍起更闻商旅相呼片帆高举泛画鹢翩翩过南浦望中酒旆闪闪一簇烟村数行霜树残日下渔人鸣榔归去败荷零落衰杨掩映岸边两两三三浣纱游女避行客含羞笑相语到此因念绣阁轻抛浪萍难驻叹后约丁宁竟何据惨离怀空恨岁晚归期阻凝泪眼杳杳神京路断鸿声远长天暮', '寒云黯淡的天气，一叶小舟乘兴离开江边。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，顺风忽然吹起，又听见商旅互相招呼。一片船帆高高扬起，画着鹢鸟的船翩翩驶过南浦。
远望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰柳掩映，岸边三三两两，是浣纱的游女。她们避开行人，含羞地笑着说话。
看到这里，就想起自己轻易抛下了绣阁，像浮萍一样漂泊难停。可叹临别时千叮万嘱的约期，究竟有什么凭据。离怀凄惨，白白怨恨岁暮归期受阻。含着泪眼，望那遥远的京城路。孤雁声远去，长天已暮。', 'public-domain'),
  ('songci300', 43, '玉蝴蝶·望处雨收云断', 'songci-sc-43', '望处雨收云断凭阑悄悄目送秋光晚景萧疏堪动宋玉悲凉水风轻苹花渐老月露冷梧叶飘黄遣情伤故人何在烟水茫茫难忘文期酒会几孤风月屡变星霜海阔山遥未知何处是潇湘念双燕难凭远信指暮天空识归航黯相望断鸿声里立尽斜阳', '望去雨收云散，我静静地倚着栏杆，目送秋光。晚景萧疏，足以触动宋玉那样的悲凉。水风轻，苹花渐渐老去；月露冷，梧桐叶飘黄。惹人伤情的是：故人在哪里？只见烟水茫茫。
难以忘怀。当年的文期酒会，多少次辜负了风月，星霜屡屡变换。海阔山遥，不知哪里才是潇湘。想托双燕，又难以递送远信；指着暮天，白白辨认归帆。黯然相望，在孤雁声中，一直站到斜阳落尽。', 'public-domain'),
  ('songci300', 44, '八声甘州·对潇潇暮雨洒江天', 'songci-sc-44', '对潇潇暮雨洒江天一番洗清秋渐霜风凄紧关河冷落残照当楼是处红衰翠减苒苒物华休惟有长江水无语东流不忍登高临远望故乡渺邈归思难收叹年来踪迹何事苦淹留想佳人妆楼颙望误几回天际识归舟争知我倚阑干处正恁凝愁', '面对着潇潇暮雨洒遍江天，一番雨把清秋洗得更净。霜风渐渐凄紧，关河冷落，残阳照在楼上。到处红花衰败、绿叶凋减，美好的景物渐渐消歇。只有长江水，默默地向东流。
不忍登高望远，望故乡渺茫遥远，归思难以收住。可叹这些年来的行踪，为什么苦苦滞留他乡？想那佳人正在妆楼上抬头凝望，多少次把天边的船误认作我的归舟。她怎知道，我在倚栏的地方，正这样凝着愁。', 'public-domain'),
  ('songci300', 45, '迷神引·一叶扁舟轻帆卷', 'songci-sc-45', '一叶扁舟轻帆卷暂泊楚江南岸孤城暮角引胡笳怨水茫茫平沙雁旋惊散烟敛寒林簇画屏展天际遥山小黛眉浅旧赏轻抛到此成游宦觉客程劳年光晚异乡风物忍萧索当愁眼帝城赊秦楼阻旅魂乱芳草连空阔残照满佳人无消息断云远', '一片轻帆卷起，小舟暂泊在楚江南岸。孤城响起暮角，引出胡笳哀怨。江水茫茫，平沙上的大雁转眼被惊散。烟雾收敛，寒林成簇，像展开的画屏。天边的远山很小，像浅浅的黛眉。
轻易抛下了从前的欢赏，到这里做了游宦。觉得客途劳顿，年光已晚。异乡的风物，怎忍心在这愁眼前一片萧索。京城遥远，秦楼阻隔，旅人的心魂纷乱。芳草连着辽阔的天空，残照洒满。佳人没有消息，像断云一样远去了。', 'public-domain'),
  ('songci300', 46, '竹马子·登孤垒荒凉', 'songci-sc-46', '登孤垒荒凉危亭旷望静临烟渚对雌霓挂雨雄风拂槛微收烦暑渐觉一叶惊秋残蝉噪晚素商时序览景想前欢指神京非雾非烟深处向此成追感新愁易积故人难聚凭高尽日凝伫赢得消魂无语极目霁霭霏微暝鸦零乱萧索江城暮南楼画角又送残阳去', '登上荒凉的孤垒，在高亭上远望，静静地面对烟雾中的洲渚。只见雌霓挂着雨，大风拂着栏杆，稍稍收去了闷热。渐渐觉得一片落叶惊动了秋意，残蝉在傍晚噪鸣，已是秋天的时序。看着这景致想起从前的欢乐，遥指京城，在非雾非烟的深处。
在这里生出追怀之感，新愁容易堆积，故人难以相聚。登高整日凝立，只落得黯然无语。极目望去，雨后的云气迷蒙，暮鸦零乱，江城的黄昏一片萧索。南楼上的画角，又把残阳送走了。', 'public-domain'),
  ('songci300', 47, '桂枝香·登临送目', 'poems-gz10-18', '登临送目正故国晚秋天气初肃千里澄江似练翠峰如簇归帆去棹残阳里背西风酒旗斜矗彩舟云淡星河鹭起画图难足念往昔繁华竞逐叹门外楼头悲恨相续千古凭高对此谩嗟荣辱六朝旧事随流水但寒烟衰草凝绿至今商女时时犹唱后庭遗曲', '登上高处向远处眺望，正是故都金陵的晚秋时节，天气开始变得肃杀。千里澄澈的长江像一条白练，青翠的山峰像箭簇一样聚集。江中归来的船帆和离去的船桨沐浴在残阳里，背着西风，酒旗斜斜地竖着。彩绘的船只在淡云中，银河般的长江上白鹭飞起，这样的美景图画也难以画尽。回想往昔，人们竞相追逐繁华，可叹隋兵已临城下，陈后主还在楼头寻欢作乐，悲恨接连不断。千古以来登高凭吊，徒然感叹荣辱兴亡。六朝的旧事已随流水逝去，只剩寒烟衰草凝着一片绿色。至今歌女还时时唱着《玉树后庭花》那亡国之音。', 'school'),
  ('songci300', 48, '千秋岁引·别馆寒砧', 'songci-sc-48', '别馆寒砧孤城画角一派秋声入寥廓东归燕从海上去南来雁向沙头落楚台风庾楼月宛如昨无奈被些名利缚无奈被他情担阁可惜风流总闲却当初谩留华表语而今误我秦楼约梦阑时酒醒后思量着', '别馆里的寒砧声，孤城上的画角声，一派秋声散入空阔的天空。东归的燕子从海上飞去，南来的大雁落在沙头。楚王的兰台之风、庾亮的南楼之月，宛然如昨。
无奈被那点名利缠住，无奈被那点人情耽搁，可惜风流都白白闲却了。当初白白留下华表上的话，如今又误了我秦楼的约会。梦醒的时候，酒醒以后，反复思量着。', 'public-domain'),
  ('songci300', 49, '清平乐·留春不住', 'songci-sc-49', '留春不住费尽莺儿语满地残红宫锦污昨夜南园风雨小怜初上琵琶晓来思绕天涯不肯画堂朱户春风自在杨花', '留不住春天，白白费尽黄莺的啼叫。满地落花像弄脏了的宫锦——昨夜南园下了风雨。
小怜刚刚弹起琵琶，天亮时思绪已绕着天涯飞。它不肯待在画堂朱户里，春风中只有杨花自在地飞。', 'public-domain'),
  ('songci300', 50, '临江仙·梦后楼台高锁', 'songci-sc-50', '梦后楼台高锁酒醒帘幕低垂去年春恨却来时落花人独立微雨燕双飞记得小蘋初见两重心字罗衣琵琶弦上说相思当时明月在曾照彩云归', '梦醒后楼台高锁，酒醒后帘幕低垂。去年的春恨又在此时涌上心头。落花中我独自站立，微雨里燕子双双飞过。
记得初次见到小蘋时，她穿着绣有两重心字的罗衣。琵琶弦上诉说着相思。当时的明月还在，曾照着她像彩云一样归去。', 'public-domain'),
  ('songci300', 51, '蝶恋花·醉别西楼醒不记', 'songci-sc-51', '醉别西楼醒不记春梦秋云聚散真容易斜月半窗还少睡画屏闲展吴山翠衣上酒痕诗里字点点行行总是凄凉意红烛自怜无好计夜寒空替人垂泪', '醉别西楼，醒来已不记得；春梦秋云，聚散真是容易。斜月照进半窗，还是睡不着；画屏闲开着，展开一片吴山的翠色。
衣上的酒痕、诗里的字，点点行行，都是凄凉的意思。红烛自怜没有好办法，在寒夜里白白替人垂泪。', 'public-domain'),
  ('songci300', 52, '蝶恋花·梦入江南烟水路', 'songci-sc-52', '梦入江南烟水路行尽江南不与离人遇睡里消魂无说处觉来惆怅消魂误欲尽此情书尺素浮雁沉鱼终了无凭据却倚缓弦歌别绪断肠移破秦筝柱', '梦里走进江南的烟水之路，走遍江南，也没遇上那离别的人。睡梦里的消魂无处诉说，醒来惆怅，才知消魂是误。
想把这份情都写进信里，可雁飞高空、鱼沉水底，终究没有凭据。只好靠着缓弦唱起别绪，唱到断肠，把秦筝的柱子都移破了。', 'public-domain'),
  ('songci300', 53, '鹧鸪天·彩袖殷勤捧玉钟', 'songci-sc-53', '彩袖殷勤捧玉钟当年拚却醉颜红舞低杨柳楼心月歌尽桃花扇底风从别后忆相逢几回魂梦与君同今宵剩把银釭照犹恐相逢是梦中', '她穿着彩袖殷勤地捧起玉杯，当年我甘愿喝得满脸通红。舞到杨柳楼头的月亮低下去，唱到桃花扇底的清风停息。
自从分别以后，回想相逢，多少回梦魂与你相同。今夜只管举着银灯照了又照，还怕这次相逢也是梦里。', 'public-domain'),
  ('songci300', 54, '生查子·关山魂梦长', 'songci-sc-54', '关山魂梦长鱼雁音尘少两鬓可怜青只为相思老归梦碧纱窗说与人人道真个别离难不似相逢好', '关山阻隔，魂梦悠长；书信稀少，音信难通。两鬓原本可爱的黑发，只因为相思而变白。
梦里回到碧纱窗前，对那人说：离别真是难，不如相逢好。', 'public-domain'),
  ('songci300', 55, '木兰花·秋千院落重帘暮', 'songci-sc-55', '秋千院落重帘暮彩笔闲来题绣户墙头丹杏雨余花门外绿杨风后絮朝云信断知何处应作襄王春梦去紫骝认得旧游踪嘶过画桥东畔路', '秋千院落里重重帘幕垂到黄昏，闲来用彩笔在绣户上题字。墙头的红杏是雨后残花，门外的绿杨是风后飞絮。
朝云般的她音信断绝，不知在哪里？大概随着襄王的春梦去了。紫骝马认得旧日游踪，嘶鸣着跑过画桥东边的路。', 'public-domain'),
  ('songci300', 56, '木兰花·小颦若解愁春暮', 'songci-sc-56', '小颦若解愁春暮一笑留春春也住晚红初减谢池花新翠已遮隋堤树谁知错管春残事到处登临曾费泪此时金盏直须深看尽落花能几醉', '小颦若能懂得为春暮发愁，那么她一笑留春，春天也会停住。晚红刚刚从谢家池边的花上减退，新绿已经遮住隋堤的树。
谁知道白白操心了春残的事，处处登临都曾费了不少眼泪。此时金杯正该斟得深些——看尽落花，还能醉几回？', 'public-domain'),
  ('songci300', 57, '清平乐·留人不住', 'songci-sc-57', '留人不住醉解兰舟去一棹碧涛春水路过尽晓莺啼处渡头杨柳青青枝枝叶叶离情此后锦书休寄画楼云雨无凭', '留不住人，他醉中解开兰舟离去。一桨划进碧涛春水，驶过所有黄莺啼叫的地方。
渡头的杨柳青青，枝枝叶叶都是离情。从今以后不必再寄书信了，画楼里的欢会本来就没有凭据。', 'public-domain'),
  ('songci300', 58, '阮郎归·天边金掌露成霜', 'songci-sc-58', '天边金掌露成霜云随雁字长绿杯红袖趁重阳人情似故乡兰佩紫菊簪黄殷勤理旧狂欲将沉醉换悲凉清歌莫断肠', '天边仙人掌上的承露盘结了霜，云随着雁行拉得很长。绿杯红袖趁着重阳欢聚，人情的温暖竟像在故乡。
佩上紫色的兰，簪上黄色的菊，殷勤地重理旧日的狂放。想用沉醉换掉悲凉，清歌一曲莫要唱断人肠。', 'public-domain'),
  ('songci300', 59, '阮郎归·旧香残粉似当初', 'songci-sc-59', '旧香残粉似当初人情恨不如一春犹有数行书秋来书更疏衾凤冷枕鸳孤愁肠待酒舒梦魂纵有也成虚那堪和梦无', '旧日的香气、残余的脂粉还像当初，可人情却恨不如从前。春天还有几行书信，入秋以后信更稀了。
凤被冷，鸳枕孤，愁肠只能等酒来舒展。梦魂纵然有也是空的，更哪堪连梦也没有。', 'public-domain'),
  ('songci300', 60, '六幺令·绿阴春尽', 'songci-sc-60', '绿阴春尽飞絮绕香阁晚来翠眉宫样巧把远山学一寸狂心未说已向横波觉画帘遮匝新翻曲妙暗许闲人带偷掐前度书多隐语意浅愁难答昨夜诗有回文韵险还慵押都待笙歌散了记取来时霎不消红蜡闲云归后月在庭花旧阑角', '绿荫浓了，春天将尽，飞絮绕着香阁。傍晚时她眉画成宫中的样子，巧妙地学着远山。一寸狂热的心还没说出口，已在眼波里被人察觉。画帘四面遮着，新翻的曲子精妙，暗暗允许闲人偷学指法。
上次来信多藏隐语，用意浅而愁绪难答。昨夜的诗是回文体，韵太险也懒得押。都等笙歌散了，记住她来时的刹那。不必点红蜡——闲云归去之后，月亮还照在庭中花下旧栏杆的角上。', 'public-domain'),
  ('songci300', 61, '御街行·街南绿树春饶絮', 'songci-sc-61', '街南绿树春饶絮雪满游春路树头花艳杂娇云树底人家朱户北楼闲上疏帘高卷直见街南树阑干倚尽犹慵去几度黄昏雨晚春盘马踏青苔曾傍绿阴深驻落花犹在香屏空掩人面知何处', '街南绿树成荫，春天柳絮很多，像雪铺满游春的路。树梢上繁花与娇云相杂，树下有人家的朱门。闲来登上北楼，把疏帘高高卷起，一直望见街南的树。
把栏杆倚遍还懒得离开，几番黄昏都下着雨。晚春时曾骑马踏过青苔，在绿荫下久久停留。如今落花还在，香屏空掩，那张熟悉的脸不知去了何处。', 'public-domain'),
  ('songci300', 62, '虞美人·曲阑干外天如水', 'songci-sc-62', '曲阑干外天如水昨夜还曾倚初将明月比佳期长向月圆时候望人归罗衣着破前香在旧意谁教改一春离恨懒调弦犹有两行闲泪宝筝前', '曲栏杆外天色如水，昨夜我还曾倚在这里。起初把明月比作佳期，总在月圆的时候盼望人归来。
罗衣穿破了，从前的香气还在；旧日的情意，是谁教它改的？一春的离恨，懒得去调弦，却还有两行无端的热泪，落在宝筝前面。', 'public-domain'),
  ('songci300', 63, '留春令·画屏天畔', 'songci-sc-63', '画屏天畔梦回依约十洲云水手捻红笺寄人书写无限伤春事别浦高楼曾漫倚对江南千里楼下分流水声中有当日凭高泪', '画屏上远接天边，梦醒时依稀还在十洲的云水之间。手里捻着红笺给人写信，写不尽伤春的心事。
在离别的江边高楼上曾随意倚过，面对着千里江南。楼下分流的水声里，还留着当日登高洒下的眼泪。', 'public-domain'),
  ('songci300', 64, '思远人·红叶黄花秋意晚', 'songci-sc-64', '红叶黄花秋意晚千里念行客飞云过尽归鸿无信何处寄书得泪弹不尽临窗滴就砚旋研墨渐写到别来此情深处红笺为无色', '红叶黄花，秋意已晚，我思念千里之外的行人。飞云过尽，归雁也不带信，书信能寄到哪里去？
眼泪弹不尽，临窗滴落，就着砚台随即研墨。渐渐写到别后的事，情深处，红笺都褪了颜色。', 'public-domain'),
  ('songci300', 65, '水调歌头·明月几时有', 'songci-sc-65', '明月几时有把酒问青天不知天上宫阙今夕是何年我欲乘风归去又恐琼楼玉宇高处不胜寒起舞弄清影何似在人间转朱阁低绮户照无眠不应有恨何事长向别时圆人有悲欢离合月有阴晴圆缺此事古难全但愿人长久千里共婵娟', '明月是什么时候才有的？我端起酒杯问青天。不知道天上的宫殿，今夜是哪一年。我想乘风回去，又怕琼楼玉宇太高，受不住那份寒冷。起身起舞，戏弄自己的影子，哪里比得上人间。
月光转过朱红楼阁，低低地照进雕花窗户，照着不能入睡的人。明月不该有什么怨恨，为什么总在离别时团圆？人有悲欢离合，月有阴晴圆缺，这种事自古难以周全。只愿人长久平安，虽隔千里，也能共赏这轮明月。', 'public-domain'),
  ('songci300', 66, '水龙吟·似花还似非花', 'songci-sc-66', '似花还似非花也无人惜从教坠抛家傍路思量却是无情有思萦损柔肠困酣娇眼欲开还闭梦随风万里寻郎去处又还被莺呼起不恨此花飞尽恨西园落红难缀晓来雨过遗踪何在一池萍碎春色三分二分尘土一分流水细看来不是杨花点点是离人泪', '像花又不像花，也没有人怜惜，任它飘落。它离开枝头、依傍路旁，想来看似无情，其实有情。它缠绕着、折损着柔肠，困倦中娇眼欲开还闭。梦里随着风飘到万里之外，去找那人的去处，却又被黄莺啼醒。
不恨这花飞尽，只恨西园的落花难以再连缀。清晨雨过，它的踪迹在哪里？化作一池碎萍。春色若有三分，二分归了尘土，一分随了流水。细细看来，那不是杨花，一点一点都是离人的泪。', 'public-domain'),
  ('songci300', 67, '念奴娇·大江东去', 'poems-gz10-07', '大江东去浪淘尽千古风流人物故垒西边人道是三国周郎赤壁乱石穿空惊涛拍岸卷起千堆雪江山如画一时多少豪杰遥想公瑾当年小乔初嫁了雄姿英发羽扇纶巾谈笑间樯橹灰飞烟灭故国神游多情应笑我早生华发人生如梦一尊还酹江月', '大江浩浩荡荡向东流去，巨浪淘尽了千百年来所有杰出的英雄人物。旧的营垒西边，人们说，那就是三国时周瑜大战赤壁的地方。陡峭的乱石直插云霄，惊人的巨浪拍打着江岸，卷起千万堆雪白的浪花。江山美得像一幅画，一时之间涌现出多少英雄豪杰。遥想当年周瑜，小乔刚刚嫁给他，他英姿勃发。手执羽扇，头戴纶巾，谈笑之间，强敌的战船就灰飞烟灭。神游于三国故地，应该笑我多愁善感，过早地生出白发。人生就像一场梦，还是把一杯酒洒向江中的明月吧。', 'academic'),
  ('songci300', 68, '永遇乐·明月如霜', 'songci-sc-68', '明月如霜好风如水清景无限曲港跳鱼圆荷泻露寂寞无人见紞如三鼓铿然一叶黯黯梦云惊断夜茫茫重寻无处觉来小园行遍天涯倦客山中归路望断故园心眼燕子楼空佳人何在空锁楼中燕古今如梦何曾梦觉但有旧欢新怨异时对黄楼夜景为余浩叹', '明月如霜，好风如水，清景无边。曲港里鱼跳，圆荷上露珠泻落，寂寞无人看见。三更鼓响，一片落叶铿然，把梦一般的美好惊醒，心中黯然。夜色茫茫，重新寻找已无踪迹，醒来后把小园走了个遍。
我是天涯倦客，望着山中的归路，望断了故园的心眼。燕子楼已空，佳人何在？只白白锁着楼中的燕子。古今如梦，何曾有人梦醒？只有旧欢新怨。日后有人面对黄楼的夜景，也会替我长叹。', 'public-domain'),
  ('songci300', 69, '洞仙歌·冰肌玉骨', 'songci-sc-69', '冰肌玉骨自清凉无汗水殿风来暗香满绣帘开一点明月窥人人未寝欹枕钗横鬓乱起来携素手庭户无声时见疏星渡河汉试问夜如何夜已三更金波淡玉绳低转但屈指西风几时来又不道流年暗中偷换', '冰一样的肌肤、玉一样的骨，自然清凉无汗。水殿上风吹来，暗暗满是香气。绣帘掀开，一点明月来窥人；人还未睡，斜靠着枕头，金钗横斜、鬓发零乱。
起身牵着她的素手，庭院寂静无声，不时看见稀疏的星子渡过银河。试问夜到什么时辰了？已过三更，月光淡了，玉绳星低低转动。只是扳着手指算西风几时来，却没料到流年已在暗中偷偷换了。', 'public-domain'),
  ('songci300', 70, '卜算子·缺月挂疏桐', 'poems-cz8-28', '缺月挂疏桐漏断人初静谁见幽人独往来缥缈孤鸿影惊起却回头有恨无人省拣尽寒枝不肯栖寂寞沙洲冷', '弯弯的月亮挂在稀疏的梧桐树上，漏壶的水已经滴尽，人声刚刚静下来。谁见到幽居的人独自往来，仿佛那缥缈的孤雁的身影。它突然惊起又回过头来，心中有怨恨却无人能理解。它把寒冷的树枝都挑遍了也不肯栖宿，甘愿在寂寞凄冷的沙洲上独宿。', 'academic'),
  ('songci300', 71, '青玉案·三年枕上吴中路', 'songci-sc-71', '三年枕上吴中路遣黄耳随君去若到松江呼小渡莫惊鸥鹭四桥尽是老子经行处辋川图上看春暮常记高人右丞句作个归期天已许春衫犹是小蛮针线曾湿西湖雨', '三年梦里都想着回吴中的路。派黄犬随你归去。若到松江叫小渡船，不要惊动鸥鹭；四桥一带，都是我走过的地方。
在《辋川图》上看春暮的景致，常记得王维那样高人写的句子。定下归期，老天已经答应了。身上的春衫还是小蛮亲手缝的，曾被西湖的雨打湿过。', 'public-domain'),
  ('songci300', 72, '临江仙·夜饮东坡醒复醉', 'songci-sc-72', '夜饮东坡醒复醉归来仿佛三更家童鼻息已雷鸣敲门都不应倚杖听江声长恨此身非我有何时忘却营营夜阑风静縠纹平小舟从此逝江海寄余生', '夜里在东坡饮酒，醒了又醉，回来时仿佛已三更。家童鼾声如雷，敲门都不应，只好拄着拐杖听江声。
常恨这身子不属于自己，什么时候才能忘掉那些营营碌碌？夜深风静，水面像绉纱一样平。就乘一叶小舟从此远去，把余生寄托在江海之间。', 'public-domain'),
  ('songci300', 73, '定风波·莫听穿林打叶声', 'songci-sc-73', '莫听穿林打叶声何妨吟啸且徐行竹杖芒鞋轻胜马谁怕一蓑烟雨任平生料峭春风吹酒醒微冷山头斜照却相迎回首向来萧瑟处归去也无风雨也无晴', '不要去听那穿林打叶的雨声，不妨一边吟诗长啸一边慢慢走。竹杖草鞋比骑马还轻快，怕什么？披一件蓑衣，任凭一生风雨。
料峭的春风吹醒了酒意，有些微冷；山头的斜阳却迎面照来。回头看看方才风雨萧瑟的地方——回去吧，也无所谓风雨，也无所谓晴。', 'public-domain'),
  ('songci300', 74, '江城子·十年生死两茫茫', 'poems-gz11-07', '十年生死两茫茫不思量自难忘千里孤坟无处话凄凉纵使相逢应不识尘满面鬓如霜夜来幽梦忽还乡小轩窗正梳妆相顾无言惟有泪千行料得年年肠断处明月夜短松冈', '你我夫妻诀别已经整整十年，纵然不去刻意思念，也自然是难以忘怀。你的孤坟远在千里，没有地方能与你诉说心中的凄凉。即使相逢你也应该认不出我了，我已风尘满面，两鬓如霜。昨夜在幽幽的梦中忽然回到了故乡，看见你正在小窗前梳妆。我们相视无言，只有泪水流了千行。想来年年令我肝肠寸断的地方，就是那明月之夜、矮松冈上你的坟茔。', 'academic'),
  ('songci300', 75, '木兰花·霜余已失长淮阔', 'songci-sc-76', '霜余已失长淮阔空听潺潺清颍咽佳人犹唱醉翁词四十三年如电抹草头秋露流珠滑三五盈盈还二八与余同是识翁人惟有西湖波底月', '霜降之后，淮河已失了宽阔的气象，只听见清颍河潺潺如咽。歌女还在唱醉翁的词，四十三年像闪电一抹就过去了。
草尖上的秋露像滚动的珠，月儿十五圆满、十六也还圆。与我一样认识醉翁的人，只有西湖水底的月亮。', 'public-domain'),
  ('songci300', 76, '贺新郎·乳燕飞华屋', 'songci-sc-74', '乳燕飞华屋悄无人桐阴转午晚凉新浴手弄生绡白团扇扇手一时似玉渐困倚孤眠清熟帘外谁来推绣户枉教人梦断瑶台曲又却是风敲竹石榴半吐红巾蹙待浮花浪蕊都尽伴君幽独秾艳一枝细看取芳心千重似束又恐被秋风惊绿若待得君来向此花前对酒不忍触共粉泪两簌簌', '小燕飞过华屋，悄无人声，桐荫转过午后，傍晚凉爽，她刚沐浴过。手里把着生绡白团扇，扇子与手一时都像玉。渐渐困倦，斜倚着独自睡熟。帘外是谁来推绣户？白白教人从瑶台的仙梦里惊醒——却又只是风敲竹子。
石榴花半开，像蹙起的红巾。等那些浮花浪蕊都谢尽，它来陪伴你的幽独。细看那一枝浓艳，芳心千重，像被束住。又怕被秋风惊落绿叶。若等到你来时，面对花前饮酒也不忍触碰；那时花与粉泪，一同簌簌落下。', 'public-domain'),
  ('songci300', 77, '鹧鸪天·黄菊枝头生晓寒', 'songci-sc-78', '黄菊枝头生晓寒人生莫放酒杯干风前横笛斜吹雨醉里簪花倒著冠身健在且加餐舞裙歌板尽清欢黄花白发相牵挽付与时人冷眼看', '黄菊枝头带着清晨的寒意，人生在世不要让酒杯空着。风前横吹笛子，斜吹着雨；醉里簪花，帽子倒戴着。
身体还康健，就多吃些饭；舞裙歌板，尽情享受清欢。黄花与白发互相牵挽，随世人冷眼看去吧。', 'public-domain'),
  ('songci300', 78, '定风波·万里黔中一漏天', 'songci-sc-79', '万里黔中一漏天屋居终日似乘船及至重阳天也霁催醉鬼门关外蜀江前莫笑老翁犹气岸君看几人黄菊上华颠戏马台南追两谢驰射风流犹拍古人肩', '万里之外的黔中像天漏了一样，整日住在屋里像坐在船上。到了重阳，天也放晴了，就催人喝酒——在鬼门关外的蜀江边。
不要笑老翁还这样意气傲岸，你看，有几个人能把黄菊插上白头？在戏马台南追慕谢瞻、谢灵运；纵马驰射，风流还能与古人并肩。', 'public-domain'),
  ('songci300', 79, '清平乐·春归何处', 'poems-xx6-14', '春归何处寂寞无行路若有人知春去处唤取归来同住春无踪迹谁知除非问取黄鹂百啭无人能解因风飞过蔷薇', '春天回到了哪里？一片寂寞，找不到它的踪迹。如果谁知道春天去了哪里，请叫它回来同住。谁知道春天却没有人知道它在何处，除非去问黄鹂。黄鹂百般啼叫，没有人能听懂它的意思，它便随着风势飞过蔷薇花去了。', 'school'),
  ('songci300', 80, '阮郎归·烹茶留客驻金鞍', 'songci-sc-335', '烹茶留客驻金鞍月斜窗外山别郎容易见郎难有人愁远山归去后忆前欢画屏金博山一杯春露莫留残与郎扶玉山', '煮茶留客，让他的金鞍马停下；月亮斜照窗外，映出远山。离别情郎容易，再见情郎却难，有人对着远山发愁。
回去以后，回想从前的欢会，画屏上画着金博山炉。这一杯春露似的酒不要剩下一点，让我扶你醉倒的身躯。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 81, '绿头鸭·晚云收', 'songci-sc-82', '晚云收淡天一片琉璃烂银盘来从海底皓色千里澄辉莹无尘素娥淡伫静可数丹桂参差玉露初零金风未凛一年无似此佳时露坐久疏萤时度乌鹊正南飞瑶台冷阑干凭暖欲下迟迟念佳人音尘别后对此应解相思最关情漏声正永暗断肠花影偷移料得来宵清光未减阴晴天气又争知共凝恋如今别后还是隔年期人强健清尊素影长愿相随', '晚云收尽，淡淡的天像一片琉璃。银盘般的月亮从海底升起，皎洁的光千里澄明。它晶莹无尘，嫦娥静静地伫立；静得可以数清参差的丹桂。玉露初降，秋风还不冷，一年中没有比这更好的时候。我在露下久坐，疏疏的萤火不时飞过，乌鹊正向南飞。
瑶台清冷，栏杆却倚得暖了，想下去又迟迟不动。想那佳人在别后音信断绝，面对这月色也该懂得相思。最牵动心肠的是漏声正长，暗暗断肠的是花影偷移。料想明夜清光不会减，可阴晴天气又怎么预料？彼此凝恋，如今别后，还得再等一年。只愿人常康健，清酒与素影长久相随。', 'public-domain'),
  ('songci300', 82, '蝶恋花·欲减罗衣寒未去', 'songci-sc-83', '欲减罗衣寒未去不卷珠帘人在深深处红杏枝头花几许啼痕止恨清明雨尽日沉烟香一缕宿酒醒迟恼破春情绪飞燕又将归信误小屏风上西江路', '想减一件罗衣，寒意还没退去；不卷珠帘，人在深院深处。红杏枝头开了多少花？泪痕里只恨清明时节的雨。
整日只有一缕沉香烟，昨夜的酒醒得迟，搅坏了春天的情绪。飞燕又把归来的信误了，小屏风上画着通往西江的路。', 'public-domain'),
  ('songci300', 83, '踏莎行·雾失楼台', 'songci-sc-84', '雾失楼台月迷津渡桃源望断无寻处可堪孤馆闭春寒杜鹃声里斜阳暮驿寄梅花鱼传尺素砌成此恨无重数郴江幸自绕郴山为谁流下潇湘去', '雾遮住了楼台，月色迷失了渡口，望断桃源也找不到。孤馆紧闭，春寒难耐，杜鹃声里斜阳西下。
驿站寄来梅花，鱼腹传来书信，却把这恨堆砌得无法计数。郴江本自绕着郴山流，如今又是为谁流到潇湘去呢？', 'public-domain'),
  ('songci300', 84, '望海潮·梅英疏淡', 'songci-sc-85', '梅英疏淡冰澌溶泄东风暗换年华金谷俊游铜驼巷陌新晴细履平沙长记误随车正絮翻蝶舞芳思交加柳下桃蹊乱分春色到人家西园夜饮鸣笳有华灯碍月飞盖妨花兰苑未空行人渐老重来是事堪嗟烟暝酒旗斜但倚楼极目时见栖鸦无奈归心暗随流水到天涯', '梅花稀疏淡了，冰块溶化流去，东风暗暗换了年华。金谷园的名胜、铜驼街的巷陌，新晴时细步走在平沙上。常记得错跟了别人的车。那时柳絮翻飞、蝴蝶飞舞，芳心交杂。柳下桃径，把春色乱分到各家。
西园夜里饮酒吹笳。华灯挡住月亮，飞驰的车盖妨碍看花。兰苑还没有空，行人却渐渐老了，重来这里事事可叹！烟雾昏暝，酒旗斜挂。只能倚楼极目，不时看见栖鸦。无奈归心，暗暗随流水到天涯。', 'public-domain'),
  ('songci300', 85, '八六子·倚危亭', 'songci-sc-86', '倚危亭恨如芳草萋萋刬尽还生念柳外青骢别后水边红袂分时怆然暗惊无端天与娉婷夜月一帘幽梦春风十里柔情怎奈向欢娱渐随流水素弦声断翠绡香减那堪片片飞花弄晚蒙蒙残雨笼晴正销凝黄鹂又啼数声', '倚着高亭，恨像芳草，铲尽了又长出来。想起柳外骑着青骢马分别之后，水边她红袖分手之时，心中怆然暗惊。
上天无端给了她这样的姿容。夜月下一帘幽梦，春风里十里柔情。怎奈欢娱渐渐随流水而去，素弦声断，翠绡香减；哪堪片片飞花在暮色里摆弄，蒙蒙残雨笼着晴光。正消魂凝望，黄鹂又啼了几声。', 'public-domain'),
  ('songci300', 86, '满庭芳·山抹微云', 'songci-sc-87', '山抹微云天连衰草画角声断谯门暂停征棹聊共引离尊多少蓬莱旧事空回首烟霭纷纷斜阳外寒鸦万点流水绕孤村消魂当此际香囊暗解罗带轻分谩赢得青楼薄幸名存此去何时见也襟袖上空惹啼痕伤情处高城望断灯火已黄昏', '山抹着微云，天连着衰草，谯门上的画角声断了。暂且停下征船，姑且一同举杯话别。多少蓬莱旧事，空自回首，只见烟霭纷纷。斜阳之外，寒鸦万点，流水绕着孤村。
消魂。在这时候，暗暗解下香囊，轻轻分开罗带。白白在青楼赢得薄幸的名声。这一去什么时候再见？襟袖上只空留啼痕。最伤情处，望断高城，灯火已在黄昏里。', 'public-domain'),
  ('songci300', 87, '满庭芳·碧水惊秋', 'songci-sc-88', '碧水惊秋黄云凝暮败叶零乱空阶洞房人静斜月照徘徊又是重阳近也几处处砧杵声催西窗下风摇翠竹疑是故人来伤怀增怅望新欢易失往事难猜问篱边黄菊知为谁开谩道愁须殢酒酒未醒愁已先回凭阑久金波渐转白露点苍苔', '碧水惊起秋意，黄云凝着暮色，败叶零乱地落在空台阶上。洞房里人静，斜月照着我徘徊。又快到重阳了，处处响起砧杵声催人。西窗下，风摇翠竹，疑是故人来。
伤怀。更添怅望，新欢容易失去，往事难以猜度。问篱边的黄菊，知道它为谁开？别说愁要靠酒来缠，酒还没醒，愁已先回来了。倚栏久了，月光渐渐移动，白露点着青苔。', 'public-domain'),
  ('songci300', 88, '减字木兰花·天涯旧恨', 'songci-sc-89', '天涯旧恨独自凄凉人不问欲见回肠断尽金炉小篆香黛蛾长敛任是春风吹不展困倚危楼过尽飞鸿字字愁', '天涯旧恨，独自凄凉，无人过问。要看我的回肠，就像金炉里小篆香烧断成灰。
双眉长皱，任凭春风吹也展不开。困倦地倚着高楼，看尽飞鸿，字字都是愁。', 'public-domain'),
  ('songci300', 89, '浣溪沙·漠漠轻寒上小楼', 'songci-sc-90', '漠漠轻寒上小楼晓阴无赖似穷秋淡烟流水画屏幽自在飞花轻似梦无边丝雨细如愁宝帘闲挂小银钩', '漠漠的轻寒漫上小楼，清晨的阴天无赖得像深秋。淡烟流水，画屏幽静。
自在的飞花轻得像梦，无边的丝雨细得像愁。宝帘闲挂在小银钩上。', 'public-domain'),
  ('songci300', 90, '阮郎归·湘天风雨破寒初', 'songci-sc-91', '湘天风雨破寒初深沉庭院虚丽谯吹罢小单于迢迢清夜徂乡梦断旅魂孤峥嵘岁又除衡阳犹有雁传书郴阳和雁无', '湘天的风雨冲破寒意之初，深沉的庭院空寂。丽谯楼上吹罢《小单于》，迢迢清夜流去。
乡梦断了，旅魂孤单，年岁峥嵘又到除夕。衡阳还有大雁传书，郴阳连雁也没有。', 'public-domain'),
  ('songci300', 91, '鹧鸪天·枝上流莺和泪闻', 'songci-sc-92', '枝上流莺和泪闻新啼痕间旧啼痕一春鱼鸟无消息千里关山劳梦魂无一语对芳尊安排肠断到黄昏甫能炙得灯儿了雨打梨花深闭门', '枝上流莺的啼声和着泪听，新的泪痕夹着旧的泪痕。一春没有鱼雁消息，千里关山白白劳烦梦魂。
一句话也没有，对着酒杯，安排着断肠直到黄昏。刚把灯点上，雨就打梨花，只好把门深深关上。', 'public-domain'),
  ('songci300', 92, '江城子·西城杨柳弄春柔', 'songci-sc-93', '西城杨柳弄春柔动离忧泪难收犹记多情曾为系归舟碧野朱桥当日事人不见水空流韶华不为少年留恨悠悠几时休飞絮落花时候一登楼便作春江都是泪流不尽许多愁', '西城的杨柳在春风中摆动，牵动离愁，泪水难收。还记得她多情，曾为我系住归来的船。碧野朱桥是当年的旧事，人已不见，只有水空自流。
美好的年华不为少年停留，遗恨悠悠，几时才休？柳絮飘、落花飞的时候，独自登楼。纵使春江都是泪，也流不尽这许多愁。', 'public-domain'),
  ('songci300', 93, '临江仙·谪宦江城无屋买', 'songci-sc-336', '谪宦江城无屋买残僧野寺相依松间药臼竹间衣水穷行到处云起坐看时一个幽禽缘底事苦来醉耳边啼月斜西院愈声悲青山无限好犹道不如归', '被贬到江城，没有房屋可买，只能与残僧在野寺里相依。松林间放着药臼，竹林间晾着衣裳。走到水流的尽头，就坐下看云起的时景。
一只幽禽为了什么事，苦苦地在我醉耳边啼叫？月亮斜过西院，叫声越发悲切。青山无限美好，它却还说「不如归去」。', 'public-domain'),
  ('songci300', 94, '水龙吟·问春何苦匆匆', 'songci-sc-95', '问春何苦匆匆带风伴雨如驰骤幽葩细萼小园低槛壅培未就吹尽繁红占春长久不如垂柳算春常不老人愁春老愁只是人间有春恨十常八九忍轻孤芳醪经口那知自是桃花结子不因春瘦世上功名老来风味春归时候纵樽前痛饮狂歌似旧情难依旧', '问春为什么这样匆匆，带着风伴着雨像疾驰一般。幽静的花、细小的萼，小园低栏里，培土还没培好。吹尽了繁花，能长久占住春天的，不如垂柳。算来春永远不会老，是人愁春老，这愁只在人间有。
春恨十次里常有八九次。怎忍心轻易辜负了杯中美酒。哪知道桃花结子，并不是因为春去而消瘦。世上的功名，老来的滋味，都在春归的时候。纵然在杯前痛饮、狂歌如旧，情却难以依旧。', 'public-domain'),
  ('songci300', 95, '忆少年·无穷官柳', 'songci-sc-337', '无穷官柳无情画舸无根行客南山尚相送只高城人隔罨画园林溪绀碧算重来尽成陈迹刘郎鬓如此况桃花颜色', '一眼望不到头的官柳，无情地载人远去的画船，无根漂泊的行客。南山还肯相送，只有高高的城墙把人隔开。
历下的园林像彩画，溪水呈青碧色，算起来他日重来，都要变成旧迹。刘郎的鬓发已这样斑白，何况桃花的颜色。', 'public-domain'),
  ('songci300', 96, '洞仙歌·青烟幂处', 'songci-sc-97', '青烟幂处碧海飞金镜永夜闲阶卧桂影露凉时零乱多少寒螀神京远惟有兰桥路近水晶帘不下云母屏开冷浸佳人淡脂粉待都将许多明付与金尊投晓共流霞倾尽更携取胡床上南楼看玉做人间素秋千顷', '青烟笼罩的地方，碧海里飞出一面金镜。长夜里，空台阶上卧着桂树的影子。露水凉时，多少寒蝉零乱地叫；京城遥远，只有蓝桥的路近。
水晶帘不放下，云母屏打开，清冷浸着佳人淡淡的脂粉。要把这许多光明都交给金杯，到天亮时与流霞一同饮尽。再带着胡床登上南楼，看月色把人间做成玉，素净的秋色铺满千顷。', 'public-domain'),
  ('songci300', 97, '临江仙·忆昔西池池上饮', 'songci-sc-98', '忆昔西池池上饮年年多少欢娱别来不寄一行书寻常相见了犹道不如初安稳锦屏今夜梦月明好渡江湖相思休问定何如情知春去后管得落花无', '回想当年在西池池上饮酒，年年有多少欢乐。别后连一行书信也不寄。即使寻常相见，还说不像当初。
今夜锦屏里安睡入梦，月明正好渡过江湖。相思不必问究竟怎样。明知春天去后，还管得了落花吗。', 'public-domain'),
  ('songci300', 98, '惜分飞·泪湿阑干花著露', 'songci-sc-99', '泪湿阑干花著露愁到眉峰碧聚此恨平分取更无言语空相觑断雨残云无意绪寂寞朝朝暮暮今夜山深处断魂分付潮回去', '泪水打湿栏杆，花瓣上挂着露珠；愁到极处，眉毛像碧峰聚拢。这恨两人平分，再没有话说，只是空对着看。
断雨残云，毫无意绪，寂寞朝朝暮暮。今夜在山深处，把断了魂交给潮水带回去。', 'public-domain'),
  ('songci300', 99, '菩萨蛮·赤阑桥尽香街直', 'songci-sc-100', '赤阑桥尽香街直笼街细柳娇无力金碧上青空花晴帘影红黄衫飞白马日日青楼下醉眼不逢人午香吹暗尘', '红栏杆的桥尽头，飘香的街道笔直；笼着街道的细柳娇柔无力。金碧楼台伸向青空，花开天晴，帘影泛红。
穿黄衫的人骑着白马飞驰，天天在青楼下。醉眼朦胧看不见人，午间的香气吹起暗尘。', 'public-domain'),
  ('songci300', 100, '谒金门·花满市', 'songci-sc-101', '花满市月侵衣小院回廊春寂寂画帘风软燕归时人在绿窗初睡起看花却是今年好忆着去年人老人生只合扬州死禅智山光好墓田', '花满街市，月色侵衣。小院回廊里春意寂寂。画帘外风软，正是燕子归来的时候；人在绿窗下刚刚睡起。
看花还是今年好，回想去年，人已老了一岁。人生只该老死在扬州——禅智寺的山光就是好墓地。', 'public-domain'),
  ('songci300', 101, '苏幕遮·燎沉香', 'songci-sc-338', '燎沉香消溽暑鸟雀呼晴侵晓窥檐语叶上初阳干宿雨水面清圆一一风荷举故乡遥何日去家住吴门久作长安旅五月渔郎相忆否小楫轻舟梦入芙蓉浦', '点燃沉香，消去潮湿的暑气。鸟雀呼唤晴天，拂晓时在檐下探头啁啾。朝阳晒干了荷叶上隔夜的雨珠，水面清亮圆润，一枝枝风中的荷花高高擎起。
故乡遥远，哪天才能回去？家在吴门，却长久作客汴京。五月的渔郎还记不记得我？我梦见自己划着小桨轻舟，荡进荷花深处。', 'public-domain'),
  ('songci300', 102, '卜算子·我住长江头', 'songci-sc-103', '我住长江头君住长江尾日日思君不见君共饮长江水此水几时休此恨何时已只愿君心似我心定不负相思意', '我住在长江的源头，你住在长江的末尾。天天想你却见不到你，好在共饮一江之水。
这水什么时候流尽？这恨什么时候了结？只愿你的心像我的心，就绝不辜负这份相思。', 'public-domain'),
  ('songci300', 103, '兰陵王·柳阴直', 'songci-sc-104', '柳阴直烟里丝丝弄碧隋堤上曾见几番拂水飘绵送行色登临望故国谁识京华倦客长亭路年去岁来应折柔条过千尺闲寻旧踪迹又酒趁哀弦灯照离席梨花榆火催寒食愁一箭风快半篙波暖回头迢递便数驿望人在天北凄恻恨堆积渐别浦萦回津堠岑寂斜阳冉冉春无极念月榭携手露桥闻笛沉思前事似梦里泪暗滴', '柳荫笔直，烟雾中丝丝柳条摆弄碧色。在隋堤上，曾见过多少次它拂着水面、飘着柳絮送人远行。登高远望故国，谁能理解我这京城倦客？长亭路上，年去年来，折下的柳条该有千尺了。
闲来寻觅旧日踪迹，又趁着哀弦饮酒，灯火照着离别的酒席。梨花与榆火催促寒食到来。愁那一帆风顺、一篙水暖，回头就已过了几个驿站，望见的人远在天北。
凄恻，恨堆积！送别的江口曲折回环，渡口冷冷清清，斜阳缓缓移动，春色无边。回想月下楼台携手、露桥听笛。沉思往事，像在梦里，眼泪暗暗滴落。', 'public-domain'),
  ('songci300', 104, '瑞龙吟·章台路', 'songci-sc-105', '章台路还见褪粉梅梢试花桃树愔愔坊陌人家定巢燕子归来旧处黯凝伫因念个人痴小乍窥门户侵晨浅约宫黄障风映袖盈盈笑语前度刘郎重到访邻寻里同时歌舞惟有旧家秋娘声价如故吟笺赋笔犹记燕台句知谁伴名园露饮东城闲步事与孤鸿去探春尽是伤离意绪官柳低金缕归骑晚纤纤池塘飞雨断肠院落一帘风絮', '章台路上，又看见梅梢褪了粉、桃树初绽花。街坊里人家安静，归巢的燕子回到旧处。
我黯然凝立，想起她当初痴小，刚在门边偷看。清早淡淡地抹着宫黄，用袖子挡风，盈盈地笑着说话。
前度刘郎重来，访邻寻里，当年一同歌舞的人。只有旧家的秋娘，声价还如从前。吟诗作赋，还记得那些燕台诗句。可知谁陪我在名园露下饮酒、在东城闲步。往事已随孤雁远去。探春所见，尽是伤离的情绪。官柳低垂着金丝般的柳条。暮色中骑马归来，池塘上飘着纤细的雨。断肠的院落，一帘风絮。', 'public-domain'),
  ('songci300', 105, '风流子·新绿小池塘', 'songci-sc-106', '新绿小池塘风帘动碎影舞斜阳羡金屋去来旧时巢燕土花缭绕前度莓墙绣阁里凤帏深几许听得理丝簧欲说又休虑乖芳信未歌先噎愁近清觞遥知新妆了开朱户应自待月西厢最苦梦魂今宵不到伊行问甚时说与佳音密耗寄将秦镜偷换韩香天便教人霎时厮见何妨', '小池塘一片新绿，风吹帘动，碎影在斜阳里舞。羡慕那金屋中来去的旧巢燕，羡慕那绕着旧日莓墙的苔花。绣阁里，凤帐深到什么程度？只听得她调理乐器。想说话又停住，怕误了佳音；还没唱就先哽住，愁绪贴近清酒。
远远想她新妆已就，打开朱门，该在西厢待月。最苦的是梦魂今夜也到不了她身边。问什么时候才能把好消息密告她，送去秦镜、偷换韩香。老天既然让人相见，哪怕只是片刻又何妨！', 'public-domain'),
  ('songci300', 106, '渡江云·晴岚低楚甸', 'songci-sc-107', '晴岚低楚甸暖回雁翼阵势起平沙骤惊春在眼借问何时委曲到山家涂香晕色盛粉饰争作妍华千万丝陌头杨柳渐渐可藏鸦堪嗟清江东注画舸西流指长安日下愁宴阑风翻旗尾潮溅乌纱今宵正对初弦月傍水驿深舣蒹葭沉恨处时时自剔灯花', '晴日山气低笼楚地郊野，暖气回到雁翼上，雁阵从平沙飞起。猛然惊觉春已在眼前，请问它什么时候，曲曲折折地到了山里人家。涂抹香色、浓施粉黛，争着开出妍丽的花。陌头千万缕杨柳丝，渐渐密得可以藏住乌鸦。
堪叹。清江东流，画船西行，指向日下的长安。愁的是宴散时，风吹翻旗尾，潮水溅湿乌纱。今夜正对着初弦月，靠着水边驿舍，把船深深泊在芦苇丛里。在深恨的地方，时时自己剔着灯花。', 'public-domain'),
  ('songci300', 107, '应天长·条风布暖', 'songci-sc-108', '条风布暖霏雾弄晴池塘遍满春色正是夜堂无月沉沉暗寒食梁间燕前社客似笑我闭门愁寂乱花过隔院芸香满地狼籍长记那回时邂逅相逢郊外驻油壁又见汉宫传烛飞烟五侯宅青青草迷路陌强载酒细寻前迹市桥远柳下人家犹自相识', '东风布暖，薄雾弄晴，池塘里满是春色。正是夜堂无月，沉沉地过了寒食。梁间的燕子，是前社来的旧客，好像在笑我闭门愁寂。落花飞过，隔着院子传来芸香，满地狼藉。
常记得那一回，偶然相逢，在郊外停下车。又见汉宫传烛，飞烟飘到五侯宅。青青春草，把路都迷了。勉强载着酒，细细寻找旧迹。市桥遥远，柳树下的人家，还认得我。', 'public-domain'),
  ('songci300', 108, '还京乐·禁烟近', 'songci-sc-109', '禁烟近触处浮香秀色相料理正泥花时候奈何客里光阴虚费望箭波无际迎风漾日黄云委任去远中有万点相思清泪到长淮底过当时楼下殷勤为说春来羁旅况味堪嗟误约乖期向天涯自看桃李想而今应恨墨盈笺愁妆照水怎得青鸾翼飞归教见憔悴', '寒食将近，到处是浮动的香气和秀色互相映衬。正是缠着花的时候，怎奈客居他乡，把光阴白白浪费。望着箭一般的水波无边无际。迎风漾日，黄云低垂。任凭它流去多远，水中有万点，是我相思的清泪。
流到长淮底。经过当年那座楼下，殷勤地替我诉说，春天里羁旅的滋味。可叹误了约期，只能在天涯自己看桃李。想她如今，该是恨字写满信笺，愁妆照着水面。怎么才能有青鸾的翅膀，飞回去让她看见我的憔悴。', 'public-domain'),
  ('songci300', 109, '解连环·怨怀无托', 'songci-sc-110', '怨怀无托嗟情人断绝信音辽邈纵妙手能解连环似风散雨收雾轻云薄燕子楼空暗尘锁一床弦索想移根换叶尽是旧时手种红药汀洲渐生杜若料舟依岸曲人在天角谩记得当日音书把闲语闲言待总烧却水驿春回望寄我江南梅萼拚今生对花对酒为伊泪落', '怨怀无处寄托，可叹情人断绝，音信遥远。纵有妙手能解开连环，也像风散雨收、雾轻云薄。燕子楼已空，暗尘锁住一床琴弦。想那草木移根换叶，都是旧时她亲手种的红芍药。
汀洲上渐渐长出杜若。料想船停泊在弯曲的岸边，人远在天角。白白记得当日的书信，把那些闲言闲语，打算统统烧掉。水边驿站春回，盼望寄我一枝江南梅萼。拼了这辈子，对花对酒，为她落泪。', 'public-domain'),
  ('songci300', 110, '夜游宫·叶下斜阳照水', 'songci-sc-111', '叶下斜阳照水卷轻浪沉沉千里桥上酸风射眸子立多时看黄昏灯火市古屋寒窗底听几片井桐飞坠不恋单衾再三起有谁知为萧娘书一纸', '树下的斜阳照在水面，卷起轻浪，沉沉地流去千里。桥上的冷风刺着眼睛。站了很久，看黄昏里灯火满街市。
回到古屋寒窗下，听井边梧桐叶一片片飞落。不留恋单薄的被子，再三起身。有谁知道，我是为了她，为一纸书信。', 'public-domain'),
  ('songci300', 111, '菩萨蛮·银河宛转三千曲', 'songci-sc-112', '银河宛转三千曲浴凫飞鹭澄波绿何处是归舟夕阳江上楼天憎梅浪发故下封枝雪深院卷帘看应怜江上寒', '银河般的水流弯弯曲曲三千道，野鸭戏水、白鹭飞起，澄波碧绿。哪里是归舟？夕阳照着江上楼。
上天恨梅花开得太恣意，故意下雪封住枝头。她深院里卷帘远看，该会怜惜江上的寒冷。', 'public-domain'),
  ('songci300', 112, '虞美人·疏篱曲径田家小', 'songci-sc-113', '疏篱曲径田家小云树开清晓天寒山色有无中野外一声钟起送孤蓬添衣策马寻亭堠愁抱惟宜酒菰蒲睡鸭占陂塘纵被行人惊散又成双', '疏篱曲径，田家很小；云树间天已破晓。天寒，山色若隐若现。野外一声钟响，送走孤舟。
添件衣服骑马去找驿站，满怀愁绪只适合喝酒。茭白蒲草丛中，睡鸭占着池塘；纵然被行人惊散，转眼又成双。', 'public-domain'),
  ('songci300', 113, '点绛唇·辽鹤归来', 'songci-sc-114', '辽鹤归来故乡多少伤心地寸书不寄鱼浪空千里凭仗桃根说与凄凉意愁无际旧时衣袂犹有东门泪', '辽鹤归来，故乡有多少伤心的旧地。一寸书信也不寄，鱼浪白白千里。
只能依靠桃根，替我诉说凄凉之意。愁绪无边，旧时的衣袖上，还有东门洒下的泪。', 'public-domain'),
  ('songci300', 114, '齐天乐·绿芜凋尽台城路', 'songci-sc-115', '绿芜凋尽台城路殊乡又逢秋晚暮雨生寒鸣蛩劝织深阁时闻裁剪云窗静掩叹重拂罗裀顿疏花簟尚有綀囊露萤清夜照书卷荆江留滞最久故人相望处离思何限渭水西风长安乱叶空忆诗情宛转凭高眺远正玉液新篘蟹螯初荐醉倒山翁但愁斜照敛', '台城路上绿草凋尽，异乡又逢秋晚。暮雨带来寒意，蟋蟀鸣叫像催人织布，深阁里不时听见裁剪声。云窗静静掩着，可叹重新拂拭罗褥，转眼又疏远了花席。还有粗布囊，装着露水萤火，在清夜照我读书。
在荆江滞留最久，故人相望的地方，离思无穷。渭水西风，长安乱叶，白白回忆那宛转的诗情。登高远眺，正是新酒初滤、蟹螯初上的时候。我要像山简那样醉倒，只愁斜阳收敛了光。', 'public-domain'),
  ('songci300', 115, '琐窗寒·暗柳啼鸦', 'songci-sc-116', '暗柳啼鸦单衣伫立小帘朱户桐花半亩静锁一庭愁雨洒空阶夜阑未休故人剪烛西窗语似楚江暝宿风灯零乱少年羁旅迟暮嬉游处正店舍无烟禁城百五旗亭唤酒付与高阳俦侣想东园桃李自春小唇秀靥今在否到归时定有残英待客携尊俎', '暗柳上乌鸦啼叫，我穿着单衣久立，面前是小帘朱户。半亩桐花，静静地锁住一庭愁雨。雨洒在空台阶上，到夜深还没停，我和故人剪烛在西窗下说话。像在楚江夜宿，风灯零乱，那是少年的羁旅。
已到迟暮之年。回想游乐的地方。正是店舍无烟、京城过寒食的时候。在旗亭唤酒，交给高阳酒徒那样的伙伴。想东园的桃李自在地开着春色，那小巧的嘴唇、秀美的酒窝如今还在吗？等我回去时，一定还有残花，等着我带着酒菜去赏。', 'public-domain'),
  ('songci300', 116, '过秦楼·水浴清蟾', 'songci-sc-117', '水浴清蟾叶喧凉吹巷陌马声初断闲依露井笑扑流萤惹破画罗轻扇人静夜久凭阑愁不归眠立残更箭叹年华一瞬人今千里梦沉书远空见说鬓怯琼梳容销金镜渐懒趁时匀染梅风地溽虹雨苔滋一架舞红都变谁信无聊为伊才减江淹情伤荀倩但明河影下还看稀星数点', '月光在水里洗过，树叶被凉风吹得喧响，街巷里的马蹄声刚刚断绝。她闲来靠着露井，笑着扑打流萤，把画罗轻扇都弄破了。夜深人静，我倚着栏杆，愁得不想回去睡，站到更漏将尽。可叹年华只是一瞬，人如今相隔千里，梦沉书远。
只听说她两鬓怕用玉梳，容颜在镜中消瘦，渐渐懒得按时梳妆。梅雨时节地上潮湿，虹雨后青苔滋长，一架红花都变了样。谁信我这样无聊是为了她，才思比江淹还减，情深如荀奉倩。只是银河影下，还看着几点稀疏的星。', 'public-domain'),
  ('songci300', 117, '花犯·粉墙低', 'songci-sc-118', '粉墙低梅花照眼依然旧风味露痕轻缀疑净洗铅华无限佳丽去年胜赏曾孤倚冰盘同燕喜更可惜雪中高树香篝熏素被今年对花最匆匆相逢似有恨依依愁悴吟望久青苔上旋看飞坠相将见脆丸荐酒人正在空江烟浪里但梦想一枝潇洒黄昏斜照水', '粉墙低矮，梅花照眼，依旧是旧日的风味。露痕轻轻缀着，像洗净了脂粉，无限佳丽。去年尽兴赏花时曾独自倚树，与冰盘一同欢宴。更可惜雪中的高树，香笼熏着素被。
今年对花最是匆匆，相逢似乎带着恨意，依依地愁瘦了。吟望久了，青苔上不时看见花瓣飞坠。不久将见梅子脆丸佐酒，而我正在空江烟浪里。只能梦想那一枝潇洒的梅花，在黄昏里斜照水面。', 'public-domain'),
  ('songci300', 118, '大酺·对宿烟收', 'songci-sc-119', '对宿烟收春禽静飞雨时鸣高屋墙头青玉旆洗铅霜都尽嫩梢相触润逼琴丝寒侵枕障虫网吹粘帘竹邮亭无人处听檐声不断困眠初熟奈愁极频惊梦轻难记自怜幽独行人归意速最先念流潦妨车毂怎奈向兰成憔悴卫玠清羸等闲时易伤心目未怪平阳客双泪落笛中哀曲况萧索青芜国红糁铺地门外荆桃如菽夜游共谁秉烛', '眼看夜雾收去，春禽静了，飞雨不时敲打高屋。墙头的青竹像玉旗，霜粉都已洗尽，嫩梢互相触碰。潮气逼近琴弦，寒气侵入枕屏，虫网被风吹得粘在帘竹上。邮亭里无人，听檐下雨声不断，困倦中刚睡熟。无奈愁到极处频频惊醒，梦轻难记，自怜幽独。
行人归心急切，最先想到的是积水会阻了车轮。怎奈像我这样憔悴清瘦，寻常时候也容易伤心。难怪平阳客听笛中哀曲而双泪落。何况眼前萧索，一片青芜。红花铺地，门外的樱桃已结成豆大的果子。夜里要与谁秉烛同游？', 'public-domain'),
  ('songci300', 119, '解语花·风销焰蜡', 'songci-sc-120', '风销焰蜡露浥红莲花市光相射桂华流瓦纤云散耿耿素娥欲下衣裳淡雅看楚女纤腰一把箫鼓喧人影参差满路飘香麝因念都城放夜望千门如昼嬉笑游冶钿车罗帕相逢处自有暗尘随马年光是也唯只见旧情衰谢清漏移飞盖归来从舞休歌罢', '风吹销了烛焰，露水沾湿红莲灯，灯市里光华交射。月光流过屋瓦，纤云散去，明亮的嫦娥仿佛要下来。衣裳淡雅，看那楚地女子，纤腰一握。箫鼓喧腾，人影参差，满路飘着麝香。
于是想起京城放夜的夜晚，望千门灯火如昼，人们嬉笑游乐。钿车罗帕，相逢的地方自有车马扬起的暗尘。年光还是这样，只是旧日的情意衰谢了。漏声移转，我乘车归去，任凭舞歇歌罢。', 'public-domain'),
  ('songci300', 120, '蝶恋花·月皎惊乌栖不定', 'songci-sc-121', '月皎惊乌栖不定更漏将阑轳辘牵金井唤起两眸清炯炯泪花落枕红绵冷执手霜风吹鬓影去意徊徨别语愁难听楼上阑干横斗柄露寒人远鸡相应', '月色皎洁，惊得乌鸦栖息不定；更漏将尽，井上辘轳在响。唤她起身，两只眼睛清亮有神，泪花落在枕上，红绵都冷了。
握着手，霜风吹动鬓影；要走又迟疑，离别的话愁得听不下去。楼上栏杆外横着北斗的斗柄，露冷人远，鸡声相互应和。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 121, '西河·佳丽地', 'songci-sc-122', '佳丽地南朝盛事谁记山围故国绕清江髻鬟对起怒涛寂寞打孤城风樯遥度天际断崖树犹倒倚莫愁艇子曾系空余旧迹郁苍苍雾沉半垒夜深月过女墙来伤心东望淮水酒旗戏鼓甚处市想依稀王谢邻里燕子不知何世向寻常巷陌人家相对如说兴亡斜阳里', '这佳丽之地，南朝的盛事还有谁记得？青山环绕故都，绿水绕城，两岸山峰像发髻相对。怒涛寂寞地拍打孤城，风帆远远驶过天际。
断崖上的老树，还倒倚着。莫愁女的船曾在这里系过。只留下苍苍的旧迹，浓雾沉埋了半座营垒。夜深时月亮越过女墙，伤心得向东望淮水。
酒旗戏鼓，那是什么地方的集市？想来依稀是王谢两家的邻里。燕子不知是什么朝代，对着寻常巷陌的人家，相对着像在诉说兴亡，在斜阳里。', 'public-domain'),
  ('songci300', 122, '瑞鹤仙·悄郊原带郭', 'songci-sc-123', '悄郊原带郭行路永客去车尘漠漠斜阳映山落敛余红犹恋孤城阑角凌波步弱过短亭何用素约有流莺劝我重解绣鞍缓引春酌不记归时早暮上马谁扶醒眠朱阁惊飙动幕扶残醉绕红药叹西园已是花深无地东风何事又恶任流光过却犹喜洞天自乐', '郊野连着城郭，一片静悄悄；路很长，客去车尘漠漠。斜阳映着山峦落下，收敛余红，还恋着孤城栏杆的一角。她步履轻弱，经过短亭，何必事先约定。有流莺劝我，重新解下绣鞍，慢慢斟春酒。
不记得回来是早是晚，上马时是谁扶的，酒醒时已睡在朱阁。狂风吹动帷幕，我扶着残醉，绕着红芍药走。可叹西园已是花深得没有空地，东风为什么还要作恶？任流光过去吧，还高兴能在这洞天里自乐。', 'public-domain'),
  ('songci300', 123, '浪淘沙慢·晓阴重', 'songci-sc-124', '晓阴重霜凋岸草雾隐城堞南陌脂车待发东门帐饮乍阕正拂面垂杨堪揽结掩红泪玉手亲折念汉浦离鸿去何许经时信音绝情切望中地远天阔向露冷风清无人处耿耿寒漏咽嗟万事难忘唯是轻别翠尊未竭凭断云留取西楼残月罗带光销纹衾叠连环解旧香顿歇怨歌永琼壶敲尽缺恨春去不与人期弄夜色空余满地梨花雪', '清晨阴云浓重，霜打凋了岸边的草，雾遮住城头。南边路上，上了油的车正待出发；东门外饯行的帐幕刚散。拂面的垂杨正好可以揽住，她掩着红泪，用玉手亲自折柳相赠。想那汉浦的离雁去了哪里？过了这么久音信断绝。
情意恳切，望中地远天阔。在露冷风清、无人之处，寒漏耿耿如咽。可叹万事都能忘，只有轻易的离别难忘。翠杯还没喝干，就凭断云留住西楼残月吧。
罗带的光泽消尽，花纹被褥叠起。连环解开，旧日的香气顿时歇了。怨歌长唱，把玉壶敲得尽是缺口。恨春天离去不与人约定，只弄这夜色，白白留下满地梨花如雪。', 'public-domain'),
  ('songci300', 124, '拜星月慢·夜色催更', 'songci-sc-125', '夜色催更清尘收露小曲幽坊月暗竹槛灯窗识秋娘庭院笑相遇似觉琼枝玉树相倚暖日明霞光烂水盼兰情总平生稀见画图中旧识春风面谁知道自到瑶台畔眷恋雨润云温苦惊风吹散念荒寒寄宿无人馆重门闭败壁秋虫叹怎奈向一缕相思隔溪山不断', '夜色催着更鼓，清尘收去露水，小巷深处月色暗淡。竹栏灯窗下，认得是秋娘的庭院。笑着相逢，仿佛琼枝玉树相依，暖日明霞光灿。水样的眼波、兰样的情意，一生中难得见到。
像在画里见过那春风般的面容。谁知道，自从到了这瑶台畔，贪恋那雨润云温，却被惊风吹散。想我如今在荒寒的无人馆舍寄宿。重门紧闭，破壁下秋虫叹息。怎奈那一缕相思，隔着溪山也断不了。', 'public-domain'),
  ('songci300', 125, '尉迟杯·隋堤路', 'songci-sc-126', '隋堤路渐日晚密霭生深树阴阴淡月笼沙还宿河桥深处无情画舸都不管烟波隔前浦等行人醉拥重衾载将离恨归去因思旧客京华长偎傍疏林小槛欢聚冶叶倡条俱相识仍惯见珠歌翠舞如今向渔村水驿夜如岁焚香独自语有何人念我无憀梦魂凝想鸳侣', '隋堤路上，天色渐晚，浓雾从深树里生出。淡淡的月色阴暗地笼着沙岸，我还在河桥深处投宿。无情的画船，全不管烟波把前浦隔断。等行人醉拥厚被，就载着离恨归去。
于是想起当年客居京城，常常偎傍疏林，在小栏杆边欢聚。那些冶叶倡条都相识，也惯见珠歌翠舞。如今却在渔村水驿，夜长得像一年，焚着香独自说话。有谁念我这般无聊，梦魂凝想着鸳鸯伴侣。', 'public-domain'),
  ('songci300', 126, '夜飞鹊·河桥送人处', 'songci-sc-339', '河桥送人处凉夜何其斜月远堕余辉铜盘烛泪已流尽霏霏凉露沾衣相将散离会探风前津鼓树杪参旗花骢会意纵扬鞭亦自行迟迢递路回清野人语渐无闻空带愁归何意重经前地遗钿不见斜径都迷兔葵燕麦向残阳影与人齐但徘徊班草欷歔酹酒极望天西', '河桥上送别的地方，清凉的夜到了什么时辰？斜月远远落下，只剩一点余辉。铜盘里的烛泪已经流尽，纷纷凉露沾湿了衣裳。临别的宴席就要散了，听风里渡口的鼓声，看树梢上的参旗星。花马似乎懂得我的心意，即使扬鞭，也走得很慢。
回去的路曲折，经过空旷的原野，送行人的话渐不可闻，只带着愁绪归来。谁料又重经旧地，她遗落的钿饰已找不到，斜路都辨不清了。兔葵燕麦长得很高，在残阳里，影子与人齐高。我只得在草地上徘徊，叹息着洒酒祭奠，极力西望天边。', 'public-domain'),
  ('songci300', 127, '玉楼春·桃溪不作从容住', 'songci-sc-340', '桃溪不作从容住秋藕绝来无续处当时相候赤阑桥今日独寻黄叶路烟中列岫青无数雁背夕阳红欲暮人如风后入江云情似雨余黏地絮', '在桃溪没有能从容地留住，秋藕折断后再没有接续的地方。当年在赤阑桥上相候，如今独自来寻这条黄叶满地的路。
烟里无数青山排列，雁背上驮着夕阳，红得快要入暮。人像被风吹入江面的云，情像雨后黏在地上的柳絮。', 'public-domain'),
  ('songci300', 128, '石州慢·寒水依痕', 'songci-sc-139', '寒水依痕春意渐回沙际烟阔溪梅晴照生香冷蕊数枝争发天涯旧恨试看几许消魂长亭门外山重叠不尽眼中青是愁来时节情切画楼深闭想见东风暗销肌雪辜负枕前云雨尊前花月心期切处更有多少凄凉殷勤留与归时说到得却相逢恰经年离别', '寒水沿着旧痕，春意渐渐回来，沙滩边烟雾空阔。溪边梅树在晴日照耀下生出香气，几枝冷蕊争着开放。天涯旧恨，试看有多少消魂？长亭门外山峦重叠。眼中无尽的青色，正是愁来的时候。
情意恳切。画楼深闭，想那东风，暗暗消损她雪白的肌肤。辜负了枕前的云雨、杯前的花月。心中盼望最切的地方，还有多少凄凉，殷勤地留着等归来时说。等真能相逢，又恰恰是经年离别之后。', 'public-domain'),
  ('songci300', 129, '兰陵王·卷珠箔', 'songci-sc-140', '卷珠箔朝雨轻阴乍阁阑干外烟柳弄晴芳草侵阶映红药东风妒花恶吹落梢头嫩萼屏山掩沉水倦熏中酒心情怯杯勺寻思旧京洛正年少疏狂歌笑迷著障泥油壁催梳掠曾驰道同载上林携手灯夜初过早共约又争信漂泊寂寞念行乐甚粉淡衣襟音断弦索琼枝璧月春如昨怅别后华表那回双鹤相思除是向醉里暂忘却', '卷起珠帘，清晨的雨和轻阴刚刚停下。栏杆外，烟柳在晴光里摆动，芳草漫上台阶，映着红芍药。东风嫉妒花儿，恶狠狠地吹落了梢头的嫩萼。屏山掩着，沉香懒得再熏，酒后心情怕见酒杯。
回想旧日的京城，那时年少疏狂，一味迷恋歌笑。她坐上车，就催着梳妆。曾在大道上同车而行，在上林苑携手，灯节刚过就一同约好。又怎么敢相信会漂泊至今。
寂寞。追念旧日的行乐。为何脂粉淡了衣襟、琴弦断了音信。琼枝璧月，春色如昨。惆怅别后重来，人事已非。相思除非在醉里，才能暂时忘却。', 'public-domain'),
  ('songci300', 130, '贺新郎·梦绕神州路', 'songci-sc-141', '梦绕神州路怅秋风连营画角故宫离黍底事昆仑倾砥柱九地黄流乱注聚万落千村狐兔天意从来高难问况人情老易悲如许更南浦送君去凉生岸柳催残暑耿斜河疏星淡月断云微度万里江山知何处回首对床夜语雁不到书成谁与目尽青天怀今古肯儿曹恩怨相尔汝举大白听金缕', '梦里绕着中原地带的道路。惆怅秋风中，连营的号角声，故都长满禾黍。为什么昆仑的砥柱崩塌，九州的黄河水乱流？万落千村聚着狐兔。天意从来高远难以询问，何况人一老就容易这样悲伤。又在这南浦，送你离去。
岸边柳树生出凉意，催促残暑退去。银河明净，疏星淡月，断云缓缓飘过。万里江山，人如今在哪里？回想当年对床夜话。大雁飞不到，信写好了交给谁？望尽青天，心怀今古，岂肯像小儿女那样计较恩怨！举起大杯，听我唱这首《金缕曲》。', 'public-domain'),
  ('songci300', 131, '虞美人·落花已作风前舞', 'songci-sc-142', '落花已作风前舞又送黄昏雨晓来庭院半残红惟有游丝千丈罥晴空殷勤花下同携手更尽杯中酒美人不用敛歌眉我亦多情无奈酒阑时', '落花已在风前飞舞，又送走黄昏的雨。清晨庭院里一半是残花，只有千丈游丝挂在晴空。
我们殷勤地在花下携手，把杯中酒喝干。美人不必皱起歌眉，我也是多情的人，只是无奈酒阑人散的时候。', 'public-domain'),
  ('songci300', 132, '点绛唇·新月娟娟', 'songci-sc-143', '新月娟娟夜寒江静山衔斗起来搔首梅影横窗瘦好个霜天闲却传杯手君知否乱鸦啼后归兴浓于酒', '新月美好，夜寒江静，山峰衔着北斗。起身挠头，梅影横在窗上，清瘦。
好一个霜天，却闲下了传杯的手。你知道吗？乱鸦啼过之后，归乡的兴致比酒还浓。', 'public-domain'),
  ('songci300', 133, '喜迁莺·晓光催角', 'songci-sc-144', '晓光催角听宿鸟未惊邻鸡先觉迤逦烟村马嘶人起残月尚穿林薄泪痕带霜微凝酒力冲寒犹弱叹倦客悄不禁重染风尘京洛追念人别后心事万重难觅孤鸿托翠幌娇深曲屏香暖争念岁华飘泊怨月恨花烦恼不是不曾经著者情味望一成消减新来还恶', '晨光催着号角。听宿鸟还没惊动，邻家的鸡先醒了。一路烟雾中的村庄，马嘶人起，残月还挂在林梢。泪痕带着霜微微凝结，酒力挡不住寒气还嫌单薄。可叹倦游的人，悄悄受不住再染上京洛的风尘。
追想别后，心事万重，难以找到孤雁传递。翠帘娇深，曲屏香暖，怎么想得到年华在漂泊中流逝。怨月恨花的烦恼，不是没有经历过。这种情味，指望它能消减一分，近来反而更糟。', 'public-domain'),
  ('songci300', 134, '高阳台·频听银签', 'songci-sc-145', '频听银签重燃绛蜡年华衮衮惊心饯旧迎新能消几刻光阴老来可惯通宵饮待不眠还怕寒侵掩清尊多谢梅花伴我微吟邻娃已试春妆了更蜂腰簇翠燕股横金勾引东风也知芳思难禁朱颜那有年年好逞艳游赢取如今恣登临残雪楼台迟日园林', '频频听着更签，重新点上红烛，年华滚滚令人心惊。送旧迎新，能消磨几刻光阴？老了哪还习惯通宵饮酒？想不睡，又怕寒气侵入。放下酒杯，多谢梅花，陪我低声吟咏。
邻家女孩已试过春妆，蜂腰般的发饰簇着翠，燕尾般的金钗横着。她勾引东风，也知道芳心难禁。红颜哪能年年都好，趁艳游赢得如今吧。尽情登临，看残雪的楼台、迟日的园林。', 'public-domain'),
  ('songci300', 135, '汉宫春·潇洒江梅', 'songci-sc-146', '潇洒江梅向竹梢疏处横两三枝东君也不爱惜雪压霜欺无情燕子怕春寒轻失花期却是有年年塞雁归来曾见开时清浅小溪如练问玉堂何似茅舍疏篱伤心故人去后冷落新诗微云淡月对江天分付他谁空自忆清香未减风流不在人知', '江边梅花潇洒，在竹梢稀疏处横出两三枝。春神也不爱惜，任它被雪压霜欺。无情的燕子怕春寒，轻易错过了花期。倒是有年年归来的塞雁，见过它开放的时候。
清浅的小溪像白练，问那玉堂比茅舍疏篱如何？伤心的是故人离去后，新诗也冷落了。微云淡月，面对江天，又能交给谁？只能空自回忆；清香未减，风流本不在别人知不知道。', 'public-domain'),
  ('songci300', 136, '临江仙·忆昔午桥桥上饮', 'poems-cz9-23', '忆昔午桥桥上饮坐中多是豪英长沟流月去无声杏花疏影里吹笛到天明二十余年如一梦此身虽在堪惊闲登小阁看新晴古今多少事渔唱起三更', '回忆当年在午桥桥上饮酒，在座的大多是英雄豪杰。长长的水沟里月影流动，悄无声息。在杏花稀疏的影子里，我们吹笛吹到天亮。二十多年过去了，就像一场梦，此身虽然还在，回想起来却令人心惊。如今闲来登上小阁，看看新晴的景色。古往今来多少兴亡之事，都化作三更时渔人的歌唱。', 'academic'),
  ('songci300', 137, '苏武慢·雁落平沙', 'songci-sc-148', '雁落平沙烟笼寒水古垒鸣笳声断青山隐隐败叶萧萧天际暝鸦零乱楼上黄昏片帆千里归程年华将晚望碧云空暮佳人何处梦魂俱远忆旧游邃馆朱扉小园香径尚想桃花人面书盈锦轴恨满金徽难写寸心幽怨两地离愁一尊芳酒凄凉危阑倚遍尽迟留凭仗西风吹干泪眼', '大雁落在平沙，烟雾笼着寒水，古垒的胡笳声断绝。青山隐约，败叶萧萧，天边暮鸦零乱。楼上已是黄昏，一片孤帆千里归程，年华将晚。望碧云笼着空暮，佳人在哪里？梦魂都远了。
回忆旧游，深馆朱门，小园香径，还记得桃花般的面容。书信写满锦轴，怨恨充满琴徽，也难写尽心中幽怨。两地离愁，一尊美酒，凄凉地把危栏倚遍。久久停留，全靠西风，吹干泪眼。', 'public-domain'),
  ('songci300', 138, '柳梢青·数声鶗鴂', 'songci-sc-149', '数声鶗鴂可怜又是春归时节满院东风海棠铺绣梨花飘雪丁香露泣残枝算未比愁肠寸结自是休文多情多感不干风月', '几声杜鹃啼叫，可怜又是春归的时节。满院东风，海棠铺成锦绣，梨花飘如雪。
丁香在残枝上泣露，算来也比不上我愁肠寸结。本是我像沈约那样多情多感，与风月无关。', 'public-domain'),
  ('songci300', 139, '鹧鸪天·一点残红欲尽时', 'songci-sc-150', '一点残红欲尽时乍凉秋气满屏帏梧桐叶上三更雨叶叶声声是别离调宝瑟拨金猊那时同唱鹧鸪词如今风雨西楼夜不听清歌也泪垂', '一点残灯将尽的时候，初凉的秋气充满屏帏。梧桐叶上三更的雨，每一叶每一声都是别离。
那时调宝瑟，拨香炉，一同唱《鹧鸪词》。如今风雨西楼之夜，不听清歌也落泪。', 'public-domain'),
  ('songci300', 140, '踏莎行·情似游丝', 'songci-sc-151', '情似游丝人如飞絮泪珠阁定空相觑一溪烟柳万丝垂无因系得兰舟住雁过斜阳草迷烟渚如今已是愁无数明朝且做莫思量如何过得今宵去', '情像游丝，人如飞絮。泪珠含住，只是空对着看。一溪烟柳垂下万丝，却没有办法系住兰舟。
大雁飞过斜阳，青草迷住烟渚。如今已是愁无数。明天的事暂且不去想，可今夜怎么捱得过去？', 'public-domain'),
  ('songci300', 141, '帝台春·芳草碧色', 'songci-sc-152', '芳草碧色萋萋遍南陌暖絮乱红也知人春愁无力忆得盈盈拾翠侣共携赏凤城寒食到今来海角逢春天涯为客愁旋释还似织泪暗拭又偷滴谩伫立遍倚危阑尽黄昏也只是暮云凝碧拚则而今已拚了忘则怎生便忘得又还问鳞鸿试重寻消息', '芳草碧绿，茂盛地长满南边小路。暖絮乱红，也知道人春愁无力。记得那盈盈的拾翠伴侣，一同到京城赏寒食。到如今，在海角逢春，在天涯作客。
愁刚解开，又像织起来；泪暗暗擦去，又偷偷滴下。白白地伫立，把危栏倚遍，直到黄昏，也只是暮云凝着碧色。舍弃既然已经舍弃了，要忘又怎么忘得掉。又去问鱼雁，试着重新打听消息。', 'public-domain'),
  ('songci300', 142, '忆王孙·萋萋芳草忆王孙', 'songci-sc-153', '萋萋芳草忆王孙柳外楼高空断魂杜宇声声不忍闻欲黄昏雨打梨花深闭门', '芳草萋萋，思念远行的人；柳外楼高，白白地令人断魂。杜鹃声声，不忍听闻。将近黄昏，雨打着梨花，深深把门关上。', 'public-domain'),
  ('songci300', 143, '三台·见梨花初带夜月', 'songci-sc-154', '见梨花初带夜月海棠半含朝雨内苑春不禁过青门御沟涨潜通南浦东风静细柳垂金缕望凤阙非烟非雾好时代朝野多欢遍九陌太平箫鼓乍莺儿百啭断续燕子飞来飞去近绿水台榭映秋千斗草聚双双游女饧香更酒冷踏青路会暗识夭桃朱户向晚骤宝马雕鞍醉襟惹乱花飞絮正轻寒轻暖漏永半阴半晴云暮禁火天已是试新妆岁华到三分佳处清明看汉蜡传宫炬烟散后云归何处敛兵卫阊阖门开住传宣又还休务', '看梨花初带上夜月，海棠半含着朝雨。宫苑的春色禁不住越过宫门，御沟水涨暗暗通到南浦。东风静，细柳垂下金丝。望皇宫，非烟非雾。好时代，朝野多欢，满城都是太平的箫鼓。
黄莺骤然百般啼啭、断断续续，燕子飞来飞去。绿水边台榭映着秋千，斗草的人聚在一处，是一双双游女。饧糖香、酒已冷，就在踏青路上。在夭桃朱门处暗暗相识。傍晚时宝马雕鞍，醉襟上沾着乱花飞絮。
正是轻寒轻暖、漏声悠长，半阴半晴、云色向暮。禁火时节，已经试过新妆，一年的好景到了三分佳处。清明时看宫中传烛，烟散之后云归何处？收起兵卫，宫门大开，停止传宣，又要休沐。', 'public-domain'),
  ('songci300', 144, '二郎神·闷来弹鹊', 'songci-sc-155', '闷来弹鹊又搅碎一帘花影漫试著春衫还思纤手熏彻金猊烬冷动是愁端如何向但怪得新来多病嗟旧日沈腰如今潘鬓怎堪临镜重省别时泪湿罗衣犹凝料为我厌厌日高慵起长托春酲未醒雁足不来马蹄难驻门掩一庭芳景空伫立尽日阑干倚遍昼长人静', '闷来弹打喜鹊，又搅碎了一帘花影。随意试穿春衫，又想起那纤纤素手，香炉里的火已冷。动不动就是愁的由头，怎么办？只怪近来多病。可叹旧日像沈约那样瘦，如今又添潘岳的白发，怎么受得住照镜？
重新回想。分别时泪湿的罗衣，至今还有痕迹。料她为我恹恹无绪，日头高了还懒得起床，总推说春酒未醒。雁足不来，马蹄难留，门掩着一庭芳景。白白伫立，整日把栏杆倚遍，昼长人静。', 'public-domain'),
  ('songci300', 145, '江神子慢·玉台挂秋月', 'songci-sc-156', '玉台挂秋月铅素浅梅花傅香雪冰姿洁金莲衬小小凌波罗袜雨初歇楼外孤鸿声渐远远山外行人音信绝此恨对语犹难那堪更寄书说教人红消翠减觉衣宽金缕都为轻别太情切消魂处画角黄昏时节声呜咽落尽庭花春去也银蟾迥无情圆又缺恨伊不似余香惹鸳鸯结', '玉台上挂着秋月，她脂粉淡薄，像梅花敷着香雪。冰姿洁净。金莲鞋衬着小小的凌波罗袜。雨刚停。楼外孤雁声渐渐远去，远山之外，行人的音信断绝。这份恨面对面说都难，哪堪再写信去说。
叫人红消翠减，觉得金缕衣都宽了，都因为轻易的离别。太情切。消魂的地方，是黄昏画角响起时。声音呜咽。庭花落尽，春天去了；明月高远，无情地圆了又缺。恨他不像我身上余香，能结成鸳鸯。', 'public-domain'),
  ('songci300', 146, '蓦山溪·洗妆真态', 'songci-sc-157', '洗妆真态不作铅华御竹外一枝斜想佳人天寒日暮黄昏院落无处著清香风细细雪垂垂何况江头路月边疏影梦到消魂处结子欲黄时又须作廉纤小雨孤芳一世供断有情愁消瘦损东阳也试问花知否', '洗去妆饰的本真态度，不用脂粉来修饰。竹外一枝斜出，想那佳人，在天寒日暮的时候。黄昏的院落，清香无处安放；风细细，雪垂垂，何况江头的路上。
月边的疏影，梦到消魂的地方。等结子将要黄时，又该下起纤细的小雨。孤芳一世，供尽了有情人的愁，人瘦损如沈约，试问花知道吗？', 'public-domain'),
  ('songci300', 147, '贺新郎·篆缕销金鼎', 'songci-sc-158', '篆缕销金鼎醉沉沉庭阴转午画堂人静芳草王孙知何处惟有杨花糁径渐玉枕腾腾春醒帘外残红春已透镇无聊殢酒厌厌病云鬓乱未忺整江南旧事休重省遍天涯寻消问息断鸿难倩月满西楼凭阑久依旧归期未定又只恐瓶沉金井嘶骑不来银烛暗枉教人立尽梧桐影谁伴我对鸾镜', '香炉里的篆烟消散。醉意沉沉，庭中树荫转过午后，画堂里人声寂静。芳草萋萋，那远行的人在哪里？只有杨花散在小径上。玉枕上渐渐从春睡中醒来。帘外残红，春天已过；整日无聊，被酒困着，恹恹成病。云鬓散乱，也懒得整理。
江南的旧事不要再回想。走遍天涯寻消息，孤雁也难以托付。月满西楼，我倚栏很久，归期依旧未定。又只怕像瓶沉金井，音信全无。嘶鸣的马不来，银烛已暗，白白教人站到梧桐影尽。谁来陪我，面对鸾镜？', 'public-domain'),
  ('songci300', 148, '烛影摇红·霭霭春空', 'songci-sc-159', '霭霭春空画楼森耸凌云渚紫薇登览最关情绝妙夸能赋惆怅相思迟暮记当日朱阑共语塞鸿难问岸柳何穷别愁纷絮催促年光旧来流水知何处断肠何必更残阳极目伤平楚晚霁波声带雨悄无人舟横野渡数峰江上芳草天涯参差烟树', '春空云气弥漫，画楼高耸直入云中的洲渚。登楼览景最牵动感情，前人绝妙的赋作值得称夸。惆怅相思已到迟暮，记得当日同在朱栏边说话。塞雁难问，岸柳无穷，别愁像纷乱的柳絮。
年光被催促，旧日的流水如今在哪里？断肠何必再对着残阳，极目望去，平野令人伤心。晚晴后波声带着雨意。悄无人影，孤舟横在野渡。江上几座山峰，天涯一片芳草，参差的烟树。', 'public-domain'),
  ('songci300', 149, '薄幸·青楼春晚', 'songci-sc-160', '青楼春晚昼寂寂梳匀又懒乍听得鸦啼莺弄惹起新愁无限记年时偷掷春心花间隔雾遥相见便角枕题诗宝钗贳酒共醉青苔深院怎忘得回廊下携手处花明月满如今但暮雨蜂愁蝶恨小窗闲对芭蕉展却谁拘管尽无言闲品秦筝泪满参差雁腰支渐小心与杨花共远', '青楼里春天已晚，白天寂静，梳好妆又懒懒的。忽然听见乌鸦啼、黄莺叫，惹起无限新愁。记得那年，偷偷掷出春心，隔着花丛的雾远远相见。于是角枕上题诗，用宝钗换酒，一同醉在青苔深院。
怎么忘得掉回廊下携手的地方，那时花明月满。如今只有暮雨，蜂愁蝶恨，小窗闲对着舒展的芭蕉。又有谁来管我？只是默默无言地闲弹秦筝，泪落满参差的雁柱。腰肢渐细，心与杨花一同远去。', 'public-domain'),
  ('songci300', 150, '透碧宵·舣兰舟', 'songci-sc-161', '舣兰舟十分端然俯清流玉人娇困宝钗慵整绣阁还羞轻寒轻暖雨膏烟腻画舸频游正春浓花艳香稠渐分飞双燕愁红敛翠恨别悠悠念酒徒云散花时孤负往事怎追游断云低孤雁远空目断碧云楼自怜春晚情怀不似旧日风流但赢得多愁多病多痛双鬓先秋', '兰舟靠岸，十分端正地俯看清流。玉人娇困，宝钗慵懒地不去整理，绣阁里还有些羞意。天气轻寒轻暖，雨润烟浓，画船频频出游。正是春浓花艳香稠的时候。渐渐双燕分飞，愁红敛翠，恨那别离悠悠。
想酒友如云散，花期被辜负，往事怎么去追寻？断云低垂，孤雁远去，白白望断碧云楼。自怜春天已晚，情怀不似旧日的风流。只赢得许多愁，多病多痛，双鬓先白了。', 'public-domain'),
  ('songci300', 151, '南浦·风悲画角', 'songci-sc-162', '风悲画角听单于三弄落谯门投宿骎骎征骑飞雪满孤村酒市渐阑灯火正敲窗乱叶舞纷纷送数声惊雁乍离烟水嘹唳度寒云好在半胧淡月到如今无处不消魂故国梅花归梦愁损绿罗裙为问暗香闲艳也相思万点付啼痕算翠屏应是两眉余恨倚黄昏', '风中画角悲鸣，听《单于》三弄从谯门落下。投宿的征骑匆匆赶路，飞雪落满孤村。酒市的灯火渐渐阑珊，正是乱叶敲窗、纷纷飞舞的时候。送走几声惊雁，它们刚离开烟水，嘹唳着飞过寒云。
半朦胧的淡月还好，到如今无处不令人消魂。故国的梅花入归梦，愁坏了她绿罗裙。试问那暗香闲艳，是否也在相思，万点落成啼痕。算来翠屏里的人应是两眉含着余恨，倚到黄昏。', 'public-domain'),
  ('songci300', 152, '满江红·怒发冲冠', 'songci-sc-288', '怒发冲冠凭栏处潇潇雨歇抬望眼仰天长啸壮怀激烈三十功名尘与土八千里路云和月莫等闲白了少年头空悲切靖康耻犹未雪臣子恨何时灭驾长车踏破贺兰山缺壮志饥餐胡虏肉笑谈渴饮匈奴血待从头收拾旧山河朝天阙', '愤怒得头发直竖顶起帽子，独自凭栏，一场急雨刚刚停歇。抬起眼望向远方，仰天长啸，满腔报国之心激烈涌动。三十年的功名如同尘土，八千里的征程唯有云月相伴。不要虚度年华，等到少年白头，徒然悲伤。
靖康年间的耻辱，还未洗雪；做臣子的遗恨，何时才能消除。驾着战车，踏破贺兰山的隘口。壮志满怀，饿了就吃敌人的肉，谈笑间渴了就饮匈奴的血。等到重新收复旧日山河，再向朝廷报捷。', 'public-domain'),
  ('songci300', 153, '烛影摇红·双阙中天', 'songci-sc-164', '双阙中天凤楼十二春寒浅去年元夜奉宸游曾侍瑶池宴玉殿珠帘尽卷拥群仙蓬壶阆苑五云深处万烛光中揭天丝管驰隙流年恍如一瞬星霜换今宵谁念泣孤臣回首长安远可是尘缘未断谩惆怅华胥梦短满怀幽恨数点寒灯几声归雁', '双阙耸立天际，十二座凤楼间春寒尚浅。去年元宵夜随驾出游，曾侍瑶池之宴。玉殿上珠帘尽卷，拥着群仙，如在蓬壶阆苑。五色云深处，万烛光中，丝管之声震天。
流年如白驹过隙，恍惚一瞬星霜就换了。今夜谁念我这泣泪的孤臣？回首长安已远。难道是尘缘未断？白白惆怅，华胥梦太短。满怀幽恨，几点寒灯，几声归雁。', 'public-domain'),
  ('songci300', 154, '水龙吟·夜来风雨匆匆', 'songci-sc-165', '夜来风雨匆匆故园定是花无几愁多怨极等闲孤负一年芳意柳困桃慵杏青梅小对人容易算好春长在好花长见原只是人憔悴回首池南旧事恨星星不堪重记如今但有看花老眼伤时清泪不怕逢花瘦只愁怕老来风味待繁红乱处留云借月也须拚醉', '夜里风雨匆匆，故园的花一定不剩多少了。愁多怨极，轻易辜负了一年芳意。柳困桃惰，杏青梅小，对人都不在意。算来好春长在，好花常开，只是人憔悴了。
回望池南旧事，恨白发星星，不堪再记。如今只有看花的老眼、伤时的清泪。不怕见花憔悴，只愁老来的心境。等到繁红纷乱的时候，留住云借来月，也要拼着一醉。', 'public-domain'),
  ('songci300', 155, '六州歌头·长淮望断', 'songci-sc-166', '长淮望断关塞莽然平征尘暗霜风劲悄边声黯销凝追想当年事殆天数非人力洙泗上弦歌地亦膻腥隔水毡乡落日牛羊下区脱纵横看名王宵猎骑火一川明笳鼓悲鸣遣人惊念腰间箭匣中剑空埃蠹竟何成时易失心徒壮岁将零渺神京干羽方怀远静烽燧且休兵冠盖使纷驰骛若为情闻道中原遗老常南望翠葆霓旌使行人到此忠愤气填膺有泪如倾', '望断淮河，关塞一片荒草平铺。征尘暗淡，霜风强劲，边地悄无声音。黯然神伤。追想当年的事，大概是天数，不是人力；洙水泗水之上，本是弦歌礼乐之地，如今也沾了膻腥。隔水就是毡帐之乡，落日里牛羊下来，敌人的哨所纵横。看那敌军首领夜间打猎，骑兵的火把照亮一川。胡笳战鼓悲鸣，令人心惊。
想腰间的箭、匣中的剑，白白地积尘生蠹，终究成了什么！时机容易错过，心虽壮，年岁将尽。京城渺远。朝廷正以礼乐怀柔远人，熄灭烽火，暂且休兵。使者车马纷纷奔驰，叫人何以堪受！听说中原的遗民，常常向南盼望皇帝的仪仗。让行人来到这里，忠愤之气填满胸膛，泪如雨下。', 'public-domain'),
  ('songci300', 156, '瑞鹤仙·郊原初过雨', 'songci-sc-169', '郊原初过雨见败叶零乱风定犹舞斜阳挂深树映浓愁浅黛遥山眉妩来时旧路尚岩花娇黄半吐到而今唯有溪边流水见人如故无语邮亭深静下马还寻旧曾题处无聊倦旅伤离恨最愁苦纵收香藏镜他年重到人面桃花在否念沉沉小阁幽窗有时梦去', '郊野刚下过雨，见败叶零乱，风停了还在飞舞。斜阳挂在深树间，映出浓愁般的浅黛，远山像美人的眉。来时的旧路，还有岩上的花娇黄半开。到如今，只有溪边的流水，见了人还如故。
无语。邮亭深静，下马再去寻找旧日题字的地方。无聊的倦旅，伤离恨，最是愁苦。纵然收起香、藏起镜，他年重来时，那人面桃花还在吗？想那沉沉的小阁幽窗，有时在梦里去。', 'public-domain'),
  ('songci300', 157, '剑器近·夜来雨', 'songci-sc-170', '夜来雨赖倩得东风吹住海棠正妖娆处且留取悄庭户试细听莺啼燕语分明共人愁绪怕春去佳树翠阴初转午重帘未卷乍睡起寂寞看风絮偷弹清泪寄烟波见江头故人为言憔悴如许彩笺无数去却寒暄到了浑无定据断肠落日千山暮', '夜里的雨，幸得东风把它吹住。海棠正妖娆的时候，且留住它。庭院悄悄，试着细听莺啼燕语。分明和人一样有愁绪，怕春天归去。
美好的树，绿荫初转过午后。重帘未卷，刚睡起，寂寞地看风中的柳絮。偷偷弹去清泪寄给烟波，若见到江头的故人，替我说我憔悴成这样。彩笺无数，除去寒暄，到头来全无准信。断肠时落日下千山已暮。', 'public-domain'),
  ('songci300', 158, '安公子·弱柳千丝缕', 'songci-sc-171', '弱柳千丝缕嫩黄匀遍鸦啼处寒入罗衣春尚浅过一番风雨问燕子来时绿水桥边路曾画楼见个人人否料静掩云窗尘满哀弦危柱庾信愁如许为谁都著眉端聚独立东风弹泪眼寄烟波东去念永昼春闲人倦如何度闲傍枕百啭黄鹂语唤觉来厌厌残照依然花坞', '柔弱的柳丝千缕，嫩黄匀在乌鸦啼叫的地方。寒气侵入罗衣，春意还浅，又经过一番风雨。问燕子来时，绿水桥边的路上，可曾在画楼见过那个人？料想她静静掩着云窗，灰尘落满琴柱。
庾信那样的愁有多少，为了谁聚在眉端？独自站在东风里弹去泪眼，托烟波向东带去。想那长长的春日闲人倦，怎么捱过？闲靠着枕头，听黄鹂百啭。被唤醒后恹恹无绪，残照依然照着花坞。', 'public-domain'),
  ('songci300', 159, '瑞鹤仙·脸霞红印枕', 'songci-sc-172', '脸霞红印枕睡觉来冠儿还是不整屏间麝煤冷但眉峰压翠泪珠弹粉堂深昼永燕交飞风帘露井恨无人说与相思近日带围宽尽重省残灯朱幌淡月纱窗那时风景阳台路迥云雨梦便无准待归来先指花梢教看却把心期细问问因循过了青春怎生意稳', '脸上的红霞印在枕上，睡醒来，冠儿还是不整。屏风间的香墨冷了，只见眉峰压着翠色，泪珠冲下脂粉。堂深昼长，燕子交错飞过风帘露井。恨无人可以诉说：近日相思，衣带都宽尽了。
重新回想，残灯朱帐、淡月纱窗，那时的风景。阳台的路遥远，云雨之梦便无准信。等他回来，先指着花梢让他看，再把心中期望细细追问。问他为什么因循蹉跎过了青春，怎么就能心安？', 'public-domain'),
  ('songci300', 160, '卜算子·驿外断桥边', 'poems-cz8-29', '驿外断桥边寂寞开无主已是黄昏独自愁更著风和雨无意苦争春一任群芳妒零落成泥碾作尘只有香如故', '驿站之外的断桥边，梅花寂寞地开放，无人过问。已是黄昏时分，她独自忧愁，又遭到风雨的摧残。她本来无意苦苦争夺春光，任凭百花去嫉妒。即使凋零飘落被碾作尘土，只有那清香依旧如故。', 'school');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 161, '钗头凤·红酥手', 'songci-sc-174', '红酥手黄縢酒满城春色宫墙柳东风恶欢情薄一怀愁绪几年离索错错错春如旧人空瘦泪痕红浥鲛绡透桃花落闲池阁山盟虽在锦书难托莫莫莫', '她红润柔嫩的手，捧着黄封酒；满城春色，宫墙边一片柳。东风可恶，欢情太薄。满怀愁绪，几年离索。错、错、错。
春天还如旧，人却白白瘦了；泪痕和着脂粉，把手帕都湿透。桃花落了，池阁空着。山盟虽在，书信难托。莫、莫、莫。', 'public-domain'),
  ('songci300', 162, '水龙吟·闹花深处层楼', 'songci-sc-175', '闹花深处层楼画帘半卷东风软春归翠陌平莎茸嫩垂杨金浅迟日催花淡云阁雨轻寒轻暖恨芳菲世界游人未赏都付与莺和燕寂寞凭高念远向南楼一声归雁金钗斗草青丝勒马风流云散罗绶分香翠绡封泪几多幽怨正消魂又是疏烟淡月子规声断', '繁花深处的层楼，画帘半卷，东风柔软。春天回到翠绿的路上，平铺的莎草细嫩，垂杨垂下浅金色。迟迟的日光催花，淡云停雨，轻寒轻暖。恨这芳菲世界，游人还未赏看，都交给了黄莺和燕子。
寂寞中登高念远，向南楼听一声归雁。金钗斗草、青丝勒马的日子，都风流云散。罗带分香，翠绡封泪，有多少幽怨！正消魂时又是疏烟淡月，杜鹃声断。', 'public-domain'),
  ('songci300', 163, '眼儿媚·酣酣日脚紫烟浮', 'songci-sc-176', '酣酣日脚紫烟浮妍暖破轻裘困人天色醉人花气午梦扶头春慵恰似春塘水一片縠纹愁溶溶泄泄东风无力欲皱还休', '暖融的日脚紫烟浮起，晴暖得可以脱下轻裘。困人的天色，醉人的花气，午梦里昏昏沉沉。
春困恰似春塘的水，一片绉纱似的愁。溶溶泄泄，东风无力，要起波纹又停下。', 'public-domain'),
  ('songci300', 164, '霜天晓角·晚晴风歇', 'songci-sc-177', '晚晴风歇一夜春威折脉脉花疏天淡云来去数枝雪胜绝愁亦绝此情谁共说惟有两行低雁知人倚画楼月', '傍晚放晴，风停了，一夜之间春寒的威势被折住。花疏天淡，含情脉脉；云来云去，几枝如雪。
美到极处，愁也到极处。这份情向谁诉说？只有两行低飞的大雁，知道人正倚着画楼看月。', 'public-domain'),
  ('songci300', 165, '贺新郎·绿树听鹈鴂', 'songci-sc-178', '绿树听鹈鴂更那堪鹧鸪声住杜鹃声切啼到春归无寻处苦恨芳菲都歇算未抵人间离别马上琵琶关塞黑更长门翠辇辞金阙看燕燕送归妾将军百战身名裂向河梁回头万里故人长绝易水萧萧西风冷满座衣冠似雪正壮士悲歌未彻啼鸟还知如许恨料不啼清泪长啼血谁共我醉明月', '在绿树间听鹈鴂啼叫。更哪堪鹧鸪声刚停，杜鹃又叫得凄切。啼到春天归去无处可寻，苦恨百花都歇了。算来还比不上人间的离别。昭君骑在马上弹琵琶，关塞昏黑；还有陈皇后乘翠辇辞别金阙。看燕子飞，送走远嫁的人。
李陵将军百战之身落得身败名裂。在河梁上回头万里，与故人永诀。易水萧萧，西风冷，满座衣冠白如雪。正是壮士悲歌未终。啼鸟还知道这些恨，料想它不啼清泪而长啼血。谁来陪我，在明月下醉倒。', 'public-domain'),
  ('songci300', 166, '念奴娇·野棠花落', 'songci-sc-179', '野棠花落又匆匆过了清明时节刬地东风欺客梦一枕云屏寒怯曲岸持觞垂杨系马此地曾轻别楼空人去旧游飞燕能说闻道绮陌东头行人曾见帘底纤纤月旧恨春江流不断新恨云山千叠料得明朝尊前重见镜里花难折也应惊问近来多少华发', '野棠花落，又匆匆过了清明时节。无端的东风欺我客梦，枕上对着云屏只觉寒怯。曲岸边举杯，垂杨下系马，就在这里曾经轻易分别。楼空人去，旧游只有飞燕还能说。
听说繁华街市东头，有人曾见过帘下那弯纤纤的月。旧恨像春江流不断，新恨像云山千叠。料想明朝在杯前重见，镜中之花难以折取。她也该惊问：近来添了多少白发？', 'public-domain'),
  ('songci300', 167, '汉宫春·春已归来', 'songci-sc-180', '春已归来看美人头上袅袅春幡无端风雨未肯收尽余寒年时燕子料今宵梦到西园浑未办黄柑荐酒更传青韭堆盘却笑东风从此便薰梅染柳更没些闲闲时又来镜里转变朱颜清愁不断问何人会解连环生怕见花开花落朝来塞雁先还', '春天已经回来了，看美人头上，袅袅的春幡。无端的风雨，不肯把余寒收尽。去年的燕子，料想今夜会梦到西园。还全没备好黄柑荐酒，更别说传青韭堆盘。
却笑东风从此就要熏梅染柳，再没有一点空闲。闲下来又到镜子里，把红颜转变。清愁不断，问谁人能解开连环？最怕看见花开花落——清晨塞雁已经先归去了。', 'public-domain'),
  ('songci300', 168, '贺新郎·凤尾龙香拨', 'songci-sc-181', '凤尾龙香拨自开元霓裳曲罢几番风月最苦浔阳江头客画舸亭亭待发记出塞黄云堆雪马上离愁三万里望昭阳宫殿孤鸿没弦解语恨难说辽阳驿使音尘绝琐窗寒轻拢慢捻泪珠盈睫推手含情还却手一抹梁州哀彻千古事云飞烟灭贺老定场无消息想沉香亭北繁华歇弹到此为呜咽', '凤尾形的琵琶槽，龙香柏制的拨子。自从开元年间《霓裳羽衣曲》奏罢，经历了多少番风月？最苦的是浔阳江头那位客人，画船亭亭正待出发。记得昭君出塞时，黄沙如云、积雪成堆。马上的离愁有三万里，遥望昭阳宫殿，只见孤雁没入天际。琵琶弦能说话，这遗恨却难以诉说。
辽阳来的驿使音信断绝。冷清的小窗前，轻轻拢、慢慢捻，泪珠盈满睫毛。推手含情又却手，《梁州》一曲弹得哀伤透彻。千古兴亡事，都如云飞烟灭。贺怀智那样的定场高手已无消息，想来沉香亭北的繁华也已消歇。弹到这里，令人呜咽。', 'public-domain'),
  ('songci300', 169, '水龙吟·楚天千里清秋', 'songci-sc-182', '楚天千里清秋水随天去秋无际遥岑远目献愁供恨玉簪螺髻落日楼头断鸿声里江南游子把吴钩看了阑干拍遍无人会登临意休说鲈鱼堪脍尽西风季鹰归未求田问舍怕应羞见刘郎才气可惜流年忧愁风雨树犹如此倩何人唤取红巾翠袖揾英雄泪', '楚地天空千里清秋，江水随天而去，秋色无边。远望群山，像在献愁供恨，如玉簪螺髻。落日楼头，孤雁声里，我这江南游子。把吴钩看了又看，把栏杆拍遍，没有人懂得我登临的心意。
不要说鲈鱼可以脍，西风起了，张季鹰归去了没有？买田置屋，怕该羞见刘备那样的才气。可惜流年，忧愁风雨，树都长得这样大了！请谁去唤来红巾翠袖的歌女，替我擦干英雄的泪！', 'public-domain'),
  ('songci300', 170, '摸鱼儿·更能消', 'songci-sc-184', '更能消几番风雨匆匆春又归去惜春长怕花开早何况落红无数春且住见说道天涯芳草无归路怨春不语算只有殷勤画檐蛛网尽日惹飞絮长门事准拟佳期又误蛾眉曾有人妒千金纵买相如赋脉脉此情谁诉君莫舞君不见玉环飞燕皆尘土闲愁最苦休去倚危阑斜阳正在烟柳断肠处', '还能经得几番风雨，春天又匆匆归去。惜春总怕花开得太早，何况落红无数。春天你且留下！听说天涯芳草，没有归路。怨春不语。算来只有画檐上的蛛网殷勤，整日粘着飞絮。
长门宫的事，本预计好的佳期又被误了。美人总有人嫉妒。纵然花千金买来相如的赋，这脉脉情意向谁诉说？你不要舞！你没看见杨玉环、赵飞燕都成了尘土。闲愁最苦。不要去倚危栏，斜阳正照在烟柳断肠之处。', 'public-domain'),
  ('songci300', 171, '永遇乐·千古江山', 'poems-gz10-08', '千古江山英雄无觅孙仲谋处舞榭歌台风流总被雨打风吹去斜阳草树寻常巷陌人道寄奴曾住想当年金戈铁马气吞万里如虎元嘉草草封狼居胥赢得仓皇北顾四十三年望中犹记烽火扬州路可堪回首佛狸祠下一片神鸦社鼓凭谁问廉颇老矣尚能饭否', '千古以来的江山依旧，却再也找不到孙权那样的英雄了。当年的歌舞楼台，那些风流业绩，都被雨打风吹得无影无踪。夕阳照着衰草杂树，那些普通的街巷，人们说刘裕曾经在这里住过。想当年，他金戈铁马，气势如虎，吞掉了万里江山。元嘉年间草率出兵，想建立像封狼居胥那样的功业，却落得仓皇败退、回头北望。四十三年过去了，望中还记得当年扬州路上烽火连天的情景。怎么忍心回头看呢，佛狸祠下，一片神鸦的叫声和社日的鼓声。靠谁来问：廉颇老了，饭量还好吗？', 'academic'),
  ('songci300', 172, '木兰花·年年跃马长安市', 'songci-sc-212', '年年跃马长安市客舍似家家似寄青钱换酒日无何红烛呼卢宵不寐易挑锦妇机中字难得玉人心下事男儿西北有神州莫滴水西桥畔泪', '年年跃马在长安街市，客舍像家、家倒像寄居。青钱换酒，天天无事；红烛下呼卢赌博，通宵不睡。
容易挑出织锦妇人的回文诗，难得明白美人心中的事。男儿在西北还有神州故土，不要在滴水的西桥边落泪！', 'public-domain'),
  ('songci300', 173, '青玉案·凌波不过横塘路', 'songci-sc-129', '凌波不过横塘路但目送芳尘去锦瑟华年谁与度月桥花院琐窗朱户只有春知处飞云冉冉蘅皋暮彩笔新题断肠句试问闲愁都几许一川烟草满城风絮梅子黄时雨', '她轻盈的脚步不过横塘路，我只能目送她带着芳香的尘土远去。锦瑟般的年华与谁共度？月桥花院，雕窗朱户，只有春天知道她的去处。
飞云缓缓，长满香草的水边已近黄昏，我提彩笔新写下断肠的句子。试问我的闲愁有多少？就像一川烟草、满城风絮、梅子黄时的细雨。', 'public-domain'),
  ('songci300', 174, '薄幸·淡妆多态', 'songci-sc-131', '淡妆多态更的的频回眄睐便认得琴心先许欲绾合欢双带记画堂风月逢迎轻颦浅笑娇无奈向睡鸭炉边翔鸳屏里羞把香罗暗解自过了烧灯后都不见踏青挑菜几回凭双燕叮咛深意往来却恨重帘碍约何时再正春浓酒困人闲昼永无聊赖厌厌睡起犹有花梢日在', '她淡妆多态，又频频回头顾盼。便知道她已先许下琴心，想结起合欢的双带。记得在画堂里风月相迎，她轻蹙双眉、浅浅一笑，娇得无可奈何。在睡鸭炉边、翔鸳屏风里，羞怯地暗暗解下香罗。
自从灯节过后，都不见踏青挑菜的约会。几次托双燕，叮咛深意，往来却恨重重帘幕阻隔。约好何时再见？正当春浓酒困，人闲昼长，无聊赖。懒懒地睡起，花梢上还挂着日影。', 'public-domain'),
  ('songci300', 175, '浣溪沙·楼角初销一缕霞', 'songci-sc-132', '楼角初销一缕霞淡黄杨柳暗栖鸦玉人和笑摘梅花笑捻粉香归洞户更垂帘幕护窗纱东风寒似夜来些', '楼角的最后一缕霞光刚刚消散，淡黄杨柳里暗栖着乌鸦。玉人含笑去摘梅花。
她笑着捻着粉香回到内室，又垂下帘幕护住窗纱。东风比昨夜还要冷一些。', 'public-domain'),
  ('songci300', 176, '石州慢·薄雨收寒', 'songci-sc-133', '薄雨收寒斜照弄晴春意空阔长亭柳色才黄远客一枝先折烟横水际映带几点归鸦东风销尽龙沙雪还记出关来恰而今时节将发画楼芳酒红泪清歌顿成轻别已是经年杳杳音尘多绝欲知方寸共有几许清愁芭蕉不展丁香结枉望断天涯两厌厌风月', '小雨收去寒意，斜阳弄晴，春意空阔。长亭的柳色刚黄，远客已先折了一枝。烟雾横在水边，映带几点归鸦，东风把塞外的雪都消尽了。还记得出关来时，正是如今这个时节。
将要出发时，画楼上芳香的美酒、她带泪的清歌，顿时成了轻易的离别。已经过了一年，音信多已断绝。要知道我心里有多少清愁？就像芭蕉不展、丁香结蕾。白白望断天涯，两人都在风月里恹恹无绪。', 'public-domain'),
  ('songci300', 177, '天门谣·牛渚天门险', 'songci-sc-135', '牛渚天门险限南北七雄豪占清雾敛与闲人登览待月上潮平波滟滟塞管轻吹新阿滥风满槛历历数西州更点', '牛渚天门形势险要，隔开南北，七国豪杰都曾占据。清雾收敛，让闲人登临观赏。
等到月出潮平，波光滟滟，塞管轻吹新曲《阿滥堆》。风满栏杆，清晰地数着西州的更点。', 'public-domain'),
  ('songci300', 178, '天香·烟络横林', 'songci-sc-136', '烟络横林山沉远照迤逦黄昏钟鼓烛映帘栊蛩催机杼共苦清秋风露不眠思妇齐应和几声砧杵惊动天涯倦宦骎骎岁华行暮当年酒狂自负谓东君以春相付流浪征骖北道客樯南浦幽恨无人晤语赖明月曾知旧游处好伴云来还将梦去', '烟雾缠绕横林，远山沉入夕照，黄昏的钟鼓声连绵不断。烛光映着帘栊，蟋蟀催人纺织，一同受着清秋风露之苦。不眠的思妇，几声砧杵齐相应和。惊动了天涯倦宦，岁月匆匆将暮。
当年以酒狂自负，以为春神会把春天交给我。如今却流浪在北道征鞍、南浦客舟。幽恨无人可以面谈。幸赖明月曾知旧游之处。好伴着云来，再把梦带去。', 'public-domain'),
  ('songci300', 179, '望湘人·厌莺声到枕', 'songci-sc-137', '厌莺声到枕花气动帘醉魂愁梦相半被惜余薰带惊剩眼几许伤春春晚泪竹痕鲜佩兰香老湘天浓暖记小江风月佳时屡约非烟游伴须信鸾弦易断奈云和再鼓曲中人远认罗袜无踪旧处弄波清浅青翰棹舣白苹洲畔尽目临皋飞观不解寄一字相思幸有归来双燕', '厌听莺声传到枕边，花香拂动帘子，醉魂与愁梦各占一半。怜惜被上残留的香气，惊见腰带宽出许多孔，多少伤春之情，春天已晚。湘妃竹的泪痕还新，佩兰的香气已老，湘天浓暖。记得在江边风月最好的时候，多次约她同游。
要知道鸾弦容易断，奈何重新鼓瑟，曲中人已远。认那罗袜的踪迹已无，旧日她戏水的清浅之处。乘着青翰船靠岸，停在白苹洲边。极目望那临皋的高楼。不会寄一个字来诉相思，幸有一双归燕。', 'public-domain'),
  ('songci300', 180, '绿头鸭·玉人家', 'songci-sc-138', '玉人家画楼珠箔临津托微风彩箫流怨断肠马上曾闻宴堂开艳妆丛里调琴思认歌颦麝蜡烟浓玉莲漏短更衣不待酒初醺绣屏掩枕鸳相就香气渐暾暾回廊影疏钟淡月几许消魂翠钗分银笺封泪舞鞋从此生尘任兰舟载将离恨转南浦背西曛记取明年蔷薇谢后佳期应未误行云凤城远楚梅香嫩先寄一枝春青门外只凭芳草寻访郎君', '玉人家住画楼，珠帘临着渡口。托微风送去彩箫的哀怨，那断肠的曲子在马上曾听过。宴堂开时，艳妆丛中，她调琴的情思、唱歌时皱眉的样子我都认得。麝香蜡烛烟浓，玉莲漏滴得短，还没等酒上脸就换了衣裳。绣屏掩上，鸳鸯枕相就，香气渐渐暖浓。回廊的影子、疏钟与淡月，有多少消魂？
翠钗分作两半，银笺封着泪，舞鞋从此生了尘。任凭兰舟载着离恨，转过南浦，背向西沉的落日。记住明年蔷薇谢后，佳期该不会误了行云之约。京城遥远，楚地的梅花香嫩，先寄一枝春去。青门外，只凭芳草，来寻找郎君。', 'public-domain'),
  ('songci300', 181, '点绛唇·燕雁无心', 'songci-sc-185', '燕雁无心太湖西畔随云去数峰清苦商略黄昏雨第四桥边拟共天随住今何许凭阑怀古残柳参差舞', '燕地的雁无心停留，在太湖西畔随云飞去。几座山峰清苦，正商量着黄昏的雨。
第四桥边，本想与陆天随同住。如今在哪里？倚栏怀古，只见残柳参差舞动。', 'public-domain'),
  ('songci300', 182, '鹧鸪天·肥水东流无尽期', 'songci-sc-186', '肥水东流无尽期当初不合种相思梦中未比丹青见暗里忽惊山鸟啼春未绿鬓先丝人间别久不成悲谁教岁岁红莲夜两处沉吟各自知', '肥水向东流去没有尽期，当初不该种下相思。梦里相见还不如画像分明，暗中忽然被山鸟啼声惊醒。
春草还没绿，两鬓先白了。人间离别久了也就悲哀不起来。是谁让年年元宵灯夜，两人在两地各自沉吟，只有自己知道。', 'public-domain'),
  ('songci300', 183, '踏莎行·燕燕轻盈', 'songci-sc-187', '燕燕轻盈莺莺娇软分明又向华胥见夜长争得薄情知春初早被相思染别后书辞别时针线离魂暗逐郎行远淮南皓月冷千山冥冥归去无人管', '像燕子一样轻盈，像黄莺一样娇软，分明又在梦里相见。夜长怎么让薄情的人知道？春天刚开始就已被相思染上。
别后的书信，别时的针线，离魂暗暗随着郎的行踪远去。淮南的皓月冷照千山，她幽幽地归去，无人照管。', 'public-domain'),
  ('songci300', 184, '齐天乐·庾郎先自吟愁赋', 'songci-sc-188', '庾郎先自吟愁赋凄凄更闻私语露湿铜铺苔侵石井都是曾听伊处哀音似诉正思妇无眠起寻机杼曲曲屏山夜凉独自甚情绪西窗又吹暗雨为谁频断续相和砧杵候馆迎秋离宫吊月别有伤心无数豳诗漫与笑篱落呼灯世间儿女写入琴丝一声声更苦', '庾信先自吟起愁赋，凄凄地又听见蟋蟀私语。露水湿了铜铺首，青苔侵上石井，都是曾听它鸣叫的地方。哀音像在诉说。正是思妇无法入睡，起身去找机杼。曲曲屏风，夜凉里独自是什么情绪？
西窗又被暗雨吹打。它为谁频频断续，与砧杵相应和？候馆迎秋，离宫吊月，另有无数伤心。豳诗随意写成。可笑篱落间呼灯捉蟋蟀，那是世间的儿女。把它写入琴弦，一声声更苦。', 'public-domain'),
  ('songci300', 185, '琵琶仙·双桨来时', 'songci-sc-189', '双桨来时有人似旧曲桃根桃叶歌扇轻约飞花蛾眉正奇绝春渐远汀洲自绿更添了几声啼鴂十里扬州三生杜牧前事休说又还是宫烛分烟奈愁里匆匆换时节都把一襟芳思与空阶榆荚千万缕藏鸦细柳为玉尊起舞回雪想见西出阳关故人初别', '双桨划来，船上有人像旧曲里的桃根桃叶。歌扇轻轻约住飞花，蛾眉正奇绝。春天渐渐远了，汀洲自绿，又添了几声杜鹃啼。十里扬州，三生杜牧，前事不必再说！
又还是宫中传烛分烟的时候，怎奈在愁里匆匆换了时节。把一襟芳思，都交给了空阶上的榆荚。千万缕可以藏鸦的细柳，为玉杯起舞，像回风旋雪。想见西出阳关时，故人初别的情景。', 'public-domain'),
  ('songci300', 186, '八归·芳莲坠粉', 'songci-sc-190', '芳莲坠粉疏桐吹绿庭院暗雨乍歇无端抱影销魂处还见筱墙萤暗藓阶蛩切送客重寻西去路问水面琵琶谁拨最可惜一片江山总付与啼鴂长恨相从未款而今何事又对西风离别渚寒烟淡棹移人远缥缈行舟如叶想文君望久倚竹愁生步罗袜归来后翠尊双饮下了珠帘玲珑闲看月', '芳莲坠落粉瓣，疏桐吹着绿叶，庭院里暗雨刚停。无端抱着影子消魂的地方，又看见竹墙上萤火暗淡，苔阶上蟋蟀声凄切。送客重寻西去的路，问水面上是谁在拨琵琶？最可惜一片江山，都交给了杜鹃啼。
长恨相跟随从不能尽意，如今又为什么，对着西风离别？洲渚寒、烟雾淡，船移人远，缥缈的行舟像一片叶。想她久望，倚着竹子发愁，罗袜生尘。归来后，双饮翠杯，放下珠帘，悠闲地看玲珑的月。', 'public-domain'),
  ('songci300', 187, '念奴娇·闹红一舸', 'songci-sc-191', '闹红一舸记来时尝与鸳鸯为侣三十六陂人未到水佩风裳无数翠叶吹凉玉容消酒更洒菰蒲雨嫣然摇动冷香飞上诗句日暮青盖亭亭情人不见争忍凌波去只恐舞衣寒易落愁入西风南浦高柳垂阴老鱼吹浪留我花间住田田多少几回沙际归路', '在喧闹的荷花中乘一舸，记得来时曾与鸳鸯为伴。三十六处池塘人迹未到，无数荷叶如水的佩、风的裳。翠叶吹出凉意，娇容消去酒意，又洒下一阵菰蒲的雨。它嫣然摇动，冷香飞上我的诗句。
日暮，青色的荷叶亭亭而立，情人不见，怎忍心凌波而去？只恐舞衣遇寒容易零落，愁绪随着西风飘向南浦。高柳垂下绿荫，老鱼吹起波浪，留我在花间住下。田田的荷叶有多少，几次在沙岸边找归路。', 'public-domain'),
  ('songci300', 188, '扬州慢·淮左名都', 'poems-gz11-19', '淮左名都竹西佳处解鞍少驻初程过春风十里尽荠麦青青自胡马窥江去后废池乔木犹厌言兵渐黄昏清角吹寒都在空城杜郎俊赏算而今重到须惊纵豆蔻词工青楼梦好难赋深情二十四桥仍在波心荡冷月无声念桥边红药年年知为谁生', '扬州是淮河东边著名的都会，在竹西亭这美好的去处，我解下马鞍稍作停留。走过当年春风十里的繁华街道，如今却长满了青青的荠菜和野麦。自从金兵进犯长江流域撤走以后，废弃的池塘、高大的树木，至今还厌恶谈论战争。渐渐到了黄昏，清冷的号角声在寒冷中吹响，回荡在这座空城里。杜牧曾经那样善于游赏，料想他如今重游此地也一定会感到吃惊。纵然他写「豆蔻」的词句精工，写「青楼」的美梦美好，也难以表达此刻深沉的感情。二十四桥依然还在，水波荡漾，冷月无声。遥想桥边的红芍药，年复一年，不知道是为谁开放？', 'academic'),
  ('songci300', 189, '长亭怨慢·渐吹尽', 'songci-sc-193', '渐吹尽枝头香絮是处人家绿深门户远浦萦回暮帆零乱向何许阅人多矣谁得似长亭树树若有情时不会得青青如此日暮望高城不见只见乱山无数韦郎去也怎忘得玉环分付第一是早早归来怕红萼无人为主算空有并刀难剪离愁千缕', '枝头的香絮渐渐吹尽，到处人家，绿荫深掩门户。远处江浦萦回，暮色中船帆零乱，要驶向哪里？长亭的树见过的人多了，谁能比得上它？树若是有情，就不会这样青青！
日暮，望不见高城，只见乱山无数。韦郎一去，怎么忘得了她的嘱托：第一是早早归来，怕红花无人做主。算来空有利剪，也难剪断千缕离愁。', 'public-domain'),
  ('songci300', 190, '淡黄柳·空城晓角', 'songci-sc-194', '空城晓角吹入垂杨陌马上单衣寒恻恻看尽鹅黄嫩绿都是江南旧相识正岑寂明朝又寒食强携酒小桥宅怕梨花落尽成秋色燕燕飞来问春何在唯有池塘自碧', '空城清晨的号角声，吹进垂杨覆盖的街路。马上单衣，寒意恻恻。看尽鹅黄嫩绿，都是江南旧相识。
正是岑寂，明天又是寒食。勉强带着酒，到她小桥边的住处。怕梨花落尽，就成了秋色。燕子飞来，问春天在哪里——只有池塘自碧。', 'public-domain'),
  ('songci300', 191, '暗香·旧时月色', 'songci-sc-195', '旧时月色算几番照我梅边吹笛唤起玉人不管清寒与攀摘何逊而今渐老都忘却春风词笔但怪得竹外疏花香冷入瑶席江国正寂寂叹寄与路遥夜雪初积翠尊易泣红萼无言耿相忆长记曾携手处千树压西湖寒碧又片片吹尽也几时见得', '旧时的月色，算来几次照着我，在梅边吹笛？唤起玉人，不管清寒也要攀折。何逊如今渐渐老了，都忘了春风的词笔。只怪竹外那几枝疏花，冷香飘入瑶席。
江南水乡，正是寂寂。可叹路远难寄，夜雪初积。翠杯容易惹泪，红萼无言，耿耿相忆。常记得曾携手的地方，千树梅花压着西湖的寒碧。又一片片吹尽了，什么时候才能再见？', 'public-domain'),
  ('songci300', 192, '疏影·苔枝缀玉', 'songci-sc-196', '苔枝缀玉有翠禽小小枝上同宿客里相逢篱角黄昏无言自倚修竹昭君不惯胡沙远但暗忆江南江北想佩环月夜归来化作此花幽独犹记深宫旧事那人正睡里飞近蛾绿莫似春风不管盈盈早与安排金屋还教一片随波去又却怨玉龙哀曲等恁时重觅幽香已入小窗横幅', '苔痕斑驳的枝上缀着玉一般的花，有小翠鸟在枝上同宿。客途中相逢，篱角黄昏，它无言地倚着修竹。昭君不惯胡地的风沙遥远，只暗暗思念江南江北。想她佩环叮咚、月夜归来，化作这枝幽独的花。
还记得深宫旧事，那人正在睡梦中，梅花飞近她的蛾眉。不要像春风那样，不管它盈盈可爱，早该为它安排金屋。还教一片随波流去，却又怨玉笛的哀曲。等到那时再觅幽香，它已进了小窗上的横幅画里。', 'public-domain'),
  ('songci300', 193, '翠楼吟·月冷龙沙', 'songci-sc-197', '月冷龙沙尘清虎落今年汉酺初赐新翻胡部曲听毡幕元戎歌吹层楼高峙看槛曲萦红檐牙飞翠人姝丽粉香吹下夜寒风细此地宜有词仙拥素云黄鹤与君游戏玉梯凝望久叹芳草萋萋千里天涯情味仗酒祓清愁花销英气西山外晚来还卷一帘秋霁', '月色冷照着龙沙，尘埃扫清在虎落，今年朝廷初次赐酺。新翻的胡部乐曲，从毡幕里传出元戎的歌吹。层楼高高耸立。看栏杆回曲萦着红色，檐牙飞着翠色。人儿美丽，粉香从楼上吹下，夜寒风细。
这地方，该有词仙，拥着素云黄鹤，与你同游。在玉梯上凝望久了，可叹芳草萋萋千里。天涯的滋味。只能靠酒来除清愁，靠花来销磨英气。西山之外，傍晚时又卷起一帘秋晴。', 'public-domain'),
  ('songci300', 194, '小重山·柳暗花明春事深', 'songci-sc-198', '柳暗花明春事深小阑红芍药已抽簪雨余风软碎鸣禽迟迟日犹带一分阴往事莫沉吟身闲时序好且登临旧游无处不堪寻无寻处惟有少年心', '柳暗花明，春事已深；小栏杆边的红芍药已经抽出簪一样的花苞。雨后风软，鸣禽声碎；日头迟迟，还带着一分阴。
往事不要沉吟；身闲时序又好，且去登临。旧游之处没有一处不能寻访，寻不到的，只有那颗少年心。', 'public-domain'),
  ('songci300', 195, '唐多令·芦叶满汀洲', 'songci-sc-199', '芦叶满汀洲寒沙带浅流二十年重过南楼柳下系船犹未稳能几日又中秋黄鹤断矶头故人曾到否旧江山浑是新愁欲买桂花同载酒终不似少年游', '芦叶长满汀洲，寒沙带着浅流。二十年后重过南楼。柳下系船还没系稳，能过几天，又到中秋。
黄鹤矶头，故人来过没有？旧日江山全是新愁。想买桂花、载着酒同游，终究不像少年时那样了。', 'public-domain'),
  ('songci300', 196, '木兰花·春风只在园西畔', 'songci-sc-200', '春风只在园西畔荠菜花繁蝴蝶乱冰池晴绿照还空香径落红吹已断意长翻恨游丝短尽日相思罗带缓宝奁明月不欺人明日归来君试看', '春风只在园子西边，荠菜花开得繁盛，蝴蝶纷乱。冰池晴日的绿光映照还是空的，香径上的落花已被吹尽。
情意深长反倒恨游丝太短，整日相思，罗带都松了。梳妆镜的明月不骗人，明天你归来时试着看看。', 'public-domain'),
  ('songci300', 197, '风入松·一春长费买花钱', 'songci-sc-201', '一春长费买花钱日日醉湖边玉骢惯识西湖路骄嘶过沽酒楼前红杏香中箫鼓绿杨影里秋千暖风十里丽人天花压鬓云偏画船载取春归去余情付湖水湖烟明日重扶残醉来寻陌上花钿', '一春常花买花的钱，天天醉在西湖边。玉骢马惯识西湖的路，骄嘶着走过卖酒楼前。红杏香中有箫鼓，绿杨影里有秋千。
暖风十里，是丽人的天气；花压得鬓发偏斜。画船载着春天归去，余情交给湖水湖烟。明天再扶着残醉，来寻路上的花钿。', 'public-domain'),
  ('songci300', 198, '满庭芳·月洗高梧', 'songci-sc-202', '月洗高梧露漙幽草宝钗楼外秋深土花沿翠萤火坠墙阴静听寒声断续微韵转凄咽悲沉争求侣殷勤劝织促破晓机心儿时曾记得呼灯灌穴敛步随音任满身花影犹自追寻携向华堂戏斗亭台小笼巧妆金今休说从渠床下凉夜伴孤吟', '月光冲洗着高梧，露水沾满幽草，宝钗楼外秋意已深。苔藓沿着翠色生长，萤火坠在墙阴。静听那寒声断续，微韵转成凄咽悲沉。它急于求偶，殷勤地像劝人纺织，催破了拂晓时的机杼心。
儿时曾记得，呼着灯、灌水入穴，收着脚步跟着声音。任凭满身都是花影，还要追寻。把它带到华堂里戏斗，亭台小，笼子精巧、妆饰如金。如今不必说了，任凭它在床下，凉夜里伴我独吟。', 'public-domain'),
  ('songci300', 199, '绮罗香·做冷欺花', 'songci-sc-203', '做冷欺花将烟困柳千里偷催春暮尽日冥迷愁里欲飞还住惊粉重蝶宿西园喜泥润燕归南浦最妨它佳约风流钿车不到杜陵路沉沉江上望极还被春潮晚急难寻官渡隐约遥峰和泪谢娘眉妩临断岸新绿生时是落红带愁流处记当日门掩梨花剪灯深夜语', '它化作寒意欺负花朵，化作烟雾困住柳树，在千里间偷偷催促春暮。整日迷蒙，像在愁里要飞又停下。惊觉花粉变重，蝴蝶宿在西园；喜见泥土湿润，燕子回到南浦。最妨碍的是风流佳约，钿车到不了杜陵路。
沉沉江上极目远望，又被春潮晚来汹涌，难以找到官渡。隐约的远峰，像和着泪水的美人眉。临着断岸，新绿生出的时候，正是落红带着愁流去的地方。记得当日门掩梨花，剪灯深夜说话。', 'public-domain'),
  ('songci300', 200, '双双燕·过春社了', 'songci-sc-204', '过春社了度帘幕中间去年尘冷差池欲住试入旧巢相并还相雕梁藻井又软语商量不定飘然快拂花梢翠尾分开红影芳径芹泥雨润爱贴地争飞竞夸轻俊红楼归晚看足柳昏花暝应自栖香正稳便忘了天涯芳信愁损翠黛双蛾日日画栏独凭', '春社过了，它们穿过帘幕之间，去年的巢已积了冷尘。翅膀参差想停下，试着进入旧巢相并。又端详雕梁藻井，软语商量不定。忽然飘然拂过花梢，翠尾分开红影。
芳香的小径，芹泥被雨润湿。它们爱贴地争飞，竞相夸耀轻捷俊俏。回红楼时已晚，看够了柳暗花昏。该是在香巢里睡稳了，便忘了天涯的书信。愁坏了那双翠眉，天天独自倚着画栏。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 201, '东风第一枝·巧沁兰心', 'songci-sc-205', '巧沁兰心偷黏草甲东风欲障新暖谩凝碧瓦难留信知暮寒较浅行天入镜做弄出轻松纤软料故园不卷重帘误了乍来双燕青未了柳回白眼红欲断杏开素面旧游忆著山阴厚盟遂妨上苑寒炉重暖便放慢春衫针线恐凤靴挑菜归来万一灞桥相见', '它巧妙地沁入兰心，偷偷黏上草芽，像要把东风的新暖挡住。白白凝在碧瓦上难以久留，的确知道暮寒还浅。在空中行、入镜般的水面，做出轻松纤软的样子。料想故园不卷重帘，误了刚来的双燕。
青色还没完，柳树就翻起白眼；红色将断，杏花开出素面。想起山阴的旧游，深约因此耽误了上苑之行。寒炉重新烧暖，便放慢了做春衫的针线。恐怕她穿着凤靴挑菜归来，万一在灞桥相见。', 'public-domain'),
  ('songci300', 202, '喜迁莺·月波疑滴', 'songci-sc-206', '月波疑滴望玉壶天近了无尘隔翠眼圈花冰丝织练黄道宝光相直自怜诗酒瘦难应接许多春色最无赖是随香趁烛曾伴狂客踪迹漫记忆老了杜郎忍听东风笛柳院灯疏梅厅雪在谁与细倾春碧旧情拘未定犹自学当年游历怕万一误玉人夜寒帘隙', '月波像要滴下，望那玉壶般的天空近在眼前，一点尘埃也没有。翠色的灯圈、冰丝织成的绢，与黄道宝光相照。自怜诗酒消磨得人瘦，难以应接这许多春色。最无赖的是随着香、趁着烛，曾经陪伴狂客。
踪迹，空自记忆，杜郎已老，怎忍听东风的笛声。柳院灯光疏落，梅厅还有积雪，谁来为我细斟春酒？旧情拘束未定，还在学当年的游历。怕万一误了玉人，在夜寒的帘缝间等待。', 'public-domain'),
  ('songci300', 203, '三姝媚·烟光摇缥瓦', 'songci-sc-207', '烟光摇缥瓦望晴檐多风柳花如洒锦瑟横床想泪痕尘影凤弦常下倦出犀帷频梦见王孙骄马讳道相思偷理绡裙自惊腰衩惆怅南楼遥夜记翠箔张灯枕肩歌罢又入铜驼遍旧家门巷首询声价可惜东风将恨与闲花俱谢记取崔徽模样归来暗写', '烟光在青瓦上摇动，望晴日屋檐多风，柳花像洒下来。锦瑟横在床上，想那泪痕尘影，弦柱常常卸下。她懒得出犀帐，频频梦见王孙的骄马。讳言相思，偷偷整理绡裙，自己惊觉腰身瘦了。
惆怅南楼的遥夜。记得翠帘张灯，枕肩歌罢。又来到铜驼街，走遍旧日的门巷，先打听她的声价。可惜东风，把恨与闲花一起吹谢。记住崔徽的模样，回来后暗暗描画。', 'public-domain'),
  ('songci300', 204, '秋霁·江水苍苍', 'songci-sc-208', '江水苍苍望倦柳愁荷共感秋色废阁先凉古帘空暮雁程最嫌风力故园信息爱渠入眼南山碧念上国谁是脍鲈江汉未归客还又岁晚瘦骨临风夜闻秋声吹动岑寂露蛩悲清灯冷屋翻书愁上鬓毛白年少俊游浑断得但可怜处无奈冉冉魂惊采香南浦剪梅烟驿', '江水苍茫，望那倦柳愁荷，一同感到秋色。废阁先凉，旧帘空垂到暮色，雁飞的路最怕风力。故园的消息，爱它入眼的南山碧色。想京城里，谁是那想脍鲈鱼却未能归江汉的客？
又到岁晚，瘦骨临风，夜里听秋声，吹动一片岑寂。露中蟋蟀悲鸣，清灯冷屋，翻书时愁得鬓毛都白了。年少的俊游全然断绝。只有可怜之处，无奈心魂冉冉惊动，在南浦采香，在烟驿剪梅。', 'public-domain'),
  ('songci300', 205, '夜合花·柳锁莺魂', 'songci-sc-209', '柳锁莺魂花翻蝶梦自知愁染潘郎轻衫未揽犹将泪点偷藏念前事怯流光早春窥酥雨池塘向消凝里梅开半面情满徐妆风丝一寸柔肠曾在歌边惹恨烛底萦香芳机瑞锦如何未织鸳鸯人扶醉月依墙是当初谁敢疏狂把闲言语花房夜久各自思量', '柳锁住黄莺的魂，花翻起蝴蝶的梦，自己知道愁已染上潘岳那样的白发。轻衫还没穿好，还把泪点偷偷藏起。想从前的事，怕流光，早春窥看酥雨后的池塘。在消凝之中，梅花开了半面，情意满是徐妃的半妆。
风丝一寸柔肠，曾经在歌边惹恨，在烛底萦香。芳机的瑞锦，怎么还没织出鸳鸯？有人扶醉，月亮靠着墙；当初谁敢这样疏狂！把那些闲言碎语，留在花房夜深时，各自思量。', 'public-domain'),
  ('songci300', 206, '玉蝴蝶·晚雨未摧宫树', 'songci-sc-210', '晚雨未摧宫树可怜闲叶犹抱凉蝉短景归秋吟思又接愁边漏初长梦魂难禁人渐老风月俱寒想幽欢土花庭甃虫网阑干无端啼蛄搅夜恨随团扇苦近秋莲一笛当楼谢娘悬泪立风前故园晚强留诗酒新雁远不致寒暄隔苍烟楚香罗袖谁伴婵娟', '晚雨没有打坏宫树，可怜那片闲叶，还抱着凉蝉。日短入秋，吟思又接到愁边。漏声初长，梦魂难禁；人渐老，风月都冷。想那幽欢之处，台阶生苔，栏杆结网。
无端，蝼蛄啼叫搅乱长夜；恨随着团扇，苦挨着秋莲。一声笛响当楼，谢娘含泪立在风前。故园天晚，勉强留着诗酒；新雁飞远，不带寒暄。隔着苍烟，楚香罗袖，谁来陪伴这婵娟。', 'public-domain'),
  ('songci300', 207, '贺新郎·湛湛长空黑', 'songci-sc-211', '湛湛长空黑更那堪斜风细雨乱愁如织老眼平生空四海赖有高楼百尺看浩荡千崖秋色白发书生神州泪尽凄凉不向牛山滴追往事去无迹少年自负凌云笔到而今春华落尽满怀萧瑟常恨世人新意少爱说南朝狂客把破帽年年拈出若对黄花孤负酒怕黄花也笑人岑寂鸿北去日西匿', '长空一片深黑。更哪堪斜风细雨，乱愁像织。我这双老眼平生空看四海，赖有百尺高楼。看那浩荡的千崖秋色。白发书生为神州落泪，尽管凄凉，也不像齐景公那样在牛山滴泪。追想往事，去无踪迹。
少年时自负凌云之笔。到如今春花落尽，满怀萧瑟。常恨世人新意太少，爱说南朝的狂客，把破帽年年拈出来说。若对着菊花辜负了酒，怕菊花也要笑人寂寞。鸿雁北去，太阳西落。', 'public-domain'),
  ('songci300', 208, '湘春夜月·近清明', 'songci-sc-232', '近清明翠禽枝上消魂可惜一片清歌都付与黄昏欲共柳花低诉怕柳花轻薄不解伤春念楚乡旅宿柔情别绪谁与温存空樽夜泣青山不语残月当门翠玉楼前惟是有一波湘水摇荡湘云天长梦短问甚时重见桃根这次第算人间没个并刀剪断心上愁痕', '将近清明，翠鸟在枝上叫得令人消魂。可惜一片清越的歌声，都交给了黄昏。想对着柳花低声诉说，又怕柳花轻薄，不懂伤春。想我在楚乡旅宿，柔情别绪，谁来温存？
空杯在夜里像在哭泣，青山不语，残月当门。翠玉楼前，只有一波湘水，摇荡着湘云。天长梦短，问什么时候能重见桃根？这般情景，算来人间没有一把并州剪刀，能剪断心上的愁痕。', 'public-domain'),
  ('songci300', 209, '大有·戏马台前', 'songci-sc-233', '戏马台前采花篱下问岁华还是重九恰归来南山翠色依旧帘栊昨夜听风雨都不似登临时候一片宋玉情怀十分卫郎清瘦红萸佩空对酒砧杵动微寒暗欺罗袖秋已无多早是败荷衰柳强整帽檐敧侧曾经向天涯搔首几回忆故国莼鲈霜前雁后', '在戏马台前，采花于篱下，问岁华，又到重九。恰好归来，南山翠色依旧。帘栊外昨夜听风雨，都不像登临时的天气。一片宋玉般的悲秋情怀，十分卫玠般的清瘦。
红萸佩在身上，只能空对酒。砧杵声催来微寒，暗暗欺着罗袖。秋色已不多，早是败荷衰柳。勉强整理歪斜的帽檐，曾经在天涯搔首。几次回想故国的莼羹鲈鱼，在霜前雁后。', 'public-domain'),
  ('songci300', 210, '青玉案·年年跃马长安市', 'songci-sc-341', '年年跃马长安市客舍似家家似寄青钱换酒日无何红烛呼卢宵不寐易挑锦妇机中字难得玉人心下事男儿西北有神州莫滴水西桥畔泪', '年年骑马奔走在京城，客舍当作家里，家里反成了寄居之处。用青铜钱换酒，天天无事可做；红烛下呼卢赌博，通夜不睡。
叫妻子在机上织锦寄字是容易的，要猜透歌女心里的念头却难。男儿志在西北的神州大地，别在水西桥边为儿女之情落泪。', 'public-domain'),
  ('songci300', 211, '霜叶飞·断烟离绪', 'songci-sc-215', '断烟离绪关心事斜阳红隐霜树半壶秋水荐黄花香噀西风雨纵玉勒轻飞迅羽凄凉谁吊荒台古记醉踏南屏彩扇咽寒蝉倦梦不知蛮素聊对旧节传杯尘笺蠹管断阕经岁慵赋小蟾斜影转东篱夜冷残蛩语早白发缘愁万缕惊飙从卷乌纱去漫细将茱萸看但约明年翠微高处', '断烟中一片离绪，最关心的事，是斜阳的红光隐在霜树里。半壶秋水供着黄花，香气喷向秋风秋雨。纵然策马轻飞如迅羽，凄凉中谁来凭吊荒台古迹？记得醉踏南屏，彩扇声中寒蝉凄咽，倦梦不知小蛮、樊素。
姑且对着旧节传杯，尘封的信笺、生蠹的笔管，断了的词稿经年懒得再赋。小月斜影转过东篱，夜冷中残蟋蟀在叫。早已白了头，都因万缕愁。狂风且卷走乌纱帽。慢慢细看茱萸，只约定明年，在青山高处。', 'public-domain'),
  ('songci300', 212, '宴清都·绣幄鸳鸯柱', 'songci-sc-216', '绣幄鸳鸯柱红情密腻云低护秦树芳根兼倚花梢钿合锦屏人妒东风睡足交枝正梦枕瑶钗燕股障滟蜡满照欢丛嫠蟾冷落羞度人间万感幽单华清惯浴春盎风露连鬟并暖同心共结向承恩处凭谁为歌长恨暗殿锁秋灯夜语叙旧期不负春盟红朝翠暮', '绣帐上鸳鸯交柱，红情密处，浓云低低护着海棠。香根相依，花梢如钿盒相合，锦屏里的人见了也嫉妒。东风里睡足，枝条相交，正像枕上梦着瑶钗燕股。挡住滟滟的蜡烛，照着满丛的欢意，孤月冷落羞于照过。
人间万种感慨都落在孤独上；华清池惯于沐浴，春意盎然的春风露水。双鬟并暖，同心共结，在那承恩的地方。靠谁来唱《长恨歌》？暗殿锁着，秋灯下夜语。叙述旧日的期约，不辜负春天的盟誓，红朝翠暮。', 'public-domain'),
  ('songci300', 213, '齐天乐·烟波桃叶西陵路', 'songci-sc-217', '烟波桃叶西陵路十年断魂潮尾古柳重攀轻鸥聚别陈迹危亭独倚凉飔乍起渺烟碛飞帆暮山横翠但有江花共临秋镜照憔悴华堂烛暗送客眼波回盼处芳艳流水素骨凝冰柔葱蘸雪犹忆分瓜深意清尊未洗梦不湿行云漫沾残泪可惜秋宵乱蛩疏雨里', '烟波中桃叶渡、西陵路，十年来魂断在潮尾。古柳再次攀折，轻鸥聚散，旧迹里独倚危亭。凉风忽起，烟碛上远帆缥缈，暮山横着翠色。只有江花，一同临着秋镜照我的憔悴。
华堂烛暗送客，她眼波回盼的地方，芳艳如流水。素骨凝冰，柔指蘸雪，还记得分瓜时的深意。清酒杯还没洗，梦不能湿行云，只白沾残泪。可惜这秋宵，在乱蟋蟀和疏雨里。', 'public-domain'),
  ('songci300', 214, '花犯·小娉婷', 'songci-sc-218', '小娉婷清铅素靥蜂黄暗偷晕翠翘敧鬓昨夜冷中庭月下相认睡浓更苦凄风紧惊回心未稳送晓色一壶葱茜才知花梦准湘娥化作此幽芳凌波路古岸云沙遗恨临砌影寒香乱冻梅藏韵熏炉畔旋移傍枕还又见玉人垂绀鬓料唤赏清华池馆台杯须满引', '小小的娉婷身影，清淡铅素的脸颊，暗暗透出一晕蜂黄。翠翘斜插鬓边。昨夜清冷的庭中，在月下相认。睡得正浓更苦于凄风紧吹，惊回后心神未稳。送来晓色，一壶葱茜，才知道花梦是真的。
是湘娥化作这幽芳，行凌波之路，古岸云沙留下遗恨。临着台阶的影子，寒香纷乱，像冻梅藏着韵味。在熏炉边，随即移到枕旁，又看见玉人垂下青黑的鬓发。料想会唤人同赏，在这清华的池馆里，台上的杯子须满满地饮。', 'public-domain'),
  ('songci300', 215, '浣溪沙·门隔花深梦旧游', 'songci-sc-219', '门隔花深梦旧游夕阳无语燕归愁玉纤香动小帘钩落絮无声春堕泪行云有影月含羞东风临夜冷于秋', '门隔着深花，梦里回到旧游之处；夕阳无语，燕子归去带着愁。她的纤手带着香气，拨动小帘钩。
落絮无声，是春天在落泪；行云有影，是月儿含羞。东风入夜，比秋天还冷。', 'public-domain'),
  ('songci300', 216, '点绛唇·卷尽愁云', 'songci-sc-220', '卷尽愁云素娥临夜新梳洗暗尘不起酥润凌波地辇路重来仿佛灯前事情如水小楼熏被春梦笙歌里', '愁云卷尽，嫦娥在夜里刚梳洗过。暗尘不起，地面酥润，是她凌波走过的地方。
重来御街，仿佛还是灯前旧事。情意如水；小楼里熏着被子，春梦在笙歌里。', 'public-domain'),
  ('songci300', 217, '祝英台近·剪红情', 'songci-sc-221', '剪红情裁绿意花信上钗股残日东风不放岁华去有人添烛西窗不眠侵晓笑声转新年莺语旧尊俎玉纤曾擘黄柑柔香系幽素归梦湖边还迷镜中路可怜千点吴霜寒销不尽又相对落梅如雨', '剪出红情，裁出绿意，花信插上钗股。残日东风，不肯放岁华归去。有人在西窗添烛，不睡到天明，笑声转为新年的莺语。
旧日的酒席。她的纤手曾剖开黄柑，柔香系着幽素。归梦到湖边，还迷在镜般的路上。可怜千点吴地的霜，寒气销不尽，又相对看着落梅如雨。', 'public-domain'),
  ('songci300', 218, '风入松·听风听雨过清明', 'songci-sc-222', '听风听雨过清明愁草瘗花铭楼前绿暗分携路一丝柳一寸柔情料峭春寒中酒交加晓梦啼莺西园日日扫林亭依旧赏新晴黄蜂频扑秋千索有当时纤手香凝惆怅双鸳不到幽阶一夜苔生', '听着风、听着雨过了清明，愁闷中写下葬花的铭文。楼前绿荫暗暗，是分手时的路；一丝柳条，就是一寸柔情。料峭春寒里喝醉了酒，交加的晓梦被黄莺啼醒。
西园天天打扫林亭，依旧去赏新晴。黄蜂频频扑着秋千索，那里有她当时纤手留下的香。惆怅那双鸳鸯鞋不再来，幽静的台阶一夜就生了青苔。', 'public-domain'),
  ('songci300', 219, '莺啼序·残寒正欺病酒', 'songci-sc-223', '残寒正欺病酒掩沉香绣户燕来晚飞入西城似说春事迟暮画船载清明过却晴烟冉冉吴宫树念羁情游荡随风化为轻絮十载西湖傍柳系马趁娇尘软雾溯红渐招入仙溪锦儿偷寄幽素倚银屏春宽梦窄断红湿歌纨金缕暝堤空轻把斜阳总还鸥鹭幽兰旋老杜若还生水乡尚寄旅别后访六桥无信事往花委瘗玉埋香几番风雨长波妒盼遥山羞黛渔灯分影春江宿记当时短楫桃根渡青楼仿佛临分败壁题诗泪墨惨淡尘土危亭望极草色天涯叹鬓侵半苎暗点检离痕欢唾尚染鲛绡亸凤迷归破鸾慵舞殷勤待写书中长恨蓝霞辽海沉过雁漫相思弹入哀筝柱伤心千里江南怨曲重招断魂在否', '残寒正欺负病酒的人，我掩上沉香木的绣户。燕子来得晚，飞入西城，像在说春事已近迟暮。画船载着，清明已经过去了；晴烟冉冉，笼着吴宫的树。想那羁旅之情，随风游荡，化作轻絮。
十年前在西湖，傍着柳树系马，趁着娇尘软雾。沿着花丛渐渐被招入仙溪，锦儿偷偷送来幽情。靠着银屏，春夜宽而梦短；断红打湿了歌扇金缕衣。暮色中堤上空空，轻轻把斜阳都还给了鸥鹭。
幽兰转眼就老，杜若又生，我还在水乡寄旅。别后访遍六桥也没有消息，往事已去，花也凋萎；葬玉埋香，经过几番风雨。长波嫉妒她的眼波，远山羞于比她的眉黛。渔灯分影，曾在春江夜宿，记得当时短桨划向桃根渡。青楼仿佛还在，临别时在败壁上题诗，泪墨惨淡，已落满尘土。
在高亭上极目远望，草色直到天涯，可叹鬓边已白了一半。暗暗点检旧物：离别的泪痕、欢笑的唾痕，还染在鲛绡上；凤钗斜垂，鸾镜残破懒得再舞。想殷勤写书，写尽长恨，可蓝天大海雁信沉没；只能白白相思，弹入哀筝的弦柱。伤心啊，千里江南；重唱怨曲招魂，那断了的魂还在吗？', 'public-domain'),
  ('songci300', 220, '惜黄花慢·送客吴皋', 'songci-sc-224', '送客吴皋正试霜夜冷枫落长桥望天不尽背城渐杳离亭黯黯恨水迢迢翠香零落红衣老暮愁锁残柳眉梢念瘦腰沈郎旧日曾系兰桡仙人凤咽琼箫怅断魂送远九辩难招醉鬟留盼小窗剪烛歌云载恨飞上银霄素秋不解随船去败红趁一叶寒涛梦翠翘怨鸿料过南谯', '在吴地水边送客，正逢霜降夜冷，枫叶落在长桥。望天望不尽，背城渐渐渺茫；离亭黯然，恨水迢迢。翠香零落，荷花老去，暮愁锁在残柳的眉梢。想那瘦腰的沈约，旧日曾在这里系过兰舟。
仙人吹着凤鸣般的琼箫，惆怅断魂送远，《九辩》也难招回。醉中的她留着盼顾，小窗剪烛，歌声载着恨飞上银霄。素秋不懂得随船离去，败红趁着一叶寒涛。梦见翠翘，怨鸿料想已飞过南谯。', 'public-domain'),
  ('songci300', 221, '高阳台·宫粉雕痕', 'songci-sc-225', '宫粉雕痕仙云堕影无人野水荒湾古石埋香金沙锁骨连环南楼不恨吹横笛恨晓风千里关山半飘零庭上黄昏月冷阑干寿阳空理愁鸾问谁调玉髓暗补香瘢细雨归鸿孤山无限春寒离魂难倩招清些梦缟衣解佩溪边最愁人啼鸟晴明叶底青圆', '宫粉留下雕痕，仙云堕下影子，无人的野水荒湾。古石埋着香，金沙如锁骨连环。南楼不恨横笛吹起，只恨晓风吹过千里关山。一半飘零，庭上黄昏，月冷栏杆。
寿阳公主白白对着鸾镜发愁，问谁来调玉髓，暗补那香瘢？细雨中归鸿飞过，孤山无限春寒。离魂难以招回，梦见缟衣人解佩在溪边。最愁人的是，晴明时啼鸟鸣叫，叶底已结出青青圆果。', 'public-domain'),
  ('songci300', 222, '三姝媚·湖山经醉惯', 'songci-sc-226', '湖山经醉惯渍春衫啼痕酒痕无限又客长安叹断襟零袂涴尘谁浣紫曲门荒沿败井风摇青蔓对语东邻犹是曾巢谢堂双燕春梦人间须断但怪得当年梦缘能短绣屋秦筝傍海棠偏爱夜深开宴舞歇歌沉花未减红颜先变伫久河桥欲去斜阳泪满', '湖山间我醉惯了。春衫上渍着啼痕酒痕，无边无际。又客居京城，可叹衣襟破断、衣袖零落，沾了尘谁替我洗？紫曲的门已荒，沿着败井，风摇着青蔓。东邻的燕子相互对语，还是当年在谢家堂上筑过巢的那一双。
人间的春梦终究要断。只怪当年梦缘太短。绣屋里的秦筝，偏偏爱在海棠边，夜深设宴。舞歇歌沉，花还没减，红颜先变了。在河桥上久立将要离去，斜阳里泪满衣襟。', 'public-domain'),
  ('songci300', 223, '八声甘州·渺空烟四远', 'songci-sc-227', '渺空烟四远是何年青天坠长星幻苍崖云树名娃金屋残霸宫城箭径酸风射眼腻水染花腥时靸双鸳响廊叶秋声', '空旷的烟霭伸向四方，是哪一年，青天坠下这颗长星？化作苍崖云树、名娃金屋，残霸的宫城。箭径上冷风刺眼，腻水把花都染上腥气。还不时传来双鸳鞋的声响，是廊上落叶的秋声。', 'public-domain'),
  ('songci300', 224, '踏莎行·润玉笼绡', 'songci-sc-228', '润玉笼绡檀樱倚扇绣圈犹带脂香浅榴心空叠舞裙红艾枝应压愁鬟乱午梦千山窗阴一箭香瘢新褪红丝腕隔江人在雨声中晚风菰叶生秋怨', '润玉般的手腕笼着绡纱，檀红的樱桃小口靠着扇子。绣圈上还带着浅淡的脂香。石榴花心白白叠成舞裙的红，艾枝该压住了愁乱的鬓发。
午梦里越过千山，窗下光阴只在一箭之间。红丝线般的手腕上香瘢刚褪。隔着江的人在雨声里，晚风吹着菰叶，生出秋怨。', 'public-domain'),
  ('songci300', 225, '瑞鹤仙·晴丝牵绪乱', 'songci-sc-229', '晴丝牵绪乱对沧江斜日花飞人远垂杨暗吴苑正旗亭烟冷河桥风暖兰情蕙盼惹相思春根酒畔又争知吟骨萦销渐把旧衫重剪凄断流红千浪缺月孤楼总难留燕歌尘凝扇待凭信拌分钿试挑灯欲写还依不忍笺幅偷和泪卷寄残云剩雨蓬莱也应梦见', '晴丝牵得心绪纷乱。对着沧江斜日，花飞人远。垂杨暗暗遮住吴苑，正是旗亭烟冷、河桥风暖。兰样的情、蕙样的眼，惹起相思，在春根酒边。她又怎知，我因吟咏消瘦，渐渐要把旧衫重新裁剪。
凄断。流红千重浪，缺月照着孤楼，总难留住燕子。歌尘凝在扇上。想凭书信，拼着分钿。试着挑亮灯要写，还是依恋不忍，偷偷把笺纸和泪卷起。寄到残云剩雨的蓬莱，她也该梦见。', 'public-domain'),
  ('songci300', 226, '夜游宫·人去西楼雁杳', 'songci-sc-231', '人去西楼雁杳叙别梦扬州一觉云澹星疏楚山晓听啼乌立河桥话未了雨外蛩声早细织就霜丝多少说与萧娘未知道向长安对秋灯几人老', '人已离开西楼，雁信渺茫；叙别之梦，像扬州一觉。云淡星疏，楚山泛晓。听乌鸦啼叫，立在河桥上，话还没说完。
雨外的蟋蟀叫得早，细细织成了多少霜丝般的白发？说给她听，她还不知道。向着长安，对着秋灯，有多少人就这样老了？', 'public-domain'),
  ('songci300', 227, '兰陵王·送春去', 'songci-sc-234', '送春去春去人间无路秋千外芳草连天谁遣风沙暗南浦依依甚意绪漫忆海门飞絮乱鸦过斗转城荒不见来时试灯处春去最谁苦但箭雁沉边梁燕无主杜鹃声里长门暮想玉树凋土泪盘如露咸阳送客屡回顾斜日未能度春去尚来否正江令恨别庾信愁赋苏堤尽日风和雨叹神游故国花记前度人生流落顾孺子共夜语', '送春天归去，春天走后人间没有归路。秋千外芳草连天，是谁让风沙遮暗了南浦？依依不舍是什么意绪？空自回忆海门飞絮。乱鸦飞过，北斗转动、城池荒废，看不见来时试灯的地方。
春天走了，谁最苦？只有边地沉落的箭雁、无主的梁燕，杜鹃声里长门已暮。想那玉树凋零入土，承露盘上的泪像露水。像咸阳送客一再回头，斜阳也迟迟不肯落下。
春天走了，还会回来吗？正是江总恨别、庾信写愁赋的时候，苏堤整日风和雨。可叹神游故国，花还记得前度。人生流落，只能看着孩子，一同夜话。', 'public-domain'),
  ('songci300', 228, '高阳台·照野旌旗', 'songci-sc-235', '照野旌旗朝天车马平沙万里天低宝带金章尊前茸帽风敧秦关汴水经行地想登临都付新诗纵英游叠鼓清笳骏马名姬酒酣应对燕山雪正冰河月冻晓陇云飞投老残年江南谁念方回东风渐绿西湖柳雁已还人未南归最关情折尽梅花难寄相思', '旌旗照遍原野，朝天的车马，平沙万里，天幕低垂。宝带金章，杯前茸帽被风吹斜。秦关汴水是你经过的地方，想登临之处都化作了新诗。纵情英游，叠鼓清笳，骏马名姬。
酒酣时面对燕山的雪，正是冰河月冻、晓陇云飞的时候。垂老的残年，江南有谁念我？东风渐渐染绿西湖的柳，大雁已经回来，人却未南归。最牵动心肠的是，梅花折尽了，相思也难寄。', 'public-domain'),
  ('songci300', 229, '瑶华·朱钿宝玦', 'songci-sc-236', '朱钿宝玦天上飞琼比人间春别江南江北曾未见漫拟梨云梅雪淮山春晚问谁识芳心高洁消几番花落花开老了玉关豪杰金壶剪送琼枝看一骑红尘香度瑶阙韶华正好应自喜初识长安蜂蝶杜郎老矣想旧事花须能说记少年一梦扬州二十四桥明月', '红钿宝玦，天上飞下的琼花，与人间的春色不同。江南江北，未曾见过，只能空比作梨云梅雪。淮山春暮，问谁能懂得它芳心的高洁？经过几番花开花落，玉关的豪杰也老了。
用金壶剪送琼枝，看一骑红尘，香气度入瑶阙。韶华正好，该自喜初次认识长安的蜂蝶。杜郎已老，想旧事，花应该还能说。记得少年时一梦扬州，二十四桥的明月。', 'public-domain'),
  ('songci300', 230, '玉京秋·烟水阔', 'songci-sc-237', '烟水阔高林弄残照晚蜩凄切碧砧度韵银床飘叶衣湿桐阴露冷采凉花时赋秋雪叹轻别一襟幽事砌蛩能说客思吟商还怯怨歌长琼壶暗缺翠扇恩疏红衣香褪翻成消歇玉骨西风恨最恨闲却新凉时节楚箫咽谁寄西楼淡月', '烟水空阔。高林摆弄着残照，晚蝉叫声凄切。碧绿的捣衣声传来韵味，井栏上飘下落叶。桐荫里露冷水湿衣裳，采着凉花，不时咏叹秋雪。可叹轻易离别，一襟幽事，只有台阶下的蟋蟀能说。
客愁吟起商调还觉胆怯。怨歌悠长，玉壶暗暗敲缺。翠扇的恩情疏了，红衣的香气褪了，反而成了消歇。玉骨迎着西风，最恨的是白白荒废了新凉的时节。楚箫呜咽，谁寄西楼那淡月。', 'public-domain'),
  ('songci300', 231, '曲游春·禁苑东风外', 'songci-sc-238', '禁苑东风外飏暖丝晴絮春思如织燕约莺期恼芳情偏在翠深红隙漠漠香尘隔沸十里乱弦丛笛看画船尽入西泠闲却半湖春色柳陌新烟凝碧映帘底宫眉堤上游勒轻暝笼寒怕梨云梦冷杏香愁幂歌管酬寒食奈蝶怨良宵岑寂正满湖碎月摇花怎生去得', '宫苑东风之外，暖风扬起游丝晴絮，春思像织。燕子黄莺的约会，恼人的芳情偏偏在翠绿深处、红花缝里。漠漠香尘隔断。十里内沸腾着乱弦丛笛。看画船都驶入西泠，把半湖春色空了出来。
柳陌上，新烟凝着碧色。映着帘下的宫样眉，堤上游人的马络头。轻暮笼着寒意，怕梨云梦冷、杏香愁浓。歌管酬答寒食。怎奈蝴蝶怨良宵岑寂。正当满湖碎月摇花，怎么舍得离去？', 'public-domain'),
  ('songci300', 232, '花犯·楚江湄', 'songci-sc-239', '楚江湄湘娥乍见无言洒清泪淡然春意空独倚东风芳思谁寄凌波路冷秋无际香云随步起谩记得汉宫仙掌亭亭明月底冰弦写怨更多情骚人恨枉赋芳兰幽芷春思远谁叹赏国香风味相将共岁寒伴侣小窗净沉烟熏翠袂幽梦觉涓涓清露一枝灯影里', '楚江边上，湘妃忽然相见，无言地洒下清泪。淡然的春意。空自独倚东风，芳心寄给谁？凌波之路清冷，秋意无边；香云随着脚步升起。白白记得汉宫的仙掌，亭亭立在明月底下。
冰弦写怨更多情，骚人的恨，白白赋写芳兰幽芷。春思遥远，谁来叹赏这国色的风味？要结为岁寒的伴侣，小窗洁净，沉香熏着翠袖。幽梦醒来，涓涓清露，一枝花在灯影里。', 'public-domain'),
  ('songci300', 233, '瑞鹤仙·绀烟迷雁迹', 'songci-sc-240', '绀烟迷雁迹渐碎鼓零钟街喧初息风檠背寒壁放冰蜍飞到丝丝帘隙琼瑰暗泣念乡关霜芜似织漫将身化鹤归来忘却旧游端的欢极蓬壶蕖浸花院梨溶醉连春夕柯云罢弈樱桃在梦难觅劝清光乍可幽窗相伴休照红楼夜笛怕人间换谱伊凉素娥未识', '青红烟霭遮住雁的踪迹，渐渐鼓声碎、钟声零落，街市喧闹刚停。风灯背靠寒壁。让冰蟾般的月亮飞进来，一丝丝穿过帘缝。美玉暗暗哭泣。想乡关那边，霜后的荒草像织。空自化作仙鹤归来，却忘了旧游的究竟。
欢乐到极处。蓬壶的荷花浸泡，花院的梨花开溶，醉连着春夜。斧柄烂了棋也下完。樱桃还在，梦却难寻。劝月光，宁可只在幽窗前相伴，不要照那红楼夜笛。怕人间换了伊凉曲谱，嫦娥不认得。', 'public-domain'),
  ('songci300', 234, '天香·孤峤蟠烟', 'songci-sc-241', '孤峤蟠烟层涛蜕月骊宫夜采铅水汛远槎风梦深薇露化作断魂心字红瓷候火还乍识冰环玉指一缕萦帘翠影依稀海天云气几回殢娇半醉剪春灯夜寒花碎更好故溪飞雪小窗深闭荀令如今顿老总忘却尊前旧风味谩惜余薰空篝素被', '孤岛上烟雾盘旋，层层波涛退出月光，骊宫夜里采来铅水。远汛的槎风，深梦里蔷薇露水，化做断魂的心字香。红瓷守着火候，才初次认识冰环玉指。一缕香萦绕帘上的翠影，依稀是海天的云气。
几回她娇困半醉，剪着春灯，夜寒里灯花碎落。更好的是故溪飞雪，小窗深深关闭。荀令如今忽然老了，都忘了杯前旧日的风味。白白怜惜余香，空着香笼和素被。', 'public-domain'),
  ('songci300', 235, '眉妩·渐新痕悬柳', 'songci-sc-242', '渐新痕悬柳淡彩穿花依约破初暝便有团圆意深深拜相逢谁在香径画眉未稳料素娥犹带离恨最堪爱一曲银钩小宝帘挂秋冷千古盈亏休问叹慢磨玉斧难补金镜太液池犹在凄凉处何人重赋清景故山夜永试待他窥户端正看云外山河还老尽桂花影', '新的月痕渐渐挂在柳上，淡淡的光彩穿过花间，隐约划破初暗的暮色。既有团圆的意味，就深深下拜——可相逢时谁在香径？眉还未画稳，料想嫦娥还带着离恨。最可爱的是那一弯小小的银钩，宝帘挂在秋寒里。
千古的盈亏不必问，可叹白白磨着玉斧，也难补圆金镜。太液池还在，凄凉之处，谁来重写清景？故山的夜长，且等它从门窗端正地照进来。看那云外的山河，桂花影也老尽了。', 'public-domain'),
  ('songci300', 236, '齐天乐·一襟余恨宫魂断', 'songci-sc-243', '一襟余恨宫魂断年年翠阴庭树乍咽凉柯还移暗叶重把离愁深诉西窗过雨怪瑶佩流空玉筝调柱镜暗妆残为谁娇鬓尚如许铜仙铅泪似洗叹携盘去远难贮零露病翼惊秋枯形阅世消得斜阳几度余音更苦甚独抱清商顿成凄楚谩想薰风柳丝千万缕', '一襟余恨，宫魂已断，年年栖在庭树的翠阴里。忽而在凉枝上呜咽，忽而移到暗叶间，重新把离愁深深倾诉。西窗下过雨。奇怪那玉佩在空中流过、玉筝在调柱。镜已暗、妆已残，她为谁还把鬓发弄得这样娇美？
铜人的铅泪像洗过一样，可叹它被携盘带走远了，难以贮存点滴露水。病翅惊秋，枯形阅世，还能经得几度斜阳？余音更苦。为什么独抱清商之调，顿时变得凄楚？白白想起和暖的风，那千万缕柳丝。', 'public-domain'),
  ('songci300', 237, '长亭怨慢·泛孤艇', 'songci-sc-244', '泛孤艇东皋过遍尚记当日绿阴门掩屐齿莓阶酒痕罗袖事何限欲寻前迹空惆怅成秋苑自约赏花人别后总风流云散水远怎知流水外却是乱山尤远天涯梦短想忘了绮疏雕槛望不尽冉冉斜阳抚乔木年华将晚但数点红英犹识西园凄婉', '泛着孤舟，把东皋走遍。还记得当日，绿荫下门扉掩着。木屐的齿印在苔阶上，酒痕在罗袖上，旧事有多少。想寻找前迹，只落得惆怅，已成了秋天的园苑。当年相约赏花的人，别后总是风流云散。
水远。怎知流水之外，还有乱山更远。天涯梦短，想她已忘了那雕花门窗。望不尽冉冉斜阳，抚着乔木，年华将晚。只有几点红花，还记得西园的凄婉。', 'public-domain'),
  ('songci300', 238, '高阳台·接叶巢莺', 'songci-sc-245', '接叶巢莺平波卷絮断桥斜日归船能几番游看花又是明年东风且伴蔷薇住到蔷薇春已堪怜更凄然万绿西泠一抹荒烟当年燕子知何处但苔深韦曲草暗斜川见说新愁如今也到鸥边无心再续笙歌梦掩重门浅醉闲眠莫开帘怕见飞花怕听啼鹃', '密叶里黄莺筑巢，平波卷着柳絮，断桥斜阳下归来的是船。还能游几番？再看花又要等明年。东风且伴着蔷薇留住吧，到蔷薇开时，春天已值得怜惜。更凄然的是，万绿丛中的西泠，只有一抹荒烟。
当年的燕子知道在哪里？只有韦曲苔深，斜川草暗。听说新愁，如今也到了鸥鸟身边。无心再续笙歌的梦，掩上重门，浅醉闲眠。不要开帘——怕见飞花，怕听杜鹃。', 'public-domain'),
  ('songci300', 239, '解连环·楚江空晚', 'songci-sc-247', '楚江空晚怅离群万里恍然惊散自顾影欲下寒塘正沙净草枯水平天远写不成书只寄得相思一点料因循误了残毡拥雪故人心眼谁怜旅愁荏苒谩长门夜悄锦筝弹怨想伴侣犹宿芦花也曾念春前去程应转暮雨相呼怕蓦地玉关重见未羞他双燕归来画帘半卷', '楚江空阔天晚，惆怅离群万里，恍然惊散。自顾身影，想落下寒塘，正是沙净草枯、水平天远。写不成书信，只能寄去一点相思。料想因循耽误了，像苏武残毡拥雪那样，辜负故人的心眼。
谁怜旅愁荏苒？空自对着长门夜静，锦筝弹怨。想同伴还宿在芦花里，也曾想过春前就该转回程。暮雨中互相呼唤，怕忽然在玉关重见。那时也不羞于看那双燕归來，画帘半卷。', 'public-domain'),
  ('songci300', 240, '疏影·碧圆自洁', 'songci-sc-248', '碧圆自洁向浅洲远渚亭亭清绝犹有遗簪不展秋心能卷几多炎热鸳鸯密语同倾盖且莫与浣纱人说恐怨歌忽断花风碎却翠云千叠回首当年汉舞怕飞去谩皱留仙裙摺恋恋青衫犹染枯香还叹鬓丝飘雪盘心清露如铅水又一夜西风吹折喜静看匹练秋光倒泻半湖明月', '碧圆的荷叶自然清洁，向着浅洲远渚，亭亭清绝。还有像遗落的玉簪，不肯展开秋心，能卷住多少炎热？鸳鸯密语，如同倾盖相交，且不要对浣纱人说。怕怨歌忽被花风吹断，碎了千叠翠云。
回想当年汉宫的舞，怕它飞去，白白皱起留仙裙的褶。恋恋的青衫，还染着枯香，又叹鬓发如飘雪。盘心的清露像铅水，又一夜被西风吹折。喜的是静静看那匹练般的秋光，倒泻出半湖明月。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 241, '声声慢·寻寻觅觅', 'poems-gz10-09', '寻寻觅觅冷冷清清凄凄惨惨戚戚乍暖还寒时候最难将息三杯两盏淡酒怎敌他晚来风急雁过也正伤心却是旧时相识满地黄花堆积憔悴损如今有谁堪摘守着窗儿独自怎生得黑梧桐更兼细雨到黄昏点点滴滴这次第怎一个愁字了得', '苦苦地寻找寻觅，四处冷冷清清，心中凄凄惨惨悲悲戚戚。天气忽暖忽冷的时候，最难调养身体。三杯两盏淡酒，怎么能抵挡傍晚的急风！大雁飞过，正令人伤心，却原来是旧时相识。满地菊花堆积，我如此憔悴，如今有谁还能采摘？守着窗子，独自一个人怎么才能挨到天黑！梧桐树又加上细雨，到黄昏时分，点点滴滴。这情景，一个愁字怎么能说得尽！', 'academic'),
  ('songci300', 242, '念奴娇·萧条庭院', 'songci-sc-250', '萧条庭院又斜风细雨重门须闭宠柳娇花寒食近种种恼人天气险韵诗成扶头酒醒别是闲滋味征鸿过尽万千心事难寄楼上几日春寒帘垂四面玉阑干慵倚被冷香消新梦觉不许愁人不起清露晨流新桐初引多少游春意日高烟敛更看今日晴未', '庭院萧条，又是斜风细雨，重门该关上了。宠柳娇花，寒食将近，种种恼人的天气。险韵的诗写成，扶头的酒醒来，另有一番闲滋味。征鸿过尽，万千心事难以寄去。
楼上几日春寒，四面垂帘，玉栏杆也懒得去倚。被子冷了、香气消了，新梦醒来，不许愁人不起身。清露在晨光里流，新桐刚抽芽，有多少游春的意兴！太阳升高、雾气收敛，再看看今天晴不晴？', 'public-domain'),
  ('songci300', 243, '永遇乐·落日熔金', 'songci-sc-251', '落日熔金暮云合璧人在何处染柳烟浓吹梅笛怨春意知几许元宵佳节融和天气次第岂无风雨来相召香车宝马谢他酒朋诗侣中州盛日闺门多暇记得偏重三五铺翠冠儿捻金雪柳簇带争济楚如今憔悴风鬟霜鬓怕见夜间出去不如向帘儿底下听人笑语', '落日像熔化的金子，暮云如合拢的璧玉，人在哪里？柳色被浓烟染过，笛声吹着《梅花落》的怨曲，春意能有多少？元宵佳节，天气融和，难道就不会有风雨？有人用香车宝马来相邀，我谢绝了酒朋诗侣。
中州盛时的日子，闺中多有闲暇，记得特别看重正月十五。铺翠的冠儿、捻金的雪柳，簇带争着齐整。如今憔悴，风鬟霜鬓，怕在夜里出去。不如守在帘子底下，听别人笑语。', 'public-domain'),
  ('songci300', 244, '一剪梅·红藕香残玉簟秋', 'songci-sc-252', '红藕香残玉簟秋轻解罗裳独上兰舟云中谁寄锦书来雁字回时月满西楼花自飘零水自流一种相思两处闲愁此情无计可消除才下眉头却上心头', '红藕香残，玉席生凉，已是秋天。轻轻解开罗裳，独自登上兰舟。云中谁寄书信来？雁字归来时，月满西楼。
花自飘零，水自流去。同一种相思，分成两处的闲愁。这份情没有办法消除，刚下了眉头，又上了心头。', 'public-domain'),
  ('songci300', 245, '醉花阴·薄雾浓云愁永昼', 'songci-sc-253', '薄雾浓云愁永昼瑞脑消金兽佳节又重阳玉枕纱厨半夜凉初透东篱把酒黄昏后有暗香盈袖莫道不销魂帘卷西风人比黄花瘦', '薄雾浓云，整日发愁；龙脑香在铜兽香炉里渐渐烧尽。又到重阳佳节，玉枕纱帐，半夜里凉意初透。
黄昏后在东篱下举杯，有暗香盈袖。不要说不会消魂——西风卷起帘子，人比菊花还瘦。', 'public-domain'),
  ('songci300', 246, '凤凰台上忆吹箫·香冷金猊', 'songci-sc-254', '香冷金猊被翻红浪起来慵自梳头任宝奁尘满日上帘钩生怕离怀别苦多少事欲说还休新来瘦非干病酒不是悲秋休休这回去也千万遍阳关也则难留念武陵人远烟锁秦楼惟有楼前流水应念我终日凝眸凝眸处从今又添一段新愁', '香炉里的香冷了，锦被翻起红浪，起身后懒懒地不想梳头。任凭宝奁积满灰尘，太阳升上帘钩。最怕离怀别苦，多少事想说又停住。近来瘦了，不是因为病酒，也不是悲秋。
算了算了！这一去，唱千万遍《阳关》，也还是留不住。想那武陵人已远，烟雾锁住秦楼。只有楼前的流水，应该念我终日凝望。凝望的地方，从今又添了一段新愁。', 'public-domain'),
  ('songci300', 247, '武陵春·风住尘香花已尽', 'songci-sc-255', '风住尘香花已尽日晚倦梳头物是人非事事休欲语泪先流闻说双溪春尚好也拟泛轻舟只恐双溪舴艋舟载不动许多愁', '风停了，尘土里带着花香，花已落尽；日头已高，还懒得梳头。景物依旧而人事全非，事事都完了；想说话，泪先流下来。
听说双溪的春色还好，也打算去泛轻舟。只怕双溪那小小的舴艋舟，载不动我这么多愁。', 'public-domain'),
  ('songci300', 248, '点绛唇·蹴罢秋千', 'songci-sc-342', '蹴罢秋千起来慵整纤纤手露浓花瘦薄汗轻衣透见客入来袜刬金钗溜和羞走倚门回首却把青梅嗅', '荡完秋千，起身懒得揉一揉纤细的手。露水浓、花儿瘦，一层薄汗湿透了轻衣。
忽然见有客人进来，她慌忙提袜而走，金钗滑落。含羞跑开，又在门边回头张望，假装嗅着手里的青梅。', 'public-domain'),
  ('songci300', 249, '醉落魄·波上春风', 'songci-sc-266', '波上春风画船明月人归后画楼闲倚东风久芳草王孙知他甚时又绿杨影里海棠亭畔红杏梢头拟歌先敛欲笑还颦最断人肠', '水波上吹着春风，画船明月中人已归去之后。久在画楼上闲倚着东风。芳草萋萋，远行的王孙，不知他什么时候才回。
绿杨的影里，海棠亭畔，红杏的枝头。想要歌唱先敛住神情，想要笑又皱起眉头，最是断人肝肠。', 'public-domain'),
  ('songci300', 250, '菩萨蛮·风柔日薄春犹早', 'songci-sc-267', '风柔日薄春犹早夹衫乍著心情好睡起觉微寒梅花鬓上残故乡何处是忘了除非醉沉水卧时烧香消酒未消', '风轻柔，日光淡薄，春天还早，刚换上夹衫，心情很好。睡醒觉得有些微寒，鬓边的梅花已经残了。
故乡在什么地方？要忘记除非醉倒。睡时点起了沉香，如今香已烧尽，酒意还没消。', 'public-domain'),
  ('songci300', 251, '忆秦娥·临高阁', 'songci-sc-268', '临高阁乱山平野烟光薄烟光薄栖鸦归后暮天闻角断香残酒情怀恶西风催衬梧桐落梧桐落又还秋色又还寂寞', '登上高阁，乱山平野之上烟气淡薄。烟气淡薄，归巢的乌鸦落下之后，暮色里传来号角声。
残香剩酒，心情很坏，西风催促着梧桐落叶。梧桐落叶，又是秋色，又是寂寞。', 'public-domain'),
  ('songci300', 252, '孤雁儿·藤床纸帐朝眠起', 'songci-sc-269', '藤床纸帐朝眠起说不尽无佳思沉香断续玉炉寒伴我情怀如水笛声三弄梅心惊破多少春情意小风疏雨萧萧地又催下千行泪吹箫人去玉楼空肠断与谁同倚一枝折得人间天上没个人堪寄', '藤床纸帐里早晨睡醒起来，说不尽没有好心情。沉香断断续续，玉炉已冷，陪伴着我如水的情怀。笛声吹起《梅花三弄》，把梅心都惊破了，牵动多少春天的情意。
小风疏雨萧萧地落，又催下千行眼泪。吹箫的人去了，玉楼空着，肝肠寸断又与谁同倚？折得一枝梅花，人间天上，却没有人可以寄。', 'public-domain');
